quests[27027] = { id = 27027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urtümlicher Schlag", description = "Ich weiß, dass Ihr geholfen habt, Camp Narache vor den Borstennacken zu beschützen. Wir werden jeden Hammer und alles Glück, das wir bekommen können, brauchen. Erlaubt mir, Euch eine einfache Kampftechnik beizubringen, die Euch helfen wird.\n\n'Urtümlicher Schlag' sollte Euch dabei helfen, Eure Feinde schneller zu schlagen. Versucht es selbst.", sourceObjective = "Lernt von Meela Morgenwandler 'Urtümlicher Schlag'. Findet eine Trainingsattrappe in Camp Narache und übt 'Urtümlicher Schlag' 3 Mal.", sourceObjectiveStatus = "unverified-source-field" }
quests[27028] = { id = 27028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hornissenjagd", description = "Wir suchen hier immer nach neuem Wild. Daryl mag seine Eber ja lieben, aber der Rest von uns bevorzugt etwas exotischere Dinge.\n\nNun, ich würde niemals behaupten, dass es gut war, den Loch trockenzulegen, aber es gab einen Lichtblick. Der sumpfige Untergrund hat neue Beute hervorgebracht: Hornissen!\n\nUnd obendrein noch riesige Hornissen. Nicht viele Jäger haben sich mit so riesigen Insekten gemessen. Das ist ziemlich neu.\n\nIch möchte gerne, dass Ihr es versucht - ich biete Euch eine Wette an. Bringt mir einige dieser wunderschön glänzenden Flügeln von ihnen und ich bezahle Euch.", sourceObjective = "Erbeutet 6 glasige Hornissenflügel.", progress = "Wie geht's mit den Hornissen?", completion = "Wunderbare Exemplare habt Ihr da! Hier ist mein Einsatz, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[27029] = { id = 27029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geißel heilen", description = "Viel wirksamer, als eine Welle der Geißel nach der anderen zu töten, wäre es, einen Weg zu finden, wie man lebende Kreaturen davor bewahrt, sich in sie zu verwandeln. Ich habe eine Idee für ein tolles Pulver. Wenn man es einatmet, könnte es den ganzen Prozess unterbinden.\n\nIch benötige verwitterte Hauer von den untoten Stachelebern hier, um dieses Pulver herzustellen. Bringt mir eine ausreichende Menge und wir sind vielleicht in der Lage, das Wachstum der Geißel endgültig aufzuhalten.", sourceObjective = "Besorgt 20 verwitterte Hauer.", progress = "Habt Ihr die Hauer?", completion = "Ich bin davon überzeugt, dass diese Substanz uns in Zukunft weitere Kopfschmerzen ersparen wird. Danke, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27030] = { id = 27030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Handvoll Fuchsschwänze", description = "Wir haben in letzter Zeit mehr Füchse hier in den Hügeln gesehen. Sie sind gerissene Wesen. Sie sind ein guter Test für die Fähigkeiten eines Jägers - und sie bringen einen schönen Profit!\n\nWegen ihrer Schwänze, <mein Freund/meine Liebe>. Die sind schön und buschig - man kann sie an seinen Gürtel hängen, um Flöhe abzuwehren, oder man kann mit ihnen die Handschuhe eines modebewussten Edelmannes füttern.\n\nAber ich plappere nur daher. Ich bin zwar kein Goblin und die Spannung liegt in der Jagd. Doch wenn Ihr mir ein paar Fuchsschwänze bringt, werde ich Euch gerne dafür bezahlen. Ihr findet die Füchse nördlich der Jagdhütte in den unteren Waldländern.", sourceObjective = "Erbeutet 7 flauschige Fuchsschwänze.", progress = "Was habt Ihr für mich?", completion = "Ahh, seht Ihr? Waren der feinsten Qualität. Das habt Ihr gut gemacht, die zu besorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27031] = { id = 27031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verrückt nach Flügeln", description = "Ich habe die Nase von Gyrokoptern voll. Klar, sie erfüllen ihren Zweck, aber seit wann hat das einem Gnom jemals gereicht? Ich will richtig fliegen, mit FLÜGELN!\n\nIch beobachte seit Jahren Vögel und versuche, hinter das Geheimnis zu kommen, wie man eine Maschine baut, die genau wie sie fliegen kann. Dieses elegante Aufschwingen und Herabstoßen, der Wind, der über die Flügel streicht ... ahh.\n\nIhr! Ihr könnt mir helfen. Ich brauchte die besten Flugfedern, die ihr auftreiben könnt. Die goldenen Adler, die in der Nähe der Jagdhütte kreisen, wären eine ausgezeichnete Wahl.", sourceObjective = "Besorgt 3 makellose Flugfedern von Goldadlern.", progress = "Die besten Federn sind gerade gut genug!", completion = "Wunderschön. Ihr habt einen Blick für Qualität!\n\nWir sind auf der gleichen Wellenlänge! Offensichtlich könnt Ihr Euch für Flügel und Federvieh begeistern, also könntet Ihr mir noch weiter helfen...", sourceObjectiveStatus = "unverified-source-field" }
quests[27032] = { id = 27032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein schräger Vogel", description = "Ich habe meine Traummaschine fast perfektioniert: Den Himmelsschreiter! Den weltweit ersten fliegenden Roboschreiter! Aber, na ja�\n\nAls ich in meinem geheimen Höhlenlabor letzte Hand anlegen wollte, wurden meine anderen Schöpfungen, äh, eifersüchtig. Mechanischen Vögeln eine Persönlichkeit zu geben, war wahrscheinlich von Anfang an eine schlechte Idee, aber daran ist nun nichts mehr zu ändern.\n\nIch brauche das supermechanische Robodings aus dem ursprünglichen Himmelsschreiter, wenn ich ihn neu bauen will! Bitte dringt in die Höhle vor und bergt es für mich!", sourceObjective = "Findet den verrosteten Himmelsschreiter in der Eisenschwingenhöhle.", completion = "<Der Himmelsschreiter sitzt schweigend da, seine Chance, davonzufliegen, ist vertan. Eine auffällige Klappe an seiner Vorderseite trägt die Aufschrift \"SRD\".>", sourceObjectiveStatus = "unverified-source-field" }
quests[27033] = { id = 27033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herz der Himmelsstreiter", description = "Ihr öffnet die Klappe und findet ein beeindruckendes, mechanisches Gerät, das an einige Kabel, Zahnräder und wer-weiß-was noch angeschlossen ist.\n\nEs lässt sich ohne Schwierigkeiten lösen. Zeit, es zu Bingles zurückzubringen.", sourceObjective = "Bringt Bingles Blastenheimer in der Jagdhütte der Weltenwanderer das supermechanische Robodings.", completion = "Perfekt! Jetzt habe ich die perfekte Flügelbalance und habe alle Teile, die ich benötige. Alles, was noch fehlt, ist ein Pilot.", sourceObjectiveStatus = "unverified-source-field" }
quests[27034] = { id = 27034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Er ist in dem Alter", description = "ich baue den Himmelsschreiter nicht für mich, {name}. Ich baue ihn nicht mal für die Gnomwelt. Ich möchte, dass mein Sohn derjenige ist, der ihn fliegt.\n\nIch bin alt und meine Reflexe sind nicht mehr das, was sie mal waren. Aber mein Junge Ando könnte der beste Pilot werden, den Azeroth je gesehen hat, wenn er nur seine Teenager-Launenhaftigkeit ablegen würde!\n\nEr sitzt draußen am See und starrt den ganzen Tag den Himmel an. Irgendetwas bedrückt ihn, aber er weigert sich, mit seinem Vater darüber zu sprechen. Ich bin mit meinem Latein am Ende!\n\nBitte, {name}, könntet Ihr nicht mit ihm reden? Sagt ihm, ich brauche ihn, um den Himmelsschreiter zu fliegen.", sourceObjective = "Sprecht mit Ando Blastenheimer auf der Ostseite des Loch.", completion = "Mein Vater und seine albernen Erfindungen sind mir egal! Das ist alles nur Unsinn!", sourceObjectiveStatus = "unverified-source-field" }
quests[27035] = { id = 27035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stellung beziehen", description = "Schaut sie Euch an. Der Schattenhammer hat dieses Land ruiniert!\n\nDieser Kult hat diesen Kataklysmus ausgelöst, den Steinwerkdamm zerstört und den ganzen Loch trockengelegt. Und jetzt laufen sie in den Trümmern herum, als ob hier ihr Zuhause wäre!\n\nWenn es in dieser Welt Gerechtigkeit gäbe, würde jemand in ihr Lager marschieren und ihr Artefakt in Stücke brechen. Aber ich bin zu schwach, um auch nur an einen Versuch zu denken.\n\nUnd niemand hat genug Mut dazu! Nicht einmal Ihr! Seht Ihr? Es ist alles so sinnlos...", sourceObjective = "Zerstört den Zwielichtumweltgestalter in der Mitte des Schattenhammerlagers.", completion = "Ihr habt es getan! Ihr habt es wirklich getan! Ihr habt gegen sie gekämpft und gewonnen!\n\nEs besteht doch noch Hoffnung...", sourceObjectiveStatus = "unverified-source-field" }
quests[27036] = { id = 27036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vyrins Rache", description = "Ihr seid nicht zufällig daran interessiert, es unserem ach so kühnen Kühnen ein wenig heimzuzahlen? Es schmerzt mich, das zu sagen, aber Daryl hat ein gewisses Talent.\n\nVor einem Jahr war ein großer Bär das Ziel der Jagdhütte der Weltenwanderer, aber keiner der Jäger hatte Glück mit ihm. Also dachte sich Daryl, er könnte sich mal an ihm versuchen. Das einzige, was er nach seinem Versuch vorweisen konnte, war die hässliche Narbe über seinem Auge.\n\nErlegt den Bären und ich bin mir sicher, dass sogar Daryl mal sprachlos wäre.\n\nAlte Rußtatze, der Bär, hält sich irgendwo in der Nähe seines Baus nördlich von hier auf.", sourceObjective = "Tötet alte Rußtatze und bringt seinen Kopf an Euch.", progress = "Ah, {name}! Schon wieder hier? Zweifelsohne wart Ihr wieder auf der Jagd! Keine Sorge, es ist nicht schlimm, wenn Ihr ein paar Rückschläge einstecken müsst, davon werdet Ihr auf lange Sicht nur besser.\n\n... viel schlechter könntet Ihr ja sowieso nicht mehr werden...", completion = "Äh... was ist das da? Ein Bärenschädel, wie es aussieht.\n\n<Er fährt unbewusst mit einem Finger an seiner Narbe entlang>\n\nNun, das ist eine ziemlich interessante Beute, die Ihr da habt. Kann eigentlich nicht der Bär von damals sein...\n\n<Seine Stimme verliert sich, und er fängt sichtbar an zu zittern.>\n\nOh, nehmt das weg, nehmt es weg! Schafft dieses grausige Ding hier raus!", sourceObjectiveStatus = "unverified-source-field" }
quests[27037] = { id = 27037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vyrins Rache", description = "Licht! Bringt solche Dinge nicht in die Jagdhütte... das ist unhygienisch, unaussprechlich, un... un... unhygienisch!\n\nBringt es bitte einfach nur raus hier, ja? Niemand will Eure kleine blutige Trophäe sehen, aber wirklich nicht!", sourceObjective = "Bringt den Kopf der alten Rußtatzes zu Vyrin Flinkwind in die Jagdhütte der Weltenwanderer.", progress = "Sehr gute Arbeit, {name}! Wir haben's ihm wirklich gezeigt! Hier, gebt mir den Kopf, ich werde mich darum kümmern.", completion = "Danke für Eure Hilfe bei meinem kleinen Plan, {name}. Seit Monaten wollte ich es diesem hochnäsigen, eingebildeten Jungen schon heimzahlen und ich würde meinen, es hat so richtig gut geklappt! Hier, nehmt das, Ihr habt es Euch verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[27038] = { id = 27038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fehlende Teile", description = "<Der Unteroffizier wendet seine Aufmerksamkeit Euch zu.>\n\nHört zu, wenn Ihr helfen wollt, dass alles hier etwas schneller geht, dann haltet mir Flintlocke vom Leib. Eine ganze Ladung Belagerungsmaschinenteile ist verlegt worden und jetzt über das ganze Dock verteilt.\n\nSammelt die fehlenden Teile auf und bringt sie zu Flintlocke, damit er den Bau beenden kann. Er ist auf der anderen Seite der Straße und wartet.", sourceObjective = "Hebt 5 fehlende Teile im Hafen von Sturmwind auf.", progress = "Wat is'?\n\nMeine Teile. Wo sind sie? Man kann keinen Panzer ohne Teile bauen!\n\nUnd wenn, wäre er zu klein. Un' ziemlich inner-fektiv.", completion = "<Flintlocke wühlt gierig durch die Maschinenteile und wirft einige ausgewählte Stücke über die Schulter.>\n\nJau, hier is' das Zeugs ja. <Er steckt seinen Kopf tief in eine der Kisten.>\n\nAber wo ist mein Pulver? Alles ist hier, nur nicht das Pulver. Ich brauche Sprengstoff, Mann!\n\nSagt dem König: Keine Macht, wenn's nicht kracht. Ich brauch' 'n paar Kabummplosionen, sonst verlass ich den Hafen nich'.", sourceObjectiveStatus = "unverified-source-field" }
quests[27039] = { id = 27039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter Feinden", description = "Wisst Ihr, warum Mortuus 'nub' an Euren Namen anhängt, {name}? Weil er ein inkompetenter Kriecher ist, der kaum aus seinem übergroßen Helm hervorschauen kann. 'NUB' ist Eure Bezeichnung. Ihr seid jetzt nämlich Teil des NEUEN UNTERSTÄDTER BATAILLONS.\n\nDoch genug der Witze! Ich habe Todespirscherin Yorick vor zwei Tagen auf eine Überwachungsmission geschickt. Ihr Ziel war es, Informationen über die Gilnearische Befreiungsfront zu sammeln und zurückzukehren. Jetzt habe ich schon drei Tage lang nichts mehr von ihr gehört.\n\nGeht nach Südwesten zum Ivarfeld und sucht nach Yorik, {name}.", sourceObjective = "Findet Todespirscherin Yorick auf dem Ivarfeld im Silberwald.", completion = "Belmont wird ein bisschen nervös und schon schickt er irgendeinen Grünschnabel, um nach mir zu suchen? Hört zu, ich habe das Ivarhaus aus diesem Plumpsklo heraus drei Tage lang observiert. Eure Anwesenheit gefährdet die gesamte verdammte Mission!\n\nIch habe keine Zeit für Erklärungen. Wir müssen jetzt handeln. Sonst war alles umsonst.", sourceObjectiveStatus = "unverified-source-field" }
quests[27040] = { id = 27040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entschlüsselung leichtgemacht", description = "Wir haben nicht die Werkzeuge, um diese chiffrierten Pläne zu entschlüsseln. Doch der Schattenhammer hat sie.\n\nWärt Ihr so gut, mit den Plänen dort hinaufzugehen und sie durch die Einweg-Dechiffrierungsmaschine laufen zu lassen?", sourceObjective = "Entschlüsselt 6 Pläne.", sourceObjectiveStatus = "unverified-source-field" }
quests[27041] = { id = 27041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entschlüsselung leichtgemacht", description = "Wir haben nicht die Werkzeuge, um diese chiffrierten Pläne zu entschlüsseln. Doch der Schattenhammer hat sie.\n\nWärt Ihr so gut, mit den Plänen dort hinaufzugehen und sie durch die Einweg-Dechiffrierungsmaschine laufen zu lassen?", sourceObjective = "Entschlüsselt 6 Pläne.", sourceObjectiveStatus = "unverified-source-field" }
quests[27042] = { id = 27042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mächte des Feuers, des Wassers und der Luft", description = "Habt Ihr da oben diesen plappernden Idioten gehört? Das ist kein Geringerer als Haethen Kaul, ihr Anführer.\n\nDie Macht hat ihn in den Wahnsinn getrieben. Er entzieht sie den gebundenen Elementaren, was ihn nahezu unbesiegbar macht.\n\nDie einzige Chance, wie Ihr ihn im Kampf besiegen könnt, besteht darin, die Elementare zu töten und jeweils ihren Zauberschutz erlangen. Das sollte Euch vor Haethens Magie beschützen.\n\nNun, zumindest vor einem Großteil davon.", sourceObjective = "Erhaltet den Feuerzauberschutz, Wasserzauberschutz und Windzauberschutz und tötet dann Haethen Kaul.", progress = "Ihr müsst Euch schon mehr anstrengen, Kumpel!\n\nUnd jetzt hoch da mit Euch und erledigt Eure Aufgabe. Oder muss ich es selbst tun?", completion = "Das nenne ich Kampfgeist! Ein Übel weniger in dieser Welt, vor dem die Kleinen sich fürchten müssen, wenn sie abends ins Bett gehen.\n\nUnd wir müssen uns auch keine Sorgen mehr um ihn machen!\n\nNun, dann lasst mich mal nachsehen. Irgendwo in unseren Kisten haben wir sicher eine passende Belohnung für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[27043] = { id = 27043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mächte des Feuers, des Wassers und der Luft", description = "Habt Ihr da oben den Mann und sein unaufhörliches Geschrei gehört? Das ist Haethen Kaul, ihr Anführer.\n\nEs ist kein Geheimnis, dass die Macht, die er den gebundenen Elementaren entzieht, ihn in den Wahnsinn getrieben hat. Leider macht sie ihn auch nahezu unbesiegbar.\n\nWenn Ihr gegen ihn kämpfen wollt, müsst Ihr erst die Elementare töten und jeweils ihren Zauberschutz erlangen. Das sollte Euch vor Haethens Magie beschützen.\n\nNun, zumindest vor einem Großteil davon.", sourceObjective = "Erhaltet den Feuerzauberschutz, Wasserzauberschutz und Windzauberschutz und tötet dann Haethen Kaul.", completion = "Eine beeindruckende Vorstellung Eures Kampfgeschicks, {class}.\n\n\n\nIch glaube, dass Ihr Euch eine Belohnung verdient habt. Etwas, das einem mächtigen Mann wie Euch angemessen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27044] = { id = 27044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sorgen der Bauern", description = "Ich möchte noch nicht zur Burg zurückkehren. Würdet Ihr mir bei etwas helfen?\n\nEinige der hiesigen Bauern haben vor Kurzem beim König eine Eingabe gemacht, bei der es um vermisstes Nutzvieh ging. Mein Vater hat versprochen, dass jemand der Sache nachgeht, aber die Stadtwache ist so ausgelastet, dass das Wochen dauern würde.\n\nIch dachte, ich könnte doch helfen! Es wird den Bauern Mut machen, wenn sie sehen, dass jemand sich darum kümmert, besonders, wenn es jemand der königlichen Familie ist. Außerdem geht es ja nur um paar vermisste Kühe. Nichts Gefährliches.\n\nBringt mich hier in der Stadt zu Bauer Wollerton!", sourceObjective = "Begleitet Prinz Anduin zu Bauer Wollerton auf Wollertons Bauernhof in Sturmwind. Wenn er nicht mehr an Eurer Seite ist, findet Ihr ihn in Burg Sturmwind.", progress = "Äh, ja?", completion = "<Als er den Prinzregenten sieht, fällt Bauer Wollerton ungeschickt auf ein Knie.>\n\nEu - Eu - Eure Hoheit!", sourceObjectiveStatus = "unverified-source-field" }
quests[27045] = { id = 27045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lauschangriff", description = "Der Anführer der Gilnearischen Befreiungsfront, Darius Crowley, hält jetzt schon seit drei Tagen ein Treffen mit einem anderen Worgen in diesem Landhaus ab. Ich bin mir nicht sicher, was da los ist, aber wir müssen in das Haus gelangen und einen guten Platz finden, von dem aus wir sie belauschen können.\n\nJetzt oder nie, {race}. Eine zweite Chance werden wir wohl kaum bekommen.\n\nAber falls ich es nicht schaffe, müsst Ihr mir versprechen, zur Kommandozentrale der Verlassenen zurückzukehren und Belmont von unseren Erkenntnissen zu berichten.", sourceObjective = "Betretet das Landhaus auf dem Ivarfeld und sucht oben nach einem geeigneten Versteck. Belauscht dann Lord Darius Crowley.", completion = "Oh je, arme Yorick! Ich kannte sie gut, {name}. Eine Assassine mit unvergleichbarem Mut…\n\nAlso, was geht dort vor sich? Was habt Yorick und Ihr herausgefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[27046] = { id = 27046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bohrende Angst", description = "Die Tunnelgräber haben den Fels befallen und fressen die ganze Zeit daran; eines Tages wird unser Heim zusammenbrechen. Für jeden, den man tötet, brechen zweimal so viele hervor und wir müssen immer weiterkämpfen. Sie müssen ausgerottet werden.\n\nGeht zu den Bruchtiefen und vernichtet alle Würmer, die Ihr finden könnt.", sourceObjective = "Tötet 10 Schleifwürmer.", completion = "Ihr führt einen Krieg, den wir nicht führen können. Danke für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[27047] = { id = 27047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Partikel", description = "Einige der seltensten Kristalle entstehen an den gefährlichsten Orten. In den Bruchtiefen werdet Ihr Painitformationen finden. Das ist viel besser als das Gold, das Eure Rassen so schätzen.\n\nDa Ihr ein fleischliches Wesen von kleinem Wuchs seid, könnt Ihr die Bruchtiefen betreten und Painitpartikel für mich holen. Würdet Ihr Euch dieser Gefahr für mich aussetzen?", sourceObjective = "Holt 10 Painitpartikel.", progress = "Painit ist für uns eins der wertvollsten Materialien, besonders weil wir die meisten Vorkommen nicht selbst erreichen können.", completion = "Gut gemacht, {race}. Die werden gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27048] = { id = 27048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untergrundwirtschaft", description = "Hey! Ich versuche, einige dieser Kristalle zu sammeln. Die Elementare zahlen gut für das Zeug... wenn Ihr mir helft, die ganzen verschiedenen Sorten zu sammeln, bekommt Ihr einen Anteil vom Gewinn.\n\nBenutzt diese Bomben, um Teile aus den größeren Kristallformationen herauszusprengen.\n\nIch hab' die dumme Angewohnheit, mit Sprengstoff ein wenig zu dick aufzutragen. Nehmt Euch vor dem Rückstoß in Acht.", sourceObjective = "Benutzt Rickets Ticker, um 3 Tiefenalabasterkristalle, 3 Tiefencoelestinkristalle, 3 Tiefenamethystkristalle und 3 Tiefengranatkristalle zu sammeln.", progress = "Bumm?", completion = "Gut gemacht!\n\nIch habe hier dieses nette kleine Geschäft laufen. Ein Haufen Trottel geht da drüben zu Therazanes Thron und gibt D'lom bergeweise Gold für allen möglichen Unsinn. Und dieses ganze Geld gibt er mir für diese Kristalle. Ich gehe steinreich nach Hause, alles für ein paar Felsbrocken.\n\nAber erzählt es keinem, ich will keine Konkurrenz.\n\nGlaubt Ihr, Ihr könntet später vorbeikommen und noch eine Ladung Kristalle bringen?", sourceObjectiveStatus = "unverified-source-field" }
quests[27049] = { id = 27049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weicher Fels", description = "Die Verderbnis der Rubinspanne hat nicht nachgelassen. Zerstört die Fungusungetüme, die unser Land mit ihrem Schmutz besudeln. Wenn sie sich weiterhin erheben, werden wir sie weiterhin vernichten.", sourceObjective = "Tötet 8 Fungusungetüme.", completion = "Wenn sie einmal anfangen zu wachsen, ist es fast unmöglich, sie wieder einzustampfen. Durch Beharrlichkeit werden wir eines Tages unser Reich säubern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27050] = { id = 27050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn der Pilze", description = "Etwas auf der Rubinspanne ruft ständig neue, widerliche Gewächse auf dem Felsen hervor. Neue Pilze wachsen und müssen zerstört werden, bevor sie sich noch weiter verbreiten.", sourceObjective = "Zerstört 10 der neu gesprossenen Pilze in der Rubinspanne.", completion = "Ihr habt viel Erfahrung, wenn es darum geht, auf Dinge zu treten. Ihr würdet einen ausgezeichneten Riesen abgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27051] = { id = 27051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beharrlichkeit zahlt sich aus", description = "Die Troggs haben sich nicht zerstreut, nachdem Ihr Glop getötet habt. Seine Diener haben den Wachstumsbeschleuniger gefunden, der zurückgelassen wurde, und säen die Samen der Verderbnis überall auf der Rubinspanne.\n\nBringt sie zur Strecke und findet alles, was vom Wunderwachstumsmittel von Verlok noch übrig ist. Es muss entsorgt werden.", sourceObjective = "Nehmt einen Beutel mit Wunderwachstumsmittel von Verlok von den Verloks auf der Rubinspanne an Euch.", progress = "Habt Ihr getan, worum ich Euch gebeten hatte? Wir müssen das Wachstumsmittel, das sie noch in Besitz haben, beseitigen.", completion = "Danke, {race}. Wir werden den Rest im Laufe der Zeit auch noch beseitigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27053] = { id = 27053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kessel von Gahrrons Trauerfeld", description = "Meine Analyse ist abgeschlossen! Die Verseuchung, die die Tiere hier befallen hat, ist keine Resterkrankung. Nein, sie ist etwas Neues... und ich glaube, ich weiß, was es ist.\n\nDer Kult der Verdammten unterhält einen Seuchenkessel auf einem Hof, der Gahrrons Trauerfeld heißt.\n\nDer Hof ist genau im Südosten von uns, kurz vor den Östlichen Pestländern. Ich brauche eine Probe von diesem Kessel, um meinen Verdacht zu bestätigen.\n\nBeseitigt den Kessellord, der dort zugegen ist, um an seinen Schlüssel zu gelangen. Dann werdet Ihr Zugang zu dem Kessel erhalten und könnt eine Probe für mich entnehmen.", sourceObjective = "Geht zu Gahrrons Trauerfeld in den Westlichen Pestländern. Findet und besiegt den dort anwesenden Kessellord und benutzt seinen Schlüssel, um Zugang zu dem Kessel zu erlangen.", progress = "Die Zugangsklappe zu dem Kessel ist fest verschlossen. Um sie zu öffnen, müsst Ihr den Schlüssel finden.", completion = "Der Schlüssel von Kessellord Rachseele löst sich auf, als er das Schloss auf der Zugangsklappe am unteren Ende der Kesselplattform berührt. Innen ist ein leises Knacken zu hören, die Zugangsklappe schwingt auf und enthüllt noch weitere, zähflüssige Gifte, die sich in dem Gefüge des Kessels befinden.\n\nDort ist ein kleiner Zapfhahn, unter den die Flasche genau passt, um eine Probe für Außenagent Kaartish in der Stätte der Heiler abzuzapfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27054] = { id = 27054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifelte Taten", description = "Der Kult der Verdammten unterhält ein kleines Lager im Osten, Malicias Außenposten. Dort trainieren sie außerhalb von Scholomance. Möglicherweise haben wir ihnen schon viel zu lange erlaubt, unkontrolliert dieses Training auszuüben.\n\nWenn Kultisten wirklich diese Seuche benutzen, um die Tierwelt zu infizieren, dann muss diese Infizierung an Malicias Außenposten stattfinden.\n\nAusbilder Malicia leitet den Außenposten. Findet sie, tötet sie und findet heraus, von wem sie ihre Befehle empfängt.", sourceObjective = "Tötet Instrukteurin Malicia und nehmt ihre Befehle für den Kult an Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[27055] = { id = 27055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krastinovs Schüler", description = "Laut der Befehle für den Kult soll Seuche aus dem Kessel bei Gahrrons Trauerfeld für ZWEI Zwecke benutzt werden. Der erste dient zur Übung, wie man Krankheiten über die Tiere der Pestländer verbreitet, das kennt Ihr ja bereits.\n\nDer Rest der Seuche wird für düstere Experimente in die Weinende Höhle transportiert, die nördlich von Malicias Außenposen liegt. Schüler der Scholomance verwenden die Seuche, um die Toten zu reanimieren!\n\nDas muss unbedingt aufhören.", sourceObjective = "Tötet in der Weinenden Höhle, die in den Westlichen Pestländern liegt, 2 Schüler Krastinovs, 2 Schläger aus Formfleisch, 2 Reißer aus Formfleisch und 4 unheilige Körperchen.", completion = "Ihr habt Euch selbst übertroffen, {name}. Wir haben nicht nur dem Kult der Verdammten bei ihrem Kreuzzug, die Pestländer neu zu infizieren, einen empfindlichen Rückschlag versetzt, Ihr habt auch noch einen weiteren fatalen Plan aufgedeckt: Sie holen die Toten ins Leben zurück!\n\nEuer Name wird bestimmt erwähnt, wenn die Information dem Hochlord Fordring vorgetragen wird, {name}. Seid Euch meiner Dankbarkeit und dem Segen des Argentumkreuzzugs gewiss.", sourceObjectiveStatus = "unverified-source-field" }
quests[27056] = { id = 27056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belmonts Bericht", description = "<Belmont reicht Euch einen versiegelten Umschlag.>\n\nBringt diesen Bericht zu Fürstin Sylvanas Windläufer. Es ist meine Einschätzung der Lage im Silberwald basierend auf Eurer und Yoricks Feldarbeit.\n\nWenn wir diese rebellischen Worgen nicht aufhalten, werden sie uns überrennen! Jetzt ist es Zeit zu handeln!", sourceObjective = "Bringt Belmonts Bericht zu Fürstin Sylvanas Windläufer in der Kommandozentrale der Verlassenen im Silberwald.", progress = "Kniet nieder vor Eurer Fürstin, {name}.", completion = "Crowley… Eine lästige Schmeißfliege. Ein Insekt, das nur darauf wartet, unter meinem Stiefel zerquetscht zu werden.\n\nEr will also die wilden Worgen im Silberwald aufwiegeln? Wir werden ihm und seinen Verbündeten die Macht der Verlassenen zeigen!\n\nAber zuerst müssen wir das Durcheinander beseitigen, das die Flotte des Kriegshäuptlings angerichtet hat. Ohne ihre Hilfe könnten wir diesen Krieg verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[27057] = { id = 27057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum heimischen Hof", description = "Sorgfältig verschließt Ihr den Zapfhahn auf dem Bedienfeld und beobachtet, wie das faulige Sekret in die leere Flasche tropft.\n\nJetzt, da Ihr das Gift in Händen haltet, ist es Zeit zu Außenagent Kaartish in die Stätte der Heiler zurückzukehren.", sourceObjective = "Bringt die Gefüllte Flasche: Gahrrons Trauerfeld zu Außenagent Kaartish in der Stätte der Heiler in den Westlichen Pestländern.", progress = "Gahrrons Trauerfeld beherbergt einen hochgiftigen Seuchenkessel. Wenn wir erst eine Probe der Seuche haben, die er ausspuckt, werden wir in der Lage sein, festzustellen, ob der Kult der Verdammten wirklich hinter der Vergiftung unseres Landes steckt.", completion = "Gute Arbeit! Einen Moment bitte...\n\n<Der Draenei nimmt sich einen Moment Zeit, um Eure Probe mit der Probe, die er wahrscheinlich schon vorher destilliert hat, zu vergleichen.>\n\nJa, das scheint dieselbe Verderbnis zu sein, die auch die Wildtiere befallen hat. Mit diesem Wissen und Eurer Kampferfahrung könnten wir die Macht haben, das zu beenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27058] = { id = 27058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die falsche Folge", description = "Wir müssen den Schattenhammer daran hindern, das Tor zu benutzen. Es gibt nur einen Weg.\n\nGebt die falsche Aktivierungsfolge ein und zerstört es.\n\nHmm, mal sehen. Ja, damit öffnet man das Tor zu den explosiven Tiefen der Feuerlande, der Elementarebene des Feuers. Das sollte funktionieren.", sourceObjective = "Benutzt den Torwächter, um die falsche Aktivierungsfolge einzugeben und so das Tor zu zerstören.", completion = "Ihr habt es geschafft! Ihr habt herausgefunden, was der Schattenhammer vorhat und ihnen dann einen Strich durch die Rechnung gemacht!\n\n<Mowi stellt sich auf die Zehenspitzen und gibt Euch einen Kuss auf die Wange.>\n\nNun, ich bin mir sicher, dass ich hier irgendwo etwas für Euch habe.\n\n<Sie kramt nach Eurer Belohnung.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27059] = { id = 27059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die falsche Folge", description = "Wir müssen den Schattenhammer daran hindern, das Tor zu benutzen. Es gibt nur einen Weg.\n\nGebt die falsche Aktivierungsfolge ein und zerstört es.\n\nHmm, mal sehen. Ja, damit öffnet man das Tor zu den explosiven Tiefen der Feuerlande, der Elementarebene des Feuers. Das sollte funktionieren.", sourceObjective = "Benutzt den Torwächter, um die falsche Aktivierungsfolge einzugeben und so das Tor zu zerstören.", completion = "Ihr habt es geschafft! Ausgezeichnete Arbeit, junger Herr. Ihr habt herausgefunden, was der Schattenhammer vorhat und ihnen dann einen Strich durch die Rechnung gemacht!\n\n<Prüfer Rowe klopft Euch mit seiner knochigen Hand anerkennend auf den Rücken.>\n\nNun, ich bin mir sicher, dass ich hier irgendwo etwas für Euch habe.\n\n<Er kramt nach Eurer Belohnung.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27060] = { id = 27060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unheilige Kuh", description = "<Bauer Wollerton versucht, sich zusammenzureißen.>\n\nKühe? Erkundigt Ihr Euch nach dem vermissten Vieh?\n\nNormalerweise lasse ich die Kühe nördlich vom Haus grasen. Ab und zu wird eine weggezaubert. Da bleibt dann nur eine Blutspur zurück. Wer macht denn so was?\n\nIch habe Angst, dieser Spur zu folgen... etwas Krankes geht hier in Sturmwind vor!", sourceObjective = "Begleitet Anduin Wrynn und folgt der Blutspur von Wollertons Bauernhof zum Tatort. Haltet Anduin am Leben. Wenn er nicht mehr an Eurer Seite ist, findet Ihr ihn in Burg Sturmwind.", completion = "Das war knapp! Ich kann gar nicht glauben, dass Ihr Euch gegen so viele gleichzeitig behauptet habt.\n\nOffenbar wurde dieser Ort für ein widerliches Einführungsritual des Schattenhammers genutzt. Sie sind auf jeden Fall in Sturmwind aktiv. Was ist das?\n\n<Anduin findet ein Abzeichen, das auf dem Schrein liegt.>\n\nDieses Abzeichen zeigt eine Axt und einen Hammer, die gekreuzt sind. Es sieht alt aus. Wenn wir uns weiter umsehen, finden wir vielleicht heraus, was es bedeutet...", sourceObjectiveStatus = "unverified-source-field" }
quests[27061] = { id = 27061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zwielichtwarte", description = "Der Drache, von dem sie reden, ist Abyssion, {name}. Es wird nicht einfach sein, das Fragment von ihm zu erhalten.\n\nTrefft Euch erneut mit Mylra. Sie lenkt ihre Einsätze von der Zwielichtwarte hier in der Nähe aus.\n\nSie wird Euch sagen, was wir als nächstes tun werden.", sourceObjective = "Sprecht mit Sturmruferin Mylra an der Zwielichtwarte in Tiefenheim.", completion = "Also müssen wir uns Abyssion stellen, um das Fragment zu bekommen? Diese Operation ist plötzlich sehr viel gefährlicher geworden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27062] = { id = 27062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lauernde Gefahr", description = "Die Stacheleber im Hügel der Klingenhauer scheinen sich mit der Geißel zusammengetan zu haben. Das sind düstere Nachrichten für uns, {class}. Wir haben genug ernsthafte Probleme damit, uns mit den Grimmtotem auseinanderzusetzen, wir können nicht noch einen Angriff der Geißel überstehen. Begebt Euch in den Hügel der Klingenhauer, der im Osten liegt, und seht, ob Ihr jemanden findet, der Euch dabei hilft, sie aufzuhalten, bevor sie uns hier angreifen.", sourceObjective = "Findet Hilfe bei den Hügeln der Klingenhauer.", completion = "Ihr scheint fähig als Krieger zu sein. Vielleicht könnt Ihr mir helfen, diesem schrecklichen Elend hier ein Ende zu bereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27063] = { id = 27063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lauernde Gefahr", description = "Die Geißel ist eine Beleidigung für die Natur. Sie haben es geschafft, die Stacheleber im Hügel der Klingenhauer zu verderben. Jetzt drohen sie sich noch weiter in den Tausend Nadeln auszubreiten und - wie ich fürchte - schlussendlich auch nach Westen nach Feralas. Ihr müsst dorthin gehen und alles tun, um sie festzusetzen. Vielleicht könnt Ihr jemand in dem Gebiet dort finden, der Euch hilft? Die Winde flüstern von einer mächtigen Präsenz in der Gegend.", sourceObjective = "Sucht im Hügel der Klingenhauer nach Hilfe.", completion = "Ihr wirkt wie ein fähiger Krieger. Vielleicht könnt Ihr mir dabei helfen, den Schrecken hier zu beenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27064] = { id = 27064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Er hält uns hin", description = "{name}, es scheint beinahe so, als ob Samuelson absichtlich unsere Zeit verschwendet. Die Dockarbeiter wissen gar nichts. Was noch wichtiger ist - Sprengstoff aus dem Hafen von Sturmwind ist verschwunden.\n\nWisst Ihr, was ich denke? Ich wette, Samuelson weiß mehr, als er zugibt. Er hat wahrscheinlich eine Spur, den Schattenhammer betreffend, und will die Lorbeeren selbst einheimsen.\n\nWir sollten uns seine Akten im SI:7 Hauptquartier mal ansehen. Bringt mich dorthin, denn ich müsste Einblick in seine Akten bekommen, um herauszufinden, was er wirklich weiß.", sourceObjective = "Begleitet Anduin Wrynn in den dritten Stock des SI:7 Hauptquartiers in der Altstadt von Sturmwind. Wenn er nicht mehr an Eurer Seite ist, findet Ihr ihn in Burg Sturmwind.", progress = "Es wird Zeit, dass wir Antworten finden!", completion = "Das ist WIRKLICH verdächtig, {name}! Samuelson hat nicht einen Schnipsel Informationen über den Schattenhammer - es scheint beinahe so, als ob er überhaupt keine Untersuchungen über sie anstellt. Dennoch hat er hier eine Aufstellung über die fehlenden Sprengstoffe.\n\n\n\nUnd ich habe dieses merkwürdige Abzeichen mit einem Symbol darauf gefunden: Eine Axt und ein Hammer, die sich kreuzen.\n\nDas hat doch etwas zu bedeuten - aber was?", sourceObjectiveStatus = "unverified-source-field" }
quests[27065] = { id = 27065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flotte des Kriegshäuptlings", description = "Unsere Verstärkung aus Kalimdor ist letzte Nacht eingetroffen. Drei Kanonenboote der Orcs voller Vorräte, Waffen und Soldaten. Drei Kanonenboote der Orcs, die wir an die verdammten Worgen von Blutfang verloren haben.\n\nWie kann eine ganze Orcflotte gegen einen kleine Truppe feindlicher Kämpfer verlieren, die noch nicht einmal Belagerungswaffen besitzen? Diese wichtige Frage werdet Ihr mir beantworten. Sucht Eure Sachen zusammen und meldet Euch bei dem Orc Admiral Hatchet an der Rückendeckung der Verlassenen, südwestlich von hier.\n\nMacht diesen Orcs Beine, {name}.\n\nIch erwarte Euren vollständigen Bericht.", sourceObjective = "Meldet Euch bei Admiral Hatchet bei der Rückendeckung der Verlassenen im Silberwald.", completion = "Dieses Fiasko könnte als eine der größten Peinlichkeiten in die Geschichte der Seekriegsführung eingehen. Wie das passiert ist? Trunkenheit ist passiert. So war das.", sourceObjectiveStatus = "unverified-source-field" }
quests[27066] = { id = 27066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blitzartig heilen", description = "Ich möchte Euch eine vielseitige und schnelle Heilungstechnik beibringen, {name}. Diese Heilung werdet Ihr oft anwenden.\n\nEs gibt immer genug Krieger, die während unserer Kämpfe gegen die Borstennacken verletzt werden, also habt Ihr ausreichend Gelegenheit, Euer neu erworbenes Wissen sofort einzusetzen. Erprobt Eure neue Heilungstechnik an den verwundeten Kriegerhelden im Camp Narache.", sourceObjective = "Lernt von Seherin Rabenfeder 'Blitzheilung'. Erprobt Eure neue Heilungstechnik 5 Mal an den verwundeten Kriegerhelden im Camp Narache.", sourceObjectiveStatus = "unverified-source-field" }
quests[27067] = { id = 27067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verjüngende Berührung", description = "Ich möchte Euch eine einfache Heilungstechnik beibringen, {name}. Dieser Zauber erlaubt es Euch, die Wunden von Verbündeten über einen kurzen Zeitrum hinweg zu heilen.\n\nViele Krieger sind während unseres Kampfes, um Camp Narache zu verteidigen, verwundet worden, also könnt Ihr Eure Heilfähigkeiten sinnvoll einsetzen. Übt Eure neue Heilungstechnik an den verwundeten Kriegerhelden im Camp Narache.", sourceObjective = "Lernt von Gart Nebelläufer 'Verjüngung'. Übt 'Verjüngung' an einem verwundeten Kriegerhelden im Camp Narache.", completion = "Ihr habt Talent für Heilkünste, {name}. Wo immer Euer Weg Euch hinführt, Eure Fähigkeiten als Heiler werden begehrt sein. Kehrt zu mir zurück, wenn Ihr weitere Ausbildung benötigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27068] = { id = 27068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Häuptling Ukurz Sandskalp", description = "Schaut genau hin, Mann. So läuft das hier, Verrat folgt auf Verrat. Erst trickse ich Euch aus, um das Schwert zu krieg'n, und dann kommt Häuptling Ukurz und legt mich so richtig aufs Kreuz.\n\nSo is' das Leben, ja! Oder war es...\n\nNa ja, ich weiß, dass Ihr Mazoga gar nie nich' leiden konntet. Aber ich weiß, dass Ihr trotzdem macht, worum ich Euch bitte. Tötet ihn für mich. Vergießt noch mehr Blut auf dem Sand und gebt Häuptling Ukorz Sandskalp was alle Sandwüter verdien'n...einen blutigen Tod.\n\nVielleicht überlasse ich Euch was von mir, auf dem kein Fluch liegt, ja?", sourceObjective = "Tötet Häuptling Ukorz Sandskalp.", completion = "Er ist weg? Hatte er das Schwert?\n\nNee... sagt nix. Ist egal. Mazoga kümmert das nicht.\n\nIch bin dann mal weg, Mann. Die Folgen meiner Handlungen warten auf mich. Nehmt, was immer ich bei mir trage... Wo ich hingehe, brauch' ich das nich' mehr...", sourceObjectiveStatus = "unverified-source-field" }
quests[27069] = { id = 27069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der stählerne Donner", description = "Wir brauchen uns von der Schmach dieser Niederlage wahrscheinlich gar nicht reinzuwaschen, {name}. Der Kriegshäuptling wird uns stattdessen alle hinrichten lassen.\n\nIch will verdammt sein, wenn wir kampflos aufgeben. Obwohl der ganze Strand von Blutfangworgen überrannt ist, könnte noch Hoffnung bestehen. Ich möchte, dass Ihr einen unserer Süßwassermatrosen zu dem Landestrand genau westlich von hier begleitet und unsere Vorräte wiederbeschafft. Kehrt zu mir zurück, wenn der Süßwassermatrose nichts mehr tragen kann.", sourceObjective = "Bergt 5 Seebärenkisten.\n\nFalls Ihr unerwartet Euren orcischen Süßwassermatrosen verlieren solltet, dann sprecht mit Admiral Hatchet, um einen neuen zu bekommen.", completion = "In diesen Kisten befindet sich STÄHLERNER DONNER! Jetzt, da unsere Waffen wieder da sind, haben wir vielleicht eine Möglichkeit, uns zu rehabilitieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[27070] = { id = 27070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergebliche Mühe", description = "Ich hörte, dass ein Troll hier drin - Hydromantin Velratha hieß sie, glaube ich - in den Besitz eines sehr seltenen, wunderschönen und mächtigen Schmuckstücks gelangt ist - der Tiara der Tiefen. Sie benutzt sie, um den mächtigen Halbgott Gahz'rilla zu kontrollieren, dessen Schuppen angeblich vor Energie knistern. Wisst Ihr, was das bedeutet, {race}?\n\nIch brauche sie! Tötet Velratha, nehmt ihr die Tiara der Tiefen ab und tötet Gahz'rilla für eine seiner Schuppen. Bringt mir alles schleunigst her! Ich werde Euch fürstlich belohnen...", sourceObjective = "Beschafft Euch die Tiara der Tiefen und Gahz'rillas elektrisierte Schuppe.", progress = "Habt Ihr, was ich brauche?", completion = "Ausgezeichnet! Die Tiara verschafft mir die absolute Kontrolle über das Wasser hier und die elektrisierte Schuppe wird alle Maschinen antreiben, die ich zu meinem Vorteil nutze.\n\nIhr macht mich zu einem sehr reichen und mächtigen Goblin! Ihr könnt das hier haben, das ist nichts im Vergleich zu dem, was ich bald haben werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27071] = { id = 27071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorn der Sandwüter", description = "Die Sandwüter sind ein widerstandsfähiger Stamm. Sie hab'n Sandstürme überlebt und über die Jahre hinweg noch ganz andere Sachen, die inzwischen längst von Sand bedeckt sind. Es wäre dumm zu glauben, dass die einzige Macht hier die Trolle sind. Wir hab'n Skarabäen gezähmt, Sul'lithuz gezüchtet und unsere Toten wiederaufersteh'n lassen, damit sie bis in alle Ewigkeit als Zombies kämpfen.\n\nRuuzlu, die rechte Hand von Häuptling Ukorz Sandskalp, hat vor, mit ihrer Hilfe Tanaris für die Sandwüter zurückzuerobern. Ihr solltet die Trolle, die dafür verantwortlich sind, töt'n, wenn Ihr leben wollt, Mann.", sourceObjective = "Tötet Theka den Märtyrer, Hexendoktor Zum'rah, Antu'sul und Ruuzlu.", completion = "Ihr habt sie getötet? Alle? Und seid lebendig zurückgekomm'n?\n\nDann nehmt von mir, was Ihr wollt. Es ist überwiegend frei von Flüchen, Mazoga verspricht es.", sourceObjectiveStatus = "unverified-source-field" }
quests[27072] = { id = 27072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Alte Kaserne", description = "Das Symbol auf diesen Abzeichen ist mir schon aufgefallen, bevor Todesschwinge die Stadt angegriffen hat. Die Soldaten in der Alten Kaserne, die im Westen der Stadt den Hafen überblickt, haben sie getragen.\n\nIhr hättet kaum zu einer besseren Zeit hier auftauchen können. Einer meiner Topagenten, Jack Bauden, ist in meinem Namen mit der Infiltration des Schattenhammers beschäftigt. Er wird seit gestern Nacht vermisst. Wenn Anduin und Ihr Recht habt, dann haben sich die Kultisten in der Alten Kaserne verkrochen. Die Zeit drängt! Greift die Alte Kaserne an, schaltet die Kultisten aus und rettet Jack Bauden.", sourceObjective = "Geht zur Alten Kaserne und tötet 6 wahnsinnige Kultisten, dann findet Jack Bauden.", progress = "<Bauden ist ohnmächtig. Die Gegend wimmelt noch immer vor Kultisten. Ihr solltet sie beseitigen, bevor Ihr Untersuchungen anstellt.>", completion = "<Ihr ohrfeigt Bauden bis er zu sich kommt.>\n\n{class}? Was macht Ihr denn hier?\n\nIch bin SI:7-Agent Jack Bauden. Heute ist der längste Tag meines Lebens.", sourceObjectiveStatus = "unverified-source-field" }
quests[27073] = { id = 27073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht ihnen die Hölle heiß!", description = "Die Goblins sind schuld, {race}!\n\n<hicks!>\n\nWisst Ihr, wir sind vom Bilgewasserhafen aus über Azshara zum Silberwald aufgebrochen. Ein riesiger Fehler! In unserem gesamten Imperium habe ich noch nie einen sündigeren und schmächlicheren Haufen erlebt! Diese verdammten Goblins haben uns zu jedem möglichen Laster verführt und uns mit Fässern voller Bier aufs Meer geschickt!\n\n<hicks!>\n\nDie Scham, die wir dafür empfinden, sitzt tiefer als jede Narbe. Unsere Ehre muss wiederhergestellt werden! Tötet die Blutfangworgen, die uns aufgelauert haben. Sie plündern gerade das Wrack im Südwesten.", sourceObjective = "Tötet 10 Blutfangplünderer.", completion = "Sieht aus, als hättet Ihr diese Worgen so richtig vermöbelt und die Scham von uns genommen. Vielleicht hören die Seebären jetzt auf, zu saufen.\n\nAch, wem mache ich was vor.\n\nHa!", sourceObjectiveStatus = "unverified-source-field" }
quests[27074] = { id = 27074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bekämpft den Hammer", description = "Ihr habt das Unmögliche möglich gemacht! Ich habe die Nase voll davon, hier herumzuschmollen. Es wird Zeit, sich aufzugnomen.\n\nIch muss meinen Vater finden. Aber Ihr! Befasst Euch nicht länger mit mir. Ihr müsst weiter gegen diese Kultisten kämpfen.\n\nGeht und sprecht mit Ashlan Schmunzelstein im Osten. Er versucht, den Schattenhammer aufzuhalten, aber er hat niemanden, der ihm hilft. Ihr seid seine einzige Hoffnung!\n\nGebt nicht auf, {name}. Ich werde es auch nicht tun.", sourceObjective = "Sprecht in Loch Modan in der Nähe der Festung Mo'grosh mit Ashlan Schmunzelstein.", completion = "Habt Ihr dem Zwielichtlager in der Mitte des Sees einen Schlag versetzt? Nicht schlecht, Junge!\n\nWenn Ihr den Kampf zu ihnen nach Hause tragen wollt, kann ich Euch die Gelegenheit dazu geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27075] = { id = 27075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diener von Cho'gall", description = "Der Schattenhammer war zunächst ein Klan der wilden Horde. Ihr Anführer - Cho'gall - formte aus seiner Bande Oger nach und nach einen tödlichen Kult, der jeden willkommen hieß, der verrückt genug war, sich das Ende allen Lebens zu wünschen. Wie Ihr seht, gibt es immer noch viele Oger unter ihnen. Sie sind verwirrt, fanatisch und immer noch so stark wie früher.\n\nDiese primitiven Monster besitzen die Frechheit, hierherzukommen und ihren Schmutz über unser Land auszubreiten. Je mehr Ihr tötet, desto besser wird Loch Modan dastehen, {name}.", sourceObjective = "Tötet 7 Oger der Mo'grosh in der Festung Mo'grosh.", completion = "Es mag zwar finster aussehen, aber wir werden mit Eurer Hilfe gewinnen, {name}. Sie werden die Zwerge nicht unterdrückt halten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[27076] = { id = 27076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einbruch mit schwerem Werkzeug", description = "Ein guter Kumpel von mir, Weegli Lunte, hat sich mit Unteroffizier Bly und seiner Gruppe Gesetzloser zusammengetan, um in Zul'Farrak einzumarschieren und das legendäre Sul'thraze zu erbeuten. Natürlich haben sie den Stamm der Sandwüter unterschätzt und jetzt sind sie alle festgesetzt und warten auf ihre Hinrichtung, um den Halbgott Gahz'rilla zufriedenzustellen.\n\nWenn Ihr Weegli befreit, wird er Euch helfen, den Weg zu Ukorzs Privatgemächern freizusprengen, wo er mindestens einen Teil der Klinge aufbewahrt.\n\nTötet Nekrum den Ausweider und Schattenpriester Sezz'ziz, die ihn gefangen genommen haben, als Rache...Ich werde Euch belohnen.", sourceObjective = "Befreit Weegli Lunte und tötet Nekrum den Ausweider und Schattenpriester Sezz'ziz.", completion = "Wow! Ich wusste, ich kann auf Euch zählen! Hier ist etwas für Eure Unannehmlichkeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27077] = { id = 27077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ans Chaos klammern", description = "Die Kultisten vom Schattenhammer benutzen ihre Kräfte, um Elementiummetall aus den Tiefen der Erde zu gewinnen. Sie locken es als verdrehte Stacheln heraus, um damit ihre Gebäude zu formen, die in dem entweihten Boden verwurzelt sind.\n\nDie Oger hier scheinen dabei kräftig mitzumischen und wir müssen zuschlagen, solange sie es noch in Form drehen.\n\nReißt die Stacheln aus dem Boden, solange sie noch biegsam sind und bringt sie zu mir. Wir werden diesen Hundesöhnen nicht einen Zoll unseres Landes überlassen.", sourceObjective = "Reißt 10 entstehende Elementiumstacheln aus dem Boden der Festung Mo'grosh.", progress = "Habt Ihr die Stacheln herausgerissen?", completion = "Schade, dass diese halbgestalteten Dinger zu brüchig und krumm sind, als dass wir sie als Waffen benutzen könnten. Aber nur dank Euch haben wir überhaupt die Chance, sie herauszuziehen, bevor sie sich verhärten. Deshalb werde ich mich nicht beschweren.", sourceObjectiveStatus = "unverified-source-field" }
quests[27078] = { id = 27078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gor'kresh", description = "Der Oger, der über diese primitiven Narren wachen soll, heißt Gor'kresh. Er ist groß genug, um selbst diese Schläger herumzukommandieren - und obendrein ist er gerissen. Setzt niemals voraus, dass ein Oger dumm ist, denn dann erwischt er Euch.\n\nWenn Ihr ihn beseitigt, dann werden wir dem Schattenhammer schon zeigen, dass Loch Modan kein Sprungbrett für sie ist. Stellt Euch Gor'kresh entgegen und treibt diese Narren zurück in das Hochland!", sourceObjective = "Besiegt Gor'kresh.", sourceObjectiveStatus = "unverified-source-field" }
quests[27082] = { id = 27082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfaire Methoden", description = "Habt Ihr die großen, schwerfälligen Ettins gesehen, die durch die Wälder streifen? Die verfluchten Dinger kamen aus Gilneas. Jetzt vagabundieren sie durch das Land und suchen ihre nächste, saftige Mahlzeit. Wir haben es geschafft, einige von ihnen zu unterwerfen und sie nutzbar zu machen, um unsere Wagen zu ziehen, aber die anderen... nun, sie müssen getötet werden.\n\nLeider können wir keine Soldaten erübrigen, um das zu erledigen. Da kommt Ihr ins Spiel, {class}.\n\nIch habe einen Plan, aber dafür brauchen wir noch Materialien. Geht hinaus in die Wälder, die diese Basis umgeben und beschafft die Organe kranker Tiere.", sourceObjective = "Beschafft 8 verseuchte Organe von ergrauten Riesenbären und tollwütigen Worgs.", progress = "Wir sind die Verlassenen! So machen wir das, {class}.", completion = "Ausgezeichnet! Und jetzt müssen wir das \"Mahl\" vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27083] = { id = 27083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht geht weiter!", description = "Es gibt Nachrichten aus Andorhal, {name}. Die Schlacht hat wieder angefangen.\n\nUnter den Streitkräften der Verlassenen ist es wohl bekannt geworden, dass Ihr Euch in der ersten Schlacht um Andorhal als einer der Helden hervorgetan habt. Koltira verlangt umgehend nach Eurer Anwesenheit.", sourceObjective = "Meldet Euch in den Westlichen Pestländern in Andorhal bei Koltira Todesweber.", completion = "Thassarian und die Menschen haben ihren Zug gemacht. Ich dachte, ich hätte eine Abmachung mit Thassarian... aber das muss dann wohl reichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27084] = { id = 27084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bauernmiliz", description = "Der Kampf begann, als sie uns von hinten angriffen. Ich habe kurz nicht aufgepasst und eine Gruppe schlecht bewaffneter Bauern und Milizen stieß vom Trostlosen Feld in unsere Flanke vor.\n\nSie mögen schwach sein, aber wenn sie so ungehindert angreifen, besteht die Gefahr, dass sie uns allein durch ihre zahlenmäßige Überlegenheit überwältigen.\n\nLindsays domestizierte Monstrositäten können sich um den Nahkampf kümmern. Nehmt dieses Halsband, bleibt hinten und benutzt es, um meinen schwarzen Gargoyle auf diese Bauern zu hetzen.", sourceObjective = "Benutzt das ebenhölzerne Gargoylehalsband auf 6 Provinzmilizen in Andorhal.", completion = "Das hat nur ein winziges Loch in ihre Reihen gerissen...aber der Anblick ihrer Freunde, die vom Himmel fielen, hat ihre Entschlossenheit ins Wanken gebracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[27085] = { id = 27085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Truppen unterstützen", description = "Auch wenn diese Bauern uns zu überrennen drohen, dürfen wir die Hauptstreitmacht der Allianz nicht vergessen.\n\nReist in den Westen nach Andorhal und tötet die menschlichen Soldaten, die gegen unsere Todeswachen kämpfen. Wir können alle Hilfe gebrauchen, die wir bekommen können.", sourceObjective = "Tötet 15 Verteidiger von Andorhal.", completion = "Ihr habt gut gekämpft, {name}. Ich wünschte, ich hätte Eure Fähigkeiten ... und Euren Mut.", sourceObjectiveStatus = "unverified-source-field" }
quests[27086] = { id = 27086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asche zu Asche", description = "Im Westen, tief in dem von der Allianz gehaltenen Andorhal, findet Ihr ihre Kommandanten. Sie kämpfen nicht, sondern befehligen nur von den Rücken ihrer Pferde.\n\nJagt und tötet diese Kommandanten, {name}. Die Menschen werden machtlos sein.", sourceObjective = "Tötet 3 Streitkräftekommandanten von Andorhal.", completion = "Gut gemacht. Jetzt, da sie ausgeschaltet wurden, habe ich keine Ausreden mehr.\n\nBald muss ich mich Thassarian im Kampf stellen, für Ehre und für Andorhal.", sourceObjectiveStatus = "unverified-source-field" }
quests[27087] = { id = 27087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Entlarvung der Lindsay Rabensonn", description = "Man hat mir gesagt, dass dieses nutzlose Weib, Lindsay Rabensonn, hier wäre, um mich in diesem Kampf zu unterstützen. Bisher hat sie noch nichts anderes getan, als im Keller des Haupthauses hinter mir dumpf vor sich hin zu brüten. Ist wohl auch besser so. Sie war eine Ablenkung.\n\nDennoch, ich kann und werde keine Befehlsverweigerung dulden. Findet sie und bringt sie zu mir.", sourceObjective = "Meldet Euch in den Westlichen Pestländern in Andorhal bei Lindsay Rabensonn.", completion = "Ihr werdet mich nirgendwohin mitnehmen, {name}.\n\nWährend Koltira und sein Kumpan Thassarian herumstolzieren, habe ich vor, diese Schlacht zu gewinnen. Koltira wird für seine Schwäche bezahlen.\n\nGlaubt Ihr nicht? Na gut, dann weihe ich Euch in mein kleines Geheimnis ein...", sourceObjectiveStatus = "unverified-source-field" }
quests[27088] = { id = 27088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es ist nur giftig, wenn man es einnimmt", description = "Nehmt diesen Käfig, {class}. Darin befindet sich eins meiner mutierten Buschhühner, mit einigen leichten Veränderungen. In dem Hintern des Buschhuhns befindet sich eine Dynamitstange, die mit Schleim von den verseuchten Organen, die Ihr mir gebracht habt, versetzt ist.\n\nBringt den Käfig in den Wald und findet den Waldettin, der dort herumläuft. Lasst das Huhn frei und lehnt Euch zurück, während dieses Meisterstück seine Arbeit tut. Die folgende Explosion dürfte ausreichen, um den Ettin zu töten oder ihn so sehr zu schwächen, dass Ihr die Möglichkeit bekommt, ihn zu erlegen.", sourceObjective = "Benutzt das mutierte Buschhuhn, um den Waldettin zu töten.", completion = "<Apotheker Wurmschmutz lacht wie irre.>\n\nGab es daran jemals Zweifel? Ein Ettin kann der Wissenschaft nicht das Wasser reichen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27089] = { id = 27089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versteckter Trumpf", description = "Ihr habt ja keine Ahnung, wie schwer es war, die Tarnung aufrecht zu halten, während ich zusah, wie Koltira diesen Krieg entgleiten ließ. Es ist so weit gekommen, dass diese lästigen Bauern uns zu überwältigen drohen. Und all das nur, weil er sich geweigert hat, einen Freund zu töten.\n\nNehmt noch einmal meine Val'kyr, {name}. Tötet die Bauern mit ihr an Eurer Seite, macht sie zu Verlassenen und lasst sie ausrücken. Dann geht mit einer Gruppe von ihnen in den von der Allianz gehaltenen Westteil von Andorhal und bringt diesen Todesritter Thassarian zur Strecke.\n\nWir werden diesen Krieg doch noch gewinnen.", sourceObjective = "Tötet 5 verängstigte Provinzmilizangehörige mit der bezauberten Val'kyr an Eurer Seite. Dann benutzt Eure Fähigkeit 'Ruf zu den Waffen' und macht aus ihnen Gardisten der Verlassenen. Dann findet Thassarian im Westteil von Andorhal.", completion = "Dies ist die Leiche von Lurid, Thassarians getreuem Ritter. Da Thassarian nirgendwo zu finden ist, scheint es, als ob die Streitkräfte der Allianz sich zurückgezogen haben.\n\nDie Verlassenen haben die Schlacht für Andorhal gewonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27090] = { id = 27090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andorhal, für Immer und Ewig", description = "Sylvanas wird alles über die Abreise von Thassarian aus Andorhal wissen wollen. Ihr beschließt, zu der Seite der Stadt, die von den Verlassenen gehalten wird, zurückzukehren.", sourceObjective = "Meldet Euch in den Westlichen Pestländern in Andorhal bei Fürstin Sylvanas Windläufer.", completion = "Seht Ihr? Ich brauchte nur ein wenig Hilfe von den Val'kyr. Diese Wesen sind weitaus hilfreicher, als ich ursprünglich dachte.\n\nAber nun zu anderen Dingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27091] = { id = 27091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmangriff!", description = "Und jetzt ist es Zeit für Eure erste Lektion.\n\nIch werde Euch eine großartige Methode zeigen, einen Kampf zu beginnen, {name}. Indem Ihr die Initiative ergreift und losstürmt, könnt Ihr Eure Gegner betäuben und Euch die Oberhand verschaffen.\n\nSobald unsere Lektion beendet ist, findet eine Trainingsattrappe und übt Eure neue Fähigkeit.", sourceObjective = "Lernt von Delios 'Sturmangriff'. Findet eine Trainingsattrappe außerhalb des Sonnenturms und übt 'Sturmangriff'.", sourceObjectiveStatus = "unverified-source-field" }
quests[27092] = { id = 27092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kataklysmus in den Katakomben", description = "Sorgt Euch nicht um mich, {class}. Ich habe den Plan des Schattenhammers aufgedeckt. Sie haben im Hafen von Sturmwind eintreffenden Sprengstoff gesammelt und aufgeschichtet. Irgendwie haben sie sich Zutritt zu den Katakomben unter der Kathedrale des Lichts verschafft. Ich hörte von jemandem namens \"Der Schwarze Bischof\".\n\nWir haben nicht genug Zeit, um die Wache zu warnen. Es bleiben Euch nur noch Minuten, um in die Katakomben vorzudringen und die Bombe zu entschärfen! Geht! Schnell! Oder TAUSENDE MENSCHEN werden STERBEN!", sourceObjective = "Betretet die Kathedrale des Lichts und steigt hinab in die Katakomben darunter. Tötet den Schwarzen Bischof und entschärft den Sprengstoffhaufen in der Nähe.", progress = "<Dunkle magische Runen bedecken die Oberfläche des Sprengstoffs und pulsieren mit zunehmender Intensität...>\n\nIhr müsst den Schwarzen Bischof finden!", completion = "<3... 2 ... 1 ...>\n\n<Ihr feuchtet Eure Finger an und erstickt die Lunte. Die Kathedrale ist gerettet!>\n\n<Unter den Sprengstofffässern findet Ihr einen Stapel Notizen und Papiere. Offenbar haben die Kultisten versucht, die zurückgelassenen Beweise zu zerstören.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27093] = { id = 27093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Dunkelheit verlaufen", description = "Einige würden sagen, dass wir Glück haben, am Leben zu sein. Diese Leute wären Idioten. Wenn wir gestorben wären, müssten wir uns nicht dem Zorn des Kriegshäuptlings stellen. Aber nun, was geschehen ist, ist geschehen. Jetzt müssen wir versuchen, unsere verlorene Ehre wiederherzustellen.\n\nDas dritte Schiff in unserer Flotte ist direkt vor der Huschdunkelküste nordwestlich von hier gesunken. Diejenigen, die es an Land geschafft haben, wurden von riesigen Spinnen der Gegend umzingelt und in Spinnweben gehüllt.\n\nWenn es dort Überlebende gibt, müssen wir sie befreien! Geht, {name}. Auf ins Huschdunkel!", sourceObjective = "Rettet 6 orcische Seebären aus dem Huschdunkel.", completion = "Lok'tar, {name}. Sobald die Wirkung des Biers nachlässt, werden meine Orcs bereit sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[27094] = { id = 27094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefer in die Dunkelheit", description = "Die Netzhuschermatriarchin ist in der Nähe! Ihr könnt der Bedrohung durch die Netzhuscher ein Ende bereiten, indem Ihr sie erlegt!\n\nFindet sie am Ende der Höhle im Huschdunkel und vernichtet sie!", sourceObjective = "Tötet die Netzhuschermatriarchin.", completion = "Ihr habt unsere Orcs gerettet und die Netzhuschermatriarchin getötet? Wir schulden Euch großen Dank. Ihr habt uns alle vor der sicheren Hinrichtung bewahrt, {name}. Ich bin sicher, dass wir diese betrunkenen Idioten jetzt wecken können.", sourceObjectiveStatus = "unverified-source-field" }
quests[27095] = { id = 27095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Netzhuscherbedrohung", description = "Rache ist allumfassend, {name}! Unser drittes Schiff ist direkt vor der Huschdunkelküste nordwestlich von hier gesunken. Die Männer, die es von dem Schiff herunter geschafft haben, wurden entweder gefangengenommen, oder von den Netzhuscherspinnen der Region getötet. Dafür müssen die Spinnen sterben! ALLE!\n\nBegebt Euch zum Huschdunkel und zermalmt diese Spinnen!\n\nHaltet Ausschau nach ihrer Matriarchin. Wenn wir sie finden, können wir diese Bedrohung vielleicht beenden!", sourceObjective = "Tötet 12 Netzhuscherspinnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27096] = { id = 27096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles klar bei den Orcs", description = "<Admiral Hatchet übergibt Euch einen Umschlag, der mit dem Zeichen der Horde versiegelt ist.>\n\nDies ist Euer Empfehlungsschreiben. Das ist das Mindeste, was ich unter diesen Umständen für Euch tun kann.\n\nKehrt zu Fürstin Sylvanas Windläufer mit diesem Brief zurück und informiert sie über unseren Status. Lasst sie wissen, dass wir nur auf ihren Befehl warten, um loszumarschieren.\n\nLebt wohl, {name}. Ihr seid <ein ausgezeichneter Soldat/eine ausgezeichnete Soldatin>.\n\nNordosten, <mein Junge/Ma'am>. Auf zur Kommandozentrale der Verlassenen!", sourceObjective = "Liefert das Empfehlungsschreiben des Admirals bei Fürstin Sylvanas Windläufer bei der Kommandozentrale der Verlassenen im Silberwald ab.", progress = "Und die Orcs?", completion = "<Sylvanas zieht eine Augenbraue hoch.>\n\nAlso ist bei den Orcs alles in Ordnung?\n\n<Sylvanas liest das Empfehlungsschreiben.>\n\nIhre Vorräte zurückgeholt? Ein Dutzend Worgen getötet? Einen Ettin zur Strecke gebracht? Ihre Soldaten befreit und die Netzhuschermatriarchin vernichtet?\n\nIch sage das ja selten, aber ich bin beeindruckt. Vielleicht entsprechen Eure Fähigkeiten tatsächlich Euren Ambitionen. Wir werden sehen, ich werde Euch auf die Probe stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27097] = { id = 27097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhebt Euch, Verlassene", description = "Die Insel Fenris ragt trotzig im Herzen des Lordameresees auf - eine grausame Erinnerung an eine längst vergangene Zeit.\n\nObwohl sie nicht länger von Gnollgezücht befallen ist, hat sich eine neue Bedrohung aufgetan. Menschenflüchtlinge, die aus ihren Behausungen im Hügelland vertrieben wurden, sind in der Hoffnung auf die Insel Fenris geflohen, einer Niederlage durch uns zu entgehen. Da irren sie sich gewaltig.\n\nNehmt Agatha mit Euch zur Insel Fenris und tötet alle Menschen. Sie wird die Gefallenen als Verlassene wiedererwecken und so unsere Streitkräfte verstärken.\n\nEnttäuscht mich nicht, {name}.", sourceObjective = "Erweckt 15 Verlassene, indem Ihr Menschen auf der Insel Fenris tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27098] = { id = 27098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lordaeron", description = "Kommt mit mir zum Grabmal, {name}. Ich möchte vieles mit Euch besprechen. Es ist unabdingbar, dass Ihr die Geschichte von Lordaeron und die Zwangslage der Verlassenen versteht.", sourceObjective = "Begleitet Fürstin Sylvanas Windläufer zum Grabmal im Silberwald.", completion = "Versteht Ihr jetzt die Wichtigkeit unserer Mission hier? Crowley und seine Hunde der Allianz müssen aufgehalten werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[27099] = { id = 27099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Entkommen", description = "Ihr müsst gegen ihre Anführer losschlagen, {name}. Ihr werdet sie in der alten Burg versteckt finden. Kämpft Euch in die Burg durch und findet die Starrköpfe! Verwandelt sie für Eure Königin!\n\nNiemand entzieht sich dem mächtigen Griff der Verlassenen!", sourceObjective = "Findet die Anführer der Flüchtlinge in Burg Fenris.", completion = "Anscheinend muss man Crowley ernster nehmen, als ich gedacht habe. Dennoch, er ist ein Mensch - Fleisch und Blut - voller Geheimnisse. Geheimnisse, die ich alle kenne...\n\nIhr habt mir gute Dienste erwiesen, {name}. Ich könnte jemand mit Euren Fähigkeiten am Grabmal gebrauchen. Ich habe einen Plan, um mit Crowley und seinen Aufrührern endgültig fertigzuwerden. Werdet Ihr mir auch weiterhin zur Seite stehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[27100] = { id = 27100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichtige Forschungen", description = "Das Buch, das Ihr gefunden habt, scheint irgendeine Forschung zu beschreiben, die ein Mitglied des Schattenhammers durchgeführt hat.\n\nEs hat irgendwas mit Schlamm zu tun, aber es fehlen mehrere Seiten.\n\nVielleicht könntet Ihr zusätzliche Notizen finden, damit das Ganze einen Sinn ergibt.", sourceObjective = "Findet in den Oberen Silbermarschen 4 Zwielichtforschungsnotizen über Quecksilberschlamm.", sourceObjectiveStatus = "unverified-source-field" }
quests[27101] = { id = 27101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maziels Enthüllung", description = "Die Notizen führen Maziels Forschungsgeschwafel über die Zusammensetzung von Quecksilber und Quecksilberschlamm fort.\n\nOffenbar hat er eine wichtige Entdeckung gemacht. Er erwähnt, dass er sein Tagebuch in den Unteren Silbermarschen gen Südwesten versteckt hat.", sourceObjective = "Geht zu den Unteren Silbermarschen in Tiefenheim und findet Maziels Tagebuch.", completion = "Maziels Tagebuch scheint vom Quecksilber nicht beschädigt worden zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[27102] = { id = 27102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maziels Aufstieg", description = "Maziels Tagebuch enthält Aufzeichnungen über ein Aufstiegsritual, das seinen Körper in pures Quecksilber verwandeln würde.\n\nDas Ritual soll in einer Höhle in der Nähe der Unteren Silbermarschen stattfinden, wo Maziel sich von Quecksilberschlamm ernähren will, bis er die volle Stärke erreicht hat.\n\nVielleicht ist es noch nicht zu spät, seinem Wahnsinn Einhalt zu gebieten.", sourceObjective = "Tötet Maziel in der Silberlichthöhle in Tiefenheim.", sourceObjectiveStatus = "unverified-source-field" }
quests[27103] = { id = 27103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Splitter der Teufelsranke", description = "Der Satyr Alzzin der Wildformer übt seine verdorbene Herrschaft über diesen Teil von Eldre'Thalas aus. Die korrumpierte Frucht des Gedeihens - die Teufelsranke - sollte sich in Alzzins Nähe befinden. Sie könnte der Schlüssel sein, um diesen uralten Ort zu reinigen.\n\nWenn der große Satyr fällt, versucht so viel wie möglich von der Essenz der Teufelsranke zu erlangen. Versiegelt sie dann in diesem Reliquiar der Reinheit und bringt es zu mir.\n\nViel Glück und Cenarius' Kraft sei mit Euch!", sourceObjective = "Benutzt das Reliquiar der Reinheit, um einen Teufelsrankensplitter einzufangen.", progress = "Mit dem Versiegelten Reliquiar der Reinheit in unserem Besitz wird es nicht nur möglich sein, die Bedrohung der Verderbnis von der Welt zu entfernen, sondern sie auch unter unseren umsichtigen Augen zu studieren. Vielleicht können wir sogar neue Möglichkeiten finden, um das Makel der Verderbnis, das Azeroth bedroht, zu bekämpfen.", completion = "Ihr habt Eure Sache gut gemacht, {class}, und deshalb stehe ich für immer in Eurer Schuld. Obwohl der Krieg noch lange nicht vorüber ist, wurde eine große Schlacht gegen die, die unseren Untergang herbeiführen wollen, gewonnen.\n\nBitte nehmt dies als Zeichen meiner endlosen Dankbarkeit. Wenn wir jemals Düsterbruch reinigen, wisset, das Ihr als Held hier immer willkommen sein werdet. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[27104] = { id = 27104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alzzin der Wildformer", description = "Das Monster, das für die Zerstörung, die Ihr vor Euch seht, verantwortlich ist, heißt Alzzin der Wildformer. Um an ihn heranzukommen, müsst Ihr allerdings Zevrim Dornhuf töten, den Satyr, der den immer noch edlen alten Eisenborke der Große in seinen Klauen hält.\n\nSobald Eisenborke frei ist, wird er Euch helfen, Alzzins Herrschaftsgebiet zu betreten. Geht hinein und tötet ihn, ohne Gnade zu zeigen, denn es gibt keine andere Möglichkeit.", sourceObjective = "Tötet Zevrim Dornhuf und Alzzin den Wildformer.", completion = "Ah, sehr gut gemacht. Ihr habt heute einen alten Geist sehr glücklich gemacht. Ihr verdient angemessenen Dank für die Risiken, die Ihr auf Euch genommen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27105] = { id = 27105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ungebetener Gast", description = "Ihr werdet sehen, dass Düsterbruch voller Natur- und Arkanelementaren ist. Irgendwie hat ein Wasserelementar seinen Weg in diese Gegend gefunden. Bitte beschafft Euch seine Essenz und bringt sie zu mir. Ich bin neugierig, wie es hierhergekommen ist und welche Pläne es in Bezug auf die natürlich vorkommenden Elementare von Eldre'Thalas hat.", sourceObjective = "Findet die Hydrobrutessenz.", progress = "Habt Ihr die Essenz bei Euch oder war die Aufgabe zu schwierig?", completion = "Es ist äußerst besorgniserregend, dass ein Wasserelementar hier war - insbesondere so ein mächtiger. Nehmt dies als Dank für Eure Bemühungen. Ich muss diese Essenz untersuchen, ob sie etwas Wissenswertes verbirgt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27106] = { id = 27106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entlarvung eines Schurken", description = "<Ihr findet eine vollständige Liste aller Kultisten des Schattenhammers in Sturmwind.>\n\n<Was noch wichtiger ist, Ihr entdeckt einen Brief von Major Samuelson an seine Komplizen, der den ganzen Plan darlegt. Der Prinz hatte Recht: Samuelson ist der wahre Verbrecher hier, der seine Verbindungen als Kommandant der Stadtwache dazu nutzt, die Aktivitäten des Kults zu verschleiern.>\n\n<Es wird Zeit, nach Burg Sturmwind zurückzukehren und Samuelson zur Rechenschaft zu ziehen!>", sourceObjective = "Enttarnt und tötet Major Samuelson im Thronraum von Burg Sturmwind.", completion = "Samuelson - vom Schattenhammer bestochen? Das muss schon seit Jahren so gehen. Genau hier in meiner Burg!\n\nIch bin sehr dankbar, dass Ihr und mein Sohn dieser Sache auf den Grund gegangen seid, bevor meine Stadt Schaden nehmen konnte. Ich habe wohl unterschätzt, wie erwachsen Anduin bereits geworden ist - seine Beherrschung des heiligen Lichts hat mir gerade das Leben gerettet...wenn nicht sogar das ganze Königreich.\n\nWas Euch angeht - Worte vermögen Euer Heldentum am heutigen Tag nicht zu beschreiben. Ich danke Euch, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27107] = { id = 27107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pusillin der Dieb", description = "Ich nur kurz Nickerchen vorhin gemacht und blöder schneller Wichtel hat gestohlen Buch! Dagg'thol braucht Buch, um Befehle zu befolgen und Meister braucht Buch zum Erobern! Bah!\n\nIhr {race} helft mir, Buch von Wichtel zurückzuholen und ich gebe etwas Glänzendes. Geht, Wichtel ist da links! TÖTEN!!!", sourceObjective = "Überredet Pusillin, das Buch der Zauberformeln herauszugeben.", progress = "{race} hat Buch?", completion = "Jetzt sehen, wie Meister Buch benutzt und Bäume töten und dumme Ziegenmänner! JA!", sourceObjectiveStatus = "unverified-source-field" }
quests[27108] = { id = 27108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lethtendris' Netz", description = "Blutelf Lethtendris hat Netz zum Fangen von Magie hier. Sie benutzt selbst, aber Meister will benutzen um der ganzen Welt gut zu tun. Helft, Netz von dummer Elfe zu holen und Dagg'thol wird Euch belohnen. Dann Ihr seht, wie Meister es viel besser benutzt!", sourceObjective = "Beschafft Lethtendris' Netz.", progress = "{name}, habt Ihr Netz von dummer Elfe?", completion = "Das Netz hat viel Magie! Meister wird jetzt sehr zufrieden sein!\n\nUnd Ihr macht Dagg'thol zufrieden, {race}. Nehmt dies, damit Ihr wisst, wie glücklich Ihr macht Dagg'thol.", sourceObjectiveStatus = "unverified-source-field" }
quests[27109] = { id = 27109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windschiefe Verteidiger", description = "Eisenborke und Wucherborke waren einst die mächtigen Beschützer von Eldre'Thalas. Schaut, was aus ihnen geworden ist! Ihr Schicksal liegt letztendlich in meinen Händen und denen der anderen Hochgeborenen. Wir sind mit unserer Macht unachtsam umgegangen, {race}.\n\nAber Ihr, Ihr könnt das Unrecht wieder ungeschehen machen! Geht hinaus und bettet Tendris Wucherborke zur Ruhe. Er war der mächtigste und letzte Verteidiger dieses Gebiets und er verdient es, dass sein Geist freigelassen wird. Seid vorsichtig, denn wenn Ihr Euch nicht der Beschützer von Eisenborke entledigt, bevor Ihr Tendris angreift, wird er sie zu Hilfe rufen.", sourceObjective = "Tötet Tendris Wucherborke.", completion = "Eure Arbeit hier war ehrenwert. Grämt Euch nicht, denn Tendris Seele hat danach geweint, sich zur Ruhe begeben zu können. Er ist dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[27110] = { id = 27110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der innere Wahnsinn", description = "Dieser Wahnsinn muss ein Ende haben. Das Zeitalter der Unsterblichen ist lange vergangen. Vernichtet die Wächter rings um die Pylonen herum, um das Kraftfeld zu senken. Wenn das erledigt ist, vernichtet Immol'thar. Die Macht des Prinzen wird durch das Dahinscheiden des Dämons stark geschwächt sein. Greift ihn an und beendet seine Existenz. Gewährt den Geistern dieser Stadt ihre letzte Ruhe, Abenteurer, und lasst den Prinzen für seine Schandtaten bezahlen.", sourceObjective = "Zerstört alle Wächter, die um die 5 Pylonen herumstehen, welche Immol'thars Gefängnis mit Energie versorgen Sobald die Pylone deaktiviert wurden, wird sich das Kraftfeld, das Immol'thar umgibt, auflösen.\n\nBetretet Immol'thars Gefängnis und vernichtet den verdorbenen Dämonen. Zum Schluss müsst Ihr Prinz Tortheldrin im Athenaeum entgegentreten.\n\nKehrt nach Abschluss der Aufgabe zur uralten Shen'dralar im Hof zurück.", completion = "Wir sind Euch zu Dank verpflichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27111] = { id = 27111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schatz der Shen'dralar", description = "In der Bücherei, dem Athenaeum, werdet Ihr unter dem Treppenaufgang eine uralte Truhe finden. Nehmt Euch aus der Truhe, was Ihr wollt.", sourceObjective = "Kehrt in das Athenaeum zurück und sucht den Schatz der Shen'dralar. Nehmt Euch Eure Belohnung!", completion = "Ihr öffnet die Truhe und findet...", sourceObjectiveStatus = "unverified-source-field" }
quests[27112] = { id = 27112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfluchte Überreste", description = "Es gibt immer noch einige Wesen, die eine Gefahr darstellen, sollten wir diese heilige Stadt zurückerobern wollen. Magister Kalendris und Illyanna Rabeneiche sind beide äußerst gefährlich und wir müssen uns ihrer so schnell wie möglich entledigen.\n\nSeid vorsichtig, denn jetzt, da nur noch so wenige sich von Immol'thars Energien nähren, sind sie wahrscheinlich stärker, als es auf den ersten Blick scheint.", sourceObjective = "Tötet Magister Kalendris und Illyanna Rabeneiche.", completion = "Euer Engagement wird all dies so viel einfacher machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27113] = { id = 27113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Uralte Shen'dralar", description = "Einige Wesen haben es auf wundersame Weise geschafft, der Dunkelheit zu entgehen, die hier ihr Unwesen treibt. Auf der zweiten Etage am Hof der Hochgeborenen ruht ein Uralter Shen'dralar. Sucht ihn auf, er ist möglicherweise ein unerschöpflicher Quell der Weisheit und kennt vielleicht sogar das Geheimnis, wie man Eldre'Thalas befreit.", sourceObjective = "Sprecht mit dem Uralten Shen'dralar.", completion = "Unser Treffen ist kein Zufall, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27114] = { id = 27114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gordokgeschmackstest", sourceObjective = "Ihr seid nun großer Boss, also kriegt ihr kostenlose Probe meiner guten Gebräue! Diese Getränke stärken Euch UND geben eine gute Dröhnung! Das ist gutes Zeug, Chef... probiert sie und erzählt Kreeg davon!", sourceObjectiveStatus = "unverified-source-field" }
quests[27115] = { id = 27115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andos Ruf", description = "Ihr habt hier großartige Arbeit geleistet, {name}. Als Ihr fort wart, hat dieser junge Bursche Ando nach Euch gesucht. Sagte was von einem Metallvogel.\n\nVielleicht solltet Ihr zu den Ufern des Loch zurückkehren und nachsehen, was er wollte.", sourceObjective = "Sprecht mit Ando Blastenheimer.", completion = "Es funktioniert! Mein Vater hat es geschafft!", sourceObjectiveStatus = "unverified-source-field" }
quests[27116] = { id = 27116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Winde von Loch Modan", description = "Vater hat den Himmelsschreiter fertiggestellt. Er ist großartig! Wenn wir erst einmal die Kinderkrankheiten ausgemerzt haben, werde ich ihn benutzen, um für die Gerechtigkeit zu kämpfen - genau, wie Ihr.\n\nIch weiß, Ihr müsst weiterziehen und anderen Menschen helfen. Schließlich seid Ihr ein Held und so, aber wie wäre es mit einem Probeflug? Ich will den Himmelsschreiter gerade zu seinem Jungfernflug hinausbringen und es wäre mir eine Ehre, wenn Ihr Euch mir anschließen würdet. Ich setze Euch bei der Station Algaz ab.\n\nWas meint Ihr?", sourceObjective = "Fliegt mit dem Himmelsschreiter zur Station Algaz und sprecht dann mit Gebirgsjäger Sturmlanze.", completion = "Was zum Henker WAR das? Ein fliegender Mechanoschreiter?\n\nWisst Ihr was, ich will es gar nicht wissen. Ich tue einfach so, als wäre das nicht passiert und wir unterhalten uns nett wie Geschäftsleute.", sourceObjectiveStatus = "unverified-source-field" }
quests[27117] = { id = 27117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rohe Gewalt", description = "Gandling hat seinen Leutnant, den Ravenier, zur Unterstützung mitgebracht. Dieser trampelnde Rohling ist viel gefährlicher als jede andere Geißel und Monstrosität, die Euch auf dem Schlachtfeld begegnen wird.\n\nDer Ravenier befindet sich in einem Turm am südlichen Ende des Orts. Ich empfehle Umsicht, bevor Ihr mit ihm kämpft, {name}. Er ist kein leichter Gegner.", sourceObjective = "Tötet den Ravenier in Andorhal.", completion = "Ausgezeichnet gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27118] = { id = 27118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine beschädigte Falle", sourceObjective = "Eine große, beschädigte Falle liegt vor Euch. Es sieht so aus, als hätten die Oger erfolglos versucht, sie zu reparieren.\n\nNeben der Falle liegt eine hastig geschriebene Notiz, die seltsamerweise genau beschreibt, wie sie zu reparieren ist. Ein paar Handgriffe reichen. In einer reparierten Falle würde sich ein Oger, der nahe an ihr vorbeigeht, vielleicht verfangen und könnte vermieden werden.\n\nEs ist wirklich gut, dass so wenige Oger lesen können.\n\nWirklich.", sourceObjectiveStatus = "unverified-source-field" }
quests[27119] = { id = 27119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ogeranzug der Gordok", description = "Wenn Ihr vorhabt, gegen den König der Gordok zu kämpfen, dann werden Ihr es erstmal an Hauptmann Krombruch vorbei schaffen müssen. Sicher könnt Ihr ihn einfach töten. Doch vielleicht wollt Ihr diesen Oger ja am Leben lassen. \n\nEs stellt sich nur die Frage, wie? Ich glaube ich weiß, wie! Ein Ogeranzug! Ich kann Euch einen herstellen, der ausreicht, um diese Kerle zu täuschen, wenn Ihr mir Ogergerbemittel von oben herbringt. So wie die Dinge stehen, gehe ich nirgendwohin.", sourceObjective = "Bringt etwas Ogergerbemittel zu Knot Zwingschraub.", progress = "Bringt mir einfach dieses Ogergerbemittel und ich stelle Euch einen Anzug her, der Hauptmann Krombruch glauben lassen wird, dass Ihr einer seiner Männer seid.", completion = "Das sollte gehen. Ein Schnitt hier, ein Stich da... - das wird ein richtiges Meisterwerk! <Ein breites Grinsen zeichnet sich im Gesicht des Goblins ab.>\n\nHier, damit seid Ihr vorbereitet. Denkt daran - der Ogeranzug ist alles andere als haltbar. Nachdem Ihr ihn angezogen habt, bleiben Euch zehn Minuten bevor er auseinanderfällt und dann ist's aus mit der Täuschung! Benutzt ihn erst kurz bevor Ihr Krombruch begegnet, damit er so lange hält, wie Ihr ihn braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[27120] = { id = 27120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ogeranzug der Gordok", progress = "Braucht wohl einen neuen Anzug, oder? Na, ich werde wohl eh noch eine Weile hier sein - bringt mir noch ein Ogergerbemittel, dann mache ich Euch einen neuen Ogeranzug.", completion = "Bitte schön, {name} - leg das Ding an, dann habt Ihr zehn Minuten Zeit, irgendwas zu tun. Viel Glück!\n\nOh, und solltet Ihr zufällig einen Schlüssel finden, mit dem ich hier raus komme, LASST MICH DAS RUHIG WISSEN!!!" }
quests[27123] = { id = 27123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefenheim, Reich der Erde", description = "Ich wusste, Ihr würdet unserem Ruf Folge leisten, {name}. Als Todesschwinge das erste Mal von den anderen Drachenaspekten besiegt wurde, zog er sich nach Tiefenheim, im Reich der Erde, zurück.\n\nTodesschwinges Rückkehr in unsere Welt hinterließ einen Riss zwischen Azeroth und Tiefenheim.\n\nWenn wir die Lücke nicht schließen, wird dieses Land auseinandergerissen werden. Wir tun unser Bestes, um den Schaden, der diesseits des Risses entsteht, in Grenzen zu halten. Aggra wird Euch durch den Riss mitnehmen, damit Ihr helfen könnt, den Schaden von der anderen Seite aus zu reparieren.\n\nSchwingt Euch auf ihren Wyvern, wenn Ihr bereit seid.", sourceObjective = "Springt auf Aggras Wyvern und fliegt in die Bresche am Mahlstrom. Wenn Ihr auf der anderen Seite ankommt, sprecht mit Maruut Steinbinder.", completion = "Ihr seid genau rechtzeitig eingetroffen, {name}. All unsere Helfer sind damit beschäftigt, den Riss zu stabilisieren.\n\nWir brauchen jemanden, der uns dabei hilft, die Fragmente der Weltensäule zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27124] = { id = 27124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die offene Rechnung der Gordok", description = "Nun Ihr de' König sein, vielleicht Ihr kriegen zurück wertvolles Artefakt der Gordok von Wächter Mol'dar! König vor Euch hat versagt, so wie alle Könige seit Tortheldrin - de' gruselige Elf - es gestohlen hat, von damaligen Gordokkönig!\n\nArtefakt heißen Stulpen der Gordokmacht. Alte Zeit Geschichten sagen, nur de' wahre König de' Gordok kann sie zurückholen. Alte Zeit Geschichten sagen auch, de' gruselige Elf ist immer noch hier - Ihr finden es und es werden Eure mächtigen Stulpen, für immer! Yar, ich zeigen!", sourceObjective = "Sprecht mit Wache Mol'dar in Düsterbruch.", completion = "Wow... Ihr SEID de' wahre König! Alter König niemals auch nur nach Stulpen gefragt!\n\nGuckt - dieses Zeichen auf de' Stulpen ist ein sehr sehr SEHR altes Zeitsymbol. Älter als Gordok, sagen sie. Nun, als kleiner Oger bekommen eins beigebracht: Wie man machen Zeichen wieder lebendig, um geben den Stulpen die Kraft zurück!\n\nIch werde es für Euch tun, König! Hier, nehmen Stulpen und herrschen AUF EWIG!", sourceObjectiveStatus = "unverified-source-field" }
quests[27125] = { id = 27125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "König der Gordok", description = "Bei den Gordok, ist der stärkste Krieger der König. Wenn jemand, egal ob Oger oder sonstwer, den amtierenden König tötet, wird er automatisch als neuer König begrüßt.\n\nDer neue König erhält Tribut von allen lebenden Wachen, Stampfer Kreeg und Hauptmann Krombruch. Findet und tötet König Gordok, aber tötet so wenig der anderen Anführer wie möglich. Ihr werdet nicht nur eine reiche Belohnung erhalten, sondern könnt Eure Macht als König benutzen, um die Invasion der Gordok ohne Konflikt zu verhindern!", sourceObjective = "Tötet König Gordok.", completion = "Ja! Ich sehe, Ihr wart erfolgreich. Ihr habt Euren Tribut erhalten, den Vormarsch der Gordok gibt es nicht mehr und die Gordok haben von all dem keine Ahnung! Das ist das Szenario eines Gewinners, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27126] = { id = 27126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eilige Lieferung", description = "Spitz Schleifsteins Team hatte irgendwo im Westen eine Panne.\n\nMeint Ihr, Ihr könnt Euch zur Abwechslung mal nützlich machen und einige Ersatzteile zu ihnen hinausbringen, {race}?", sourceObjective = "Liefert die Katapultteile bei Spitz Schleifstein an der Zerrissenen Front in Tiefenheim ab.", progress = "Habt Ihr da die Ersatzteile?", completion = "Ich kann Euch nicht genug danken, {class}. Dann lasst uns mal sehen, ob wir das Katapult wieder in Bewegung bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27128] = { id = 27128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "König der Gordok", description = "Du tötest Anführer der Gordok, du neuer Ogerkönig. Wenn du König, dann überlebende Ogeranführer wie Kromcrush und Kreeg zahlen großen Tribut und du beendest Gordokinvasion. Wenn du das tust, dann ich sehr glücklicher Oger und wir nehmen Düsterbruch FÜR DIE HORDE!!!\n\nGeht, kleiner {race}! Tötet hässlichen Gordok Ogerkönig und vielleicht das hier neue Steinbrecherfestung! Yar!", sourceObjective = "Tötet König Gordok.", completion = "Kleiner {race} hat es geschafft! Horde jetzt mächtiger denn je! YAR!", sourceObjectiveStatus = "unverified-source-field" }
quests[27129] = { id = 27129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wucherborke retten", description = "Direkt im Ostflügel von Düsterbruch lebt eines der Urtume der Wucherborken, Furugs Wucherborke, noch vollkommen unverdorben. Ihr müsst dorthin reisen und ihm helfen, die furchtbaren Kreaturen zu vertreiben, die alles für sich einnehmen. Düsterbruch einzunehmen wäre ein Riesenfortschritt, Feralas für unser Volk wieder zurückzuerobern.\n\nIhr findet Düsterbruch südöstlich von hier.", sourceObjective = "Sprecht mit Furgus Wucherborke.", completion = "Seid Ihr in letzter Zeit einem Druiden der Kralle begegnet, {class}? Die Anwesenheit eines solchen Druiden hängt in der Luft.", sourceObjectiveStatus = "unverified-source-field" }
quests[27130] = { id = 27130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wucherborke retten", description = "Direkt im Ostflügel von Düsterbruch lebt eines der Urtume der Wucherborken, Furugs Wucherborke, noch vollkommen unverdorben. Ihr müsst dorthin reisen und ihm helfen, die furchtbaren Kreaturen zu vertreiben, die alles für sich einnehmen bevor sie Camp Mojache entdecken. Vielleicht können wir uns seiner Hilfe für später versichern, um unsere Anwesenheit in Feralas zu sichern, wo wir doch von Feinden umzingelt sind.", sourceObjective = "Sprecht mit Furgus Wucherborke.", completion = "In Eurem Gesicht sehe ich Anzeichen für einen verzweifelten Kampf. Eure Gegenwart ehrt mich, mutiger {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27131] = { id = 27131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hochgeborene", description = "Estulan, ein mächtiger und unverdorbener Hochgeborener, hat sich Zutritt zum westlichen Flügel von Düsterbruch verschafft und bittet um Mithilfe, diesen zu säubern. Ungeachtet Eurer persönlichen Ansichten über die Hochgeborenen, muss ich diese Bemühung zum Wohle von Feralas gutheißen. Möge der Wind Euren Geist mit großer Geschwindigkeit dorthintragen.\n\nIhr findet Düsterbruch südöstlich von hier.", sourceObjective = "Sprecht mit Estulan.", completion = "Ich spürte auf dem ganzen Weg von Träumersruh, dass Ihr kommen würdet. Eure Hilfe wäre mir sehr willkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27132] = { id = 27132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hochgeborene", description = "Estulan, ein mächtiger und unverdorbener Hochgeborener, hat sich Zutritt zum westlichen Flügel von Düsterbruch verschafft und bittet um Mithilfe, diesen zu säubern. Ungeachtet Eurer persönlichen Ansichten über die Hochgeborenen, muss ich diese Bemühung zu unserem Wohle gutheißen. Bitte beeilt Euch - wir brauchen jeden Fuß in der Tür von Feralas, den wir bekommen können.\n\nIhr findet Düsterbruch im Westen.", sourceObjective = "Sprecht mit Estulan.", completion = "Ich spürte auf dem ganzen Weg von Camp Mojache, dass Ihr kommen würdet. Eure Hilfe wäre mir sehr willkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27133] = { id = 27133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blick zum Himmel", description = "Die schlimmste und am besten organisierte Gefahr in Feralas stellen für uns die Oger der Gordok am nördlichen Flügel von Düsterbruch dar. Ich habe einen Druiden der Kralle beauftragt, sich dorthin zu begeben und die Lage zu erkunden. Meldet Euch bei ihm, falls er noch am Leben ist. Er wird Euch befehligen, um die Gordok aufzuhalten, bevor sie sich zum Angriff entscheiden.\n\nDas ist ein Befehl, {class}.", sourceObjective = "Sprecht mit dem Druiden der Kralle.", completion = "Sprecht leise, {name}. Die Gordok sind zwar nicht sehr schlau, aber sie sind trotzdem gefährliche Krieger.", sourceObjectiveStatus = "unverified-source-field" }
quests[27134] = { id = 27134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oger im Feld", description = "Die schlimmste und am besten organisierte Gefahr in Feralas stellen für uns die Oger der Gordok am nördlichen Flügel von Düsterbruch dar. Wenn wir sie auslöschen und Düsterbruch für die Horde in Anspruch nehmen, könnten wir unsere Machtposition in dieser artefaktreichen Gegend enorm stärken. Ich habe vor kurzer Zeit eine kleine Truppe Oger der Steinbrecher losgeschickt. Sprecht mit möglichen Überlebenden und beendet, was begonnen wurde.\n\nDas ist ein Befehl, {class}.", sourceObjective = "Sprecht mit dem Oger der Steinbrecher.", completion = "Diese Oger keine Knallschoten. Hilf mir, Orhans Aufgabe zu vollenden, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27135] = { id = 27135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas, das brennt", description = "Also, wir brauchen etwas, mit dem das Präparat in die Luft fliegt - KABUMM!\n\nIch habe kein Schießpulver mehr, aber ich habe eine Idee, was wir stattdessen verwenden können ... das Herz meines Feuerelementars!\n\nHier, nehmt mein Feuertotem mit nach Osten auf Eurem Weg zum Blutpfad. Betätigt es dort in der Nähe der Lavaseen, und Magmazahn sollte erscheinen. Bringt mir sein Herz, dann unterhalten wir uns weiter.", sourceObjective = "Erhaltet das brennende Herz.", progress = "Habt Ihr das Herz schon?", completion = "Oha. Es scheint, als hätte die Situation ihn nicht gerade erfreut. Wie hätte ich das wissen können? Ich bin doch nur ein Initiand.\n\nWie dem auch sei. Über Magmazahn sorge ich mich später.", sourceObjectiveStatus = "unverified-source-field" }
quests[27136] = { id = 27136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementarenergie", description = "Wir müssen unsere ganze Kraft aufbringen, um die Stabilität des Reichs in der Abwesenheit der Weltensäule sichern zu können.\n\nAls Schamanen können wir direkt die Energien der Elementare von Tiefenheim anzapfen und zur Heilung für vom Riss verursachten Schaden nutzen.\n\nNehmt dieses Totem und platziert es außen auf dem Boden. Alle aufgeladenen Geoden oder zerstörten Leitsteinelementare in der Nähe werden es mit der Energie füllen, die wir benötigen.", sourceObjective = "Zerstört 8 aufgeladene Geoden oder Leitsteinelementare in der Nähe des erschöpften Totems.", completion = "Ich danke Euch, {name}. Wir benötigen alle Kraft, die wir aufbringen können, um die Stabilität von Tiefenheim zu sichern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27139] = { id = 27139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hobart braucht Euch", description = "He da, Boss! Hobart Wurfhammer möchte mit Euch sprechen. Er sagt, es wäre eine Angelegenheit von höchster Dringlichkeit!", sourceObjective = "Sprecht mit Hobart Wurfhammer in Instastadt auf den Verlorenen Inseln.", completion = "Da seid Ihr ja, mein Junge! Ich habe etwas äußerst Wichtiges, was Ihr für mich erledigen müsst.", sourceObjectiveStatus = "unverified-source-field" }
quests[27140] = { id = 27140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alexis Gambit", description = "Ich benötige Eure Hilfe, {class}. Findet den Untoten Magier Vectus und den Krieger Marduk hier in den Tiefen. Sie sind mit der Operation des verseuchten Drachen der Geißel beschäftigt und müssen aufgehalten werden.\n\nPlatziert das Gambit in dem Vorführraum, in dem sie sich befinden. Hoffentlich entsteht eine Reaktion mit ihren Kräften und zerstört sie!\n\nOh, Vectus und Marduk danach zu bewältigen dürfte auch kein Problem darstellen, oder?", sourceObjective = "Platziert das Gambit im Vorführraum und tötet Vectus und Marduk.", completion = "Ihr habt es geschafft! Sie sind besiegt! Und das Gambit - hat es funktioniert?\n\nSehr interessant. Ihr habt gute Arbeit geleistet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27141] = { id = 27141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosiv", description = "Was für ein Fund!\n\nGenau hier... genau an der Stelle, die in meinen Notizen vorhergesagt wurde.\n\nMit ein wenig Glück werden sich in dieser Kammer Hinweise zum Verbleib der legendären Lade der Verheißung finden lassen.\n\nJa, das stimmt, {name}. Es ist nicht nur eine Legende. Ich glaube, dass es die Lade wirklich gibt.\n\nIch werde Euch später mehr erklären. Helft mir jetzt erstmal mit diesen Sprengsätzen.", sourceObjective = "Helft Harrison Jones am Grab des Khartut.", completion = "Schüttelt es ab, Kleiner.\n\nPassiert mir ständig...", sourceObjectiveStatus = "unverified-source-field" }
quests[27142] = { id = 27142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Lich Ras Frostraunen", description = "Einer der Studenten, denen Kel'Thuzad viel Vertrauen schenkt, leitet die Operationen in Scholomance. Tretet dem Lich Ras Frostraunen in seinem Unterschlupf gegenüber. Die hintere Tür im Vorführraum führt in seine Kammer.\n\nZerstört ihn, {name}. Löscht jeglichen Nachweis seiner Existenz aus, so dass er nie wieder solche Schrecken in unsere Welt bringen kann.", sourceObjective = "Vernichtet Ras Frostraunen.", completion = "Abertausende Seelen schreien im Einklang aus, {name}. Ihr habt mit einem tödlichen Schlag die Geißel und ihre Meister vernichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27143] = { id = 27143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Familienvermögen der Barovs", description = "Das Familienvermögen der Barovs liegt in Scholomance. Alexi und ich sind die beiden letzten verbliebenen Erben des Hauses Barov.\n\nIch bin jedoch der letzte Barov, der am Leben ist, und somit ist das ganze Reich der Barovfamilie mein! Findet die Besitzurkunden für Darrowehr, Brill, Tarrens Mühle und Süderstade, und ich werde Euch mit großem Reichtum belohnen. Der Besitz der Barov wird endlich wieder in voller Blüte stehen!", sourceObjective = "Findet die Besitzurkunde für Darrowehr, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Süderstade.", progress = "Verneigt Euch in meiner Gegenwart, {race}. Ich bin immerhin von Adel, und Ihr seid nur ein armer Bauer.", completion = "Ihr habt vorzügliche Arbeit geleistet, {race}. Für diese Torheit verdient Alexi kein Lob.", sourceObjectiveStatus = "unverified-source-field" }
quests[27144] = { id = 27144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Abrechnung", description = "Ihr habt eine vortreffliche Leistung vollbracht. Ihr erfüllt die Verlassenen mit Stolz, was ich von Kriegsherr Koltira Todesweber nicht behaupten kann.\n\nIch habe vor, ein ernstes Wörtchen mit diesem Todesritter zu wechseln. Er hat Schande über sich und das, wofür er steht, gebracht.", sourceObjective = "Wartet, bis Fürstin Sylvanas Windläufer mit Koltira Todesweber gesprochen hat.", completion = "Ich habe nichts gegen die Ritter der Schwarzen Klinge, aber Koltira muss sich im Klaren darüber sein, für wen er arbeitet. Seine Loyalität muss einzig und allein der Horde gelten.\n\nGenauer gesagt, den Verlassenen.\n\nIch würde mich nicht darauf verlassen, Koltira bald wieder zu sehen. Jetzt, da ich ihn habe ... könnt Ihr Euch sicher sein, dass alle seine Verbindungen zu irgendwelchen Allianzlern vollständig zerstört werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27145] = { id = 27145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verseuchte Jungtiere ... im Moment", description = "Eines der aktuellen ‚Projekte‘ ist der verseuchte Drachenschwarm. Glücklicherweise handelt es sich dabei um Jungtiere, aber wenn wir noch länger warten, werden sie zu einer der mächtigsten Waffen im Arsenal der Geißel und eine ernst zu nehmende Gefahr für Azeroth, und vor allem für die Ländereien meiner Familie.\n\nErschlagt zehn der Jungtiere und vergesst nicht, Euch auch um Blutrippe zu kümmern. Ihr findet ihn in der Nähe der Behausung der Jungtiere, wo er Nahrungsergänzungen zubereitet, die das Wachstum ankurbeln sollen. Beeilt Euch - bevor sie noch größer werden!", sourceObjective = "Tötet 10 verseuchte Jungtiere und Blutrippe.", completion = "Gute Arbeit, {name}. Es wird lange dauern, bis unser Feind eine neue Generation dieser Drachen züchten kann.\n\n... Zumindest hoffe ich das!", sourceObjectiveStatus = "unverified-source-field" }
quests[27146] = { id = 27146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doktor Theolen Krastinov, der Schlächter", description = "Doktor Theolen Krastinov ist für die Tode Tausender verantwortlich. Seinen Spitznamen ‚der Schlächter‘ hat er sich mit den Gräueltaten, die ihm so viel Freude bereiten, redlich verdient. Er muss im Namen der Gerechtigkeit bestraft werden.\n\nSucht ihn und bringt jene Qual über ihn, die er über zahllose Unschuldige wie mich und meinem Ehemann gebracht hat. Wenn er vernichtet ist, verbrennt unsere Überreste. Verwandelt sie in Asche, {name}. Befreit unsere schmerzenden Seelen.", sourceObjective = "Vernichtet Doktor Theolen Krastinov, und verbrennt die Überreste von Eva Sarkhoff und die Überreste von Lucien Sarkhoff.", completion = "Ich fühle, wie mein Geist heilt, {name}. Ihr habt meinem Ehemann und mir einen großen Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27147] = { id = 27147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kirtonos der Herold", description = "Mit Blut lässt Kirtonos sich anlocken. Also wird es Blut sein, das Kirtonos zerstören wird.\n\nIn der Kammer der Beschwörung werdet Ihr eine Kohlenpfanne finden, über der Ihr einen Tropfen Eures eigenen Blutes vergießen müsst. Kirtonos wird erscheinen - er kann nicht widerstehen. Entfesselt sobald er auftaucht den Zorn und Furor Tausender Unschuldiger.\n\nSollte Ihr erfolgreich sein, werdet Ihr mehr als nur unseren Dank erhalten.", sourceObjective = "Zerstört Kirtonos.", completion = "Mit dem Tod Kirtonos wird ein schreckliches Kapitel der Geschichte von Scholomance abgeschlossen. Ihr habt für Euren Mut nun für immer meine tiefste Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[27148] = { id = 27148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Sommerferien", description = "Dunkelmeister Gandling ist der Direktor von Scholomance und daher für die zahllosen Tode verantwortlich, die seine Schüler für ihn ausführten. Dafür muss er bestraft werden.\n\nEr wird nicht so einfach aus seinem Arbeitszimmer kommen. Lockt ihn heraus, indem Ihr die sechs Professoren tötet, deren Zimmer zum Arbeitszimmer des Direktors führen. Seid vorsichtig, denn wenn der letzte Professor erledigt ist, wird er mehr als erzürnt erscheinen und mit überwältigender Magie angreifen. Seht zu, dass er es nicht aus dem Arbeitszimmer schafft.", sourceObjective = "Tötet Dunkelmeister Gandling.", completion = "Ohne einen Direktor wird die Schule im Chaos versinken, und es werden nicht noch mehr dieser abscheulichen ‚Studenten‘ ausgebildet. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[27149] = { id = 27149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schule der Verdammten", description = "Seid gegrüßt! Wie Ihr sehen könnt, sind die Westlichen Pestländer von beinahe allen Restposten der Geißel befreit. Allerdings ist Scholomance, die Schule der Totenbeschwörung, noch voller junger Seelen, die nur darauf warten, ihre Ausbildung zu Zauberern der Geißel abzuschließen. Unsere Arbeit wird umsonst gewesen sein, wenn wir dem ständigen Nachrücken immer neue - und vorallem auch mächtiger - Totenbeschwörer kein Ende setzen.\n\nReist südöstlich nach Scholomance und sucht Weldon Barov. Er ist der letzte lebende Nachkomme der Familie Barov, der einst alle diese Ländereien gehörten, und er ist unser Kontakt vor Ort.", sourceObjective = "Sprecht mit Weldon Barov in Scholomance.", sourceObjectiveStatus = "unverified-source-field" }
quests[27150] = { id = 27150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stätte der Heiler", description = "Wahrscheinlich wird die Schlacht um Andorhal bald wieder wüten. In der Zwischenzeit solltet Ihr Eure Fähigkeiten als {class} verfeinern.\n\nÖstlich von hier befindet sich ein großer Bauernhof, der von der Argentumdämmerung und dem Zirkel des Cenarius eingenommen worden ist. Ich bezweifle nicht, dass Ihr dort Arbeit finden werdet.", sourceObjective = "Meldet Euch bei Außenagent Kaartish in der Stätte der Heiler in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27151] = { id = 27151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taelan Fordrings Vermächtnis", description = "Seid gegrüßt. Wie geht es Euch? Mein Name ist Daria.\n\nIch bin eine der Priesterinnen, die für den Erhalt des Friedens hier in Herdweiler zuständig ist. Eine meiner Aufgaben ist die Verwaltung des Turms entlang des Wegs südöstlich von Herdweiler. Dieser Turm ist von persönlicher Bedeutung für den Hochlord. Sein Sohn wurde dort getötet.\n\nDie Verwaltung des Turms bereitet jedoch aufgrund des feindlichen Einfalls der Gnolle vor Kurzem zunehmend Schwierigkeiten. Könnt Ihr mir helfen, den Weg von den Vandalen der Gnolle zu räumen, sodass ich meinen Pflichten nachkommen kann?", sourceObjective = "Tötet 10 Plünderer der Rotkiefer.", sourceObjectiveStatus = "unverified-source-field" }
quests[27152] = { id = 27152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungewöhnliches Verhalten ... selbst für Gnolle", description = "Ich muss mich kurz konzentrieren.\n\n<Ihr fühlt, wie Darias Gedankensicht einen anderen Ort aufsucht, und dann wieder zu Euch zurückkehrt.>\n\nSüdlich des Turm von Taelan haben die Gnolle einen Ort der Zusammenkunft errichtet - folgt dem Weg, und haltet Euch östlich der Hauptstraße. Dort geht etwas vor sich ... aber ich bin nicht sicher, was es ist. Wir sollten mehr darüber in Erfahrung bringen. Ich werde nach ungewöhnlichen Ereignissen Ausschau halten ... Ihr solltet Euch damit beschäftigen, Euch zu schützen.", sourceObjective = "Erkundet das Versteck der Gnolle entlang des Wegs nach Herdweiler in den Westlichen Pestländern.", completion = "Gnolle und Totenbeschwörung? Das ist eine Überraschung! Und ich dachte, dass hier in den Westlichen Pestländern diese dunklen Tage der Vergangenheit angehören würden.\n\n<Ihr spürt, wie Daria etwas auf dem Boden genau betrachtet.>\n\nWartet ... was ist DAS?", sourceObjectiveStatus = "unverified-source-field" }
quests[27153] = { id = 27153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die braven Bürger von Herdweiler", description = "Seht Ihr die Reagenzien dort drüben? Und diese Ladungen hier? Es handelt sich dabei um das Eigentum der Argentumkreuzfahrer.\n\nGnolle sind für das Stehlen von Gütern bekannt, aber meines Wissens gab es in Herdweiler seit dem Einfall der Rotkiefer keine Vorfälle mehr. Das ist sehr merkwürdig.\n\nIch habe ein paar Kontakte in Herdweiler, die Euch helfen könnten: Morris Vant, Ausstatter Mendelev, Bree Eisenstock und der Hohe Kleriker Alphus. Ihr könnt ihnen vertrauen, und sie haben gute Verbindungen. Befragt sie, um herauszufinden, ob sie etwas über die verlorengegangenen Ladungen wissen.", sourceObjective = "Sprecht mit Morris Vant, Ausstatter Mendelev, Bree Eisenstock und dem Hohen Kleriker Alphus in Herdweiler.", sourceObjectiveStatus = "unverified-source-field" }
quests[27154] = { id = 27154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bisp festsetzen", description = "Magus Bisp ist einer der renommiertesten Arkanisten von Herdweiler. Die Vorstellung, dass er sich mit Gnollen abgibt ... und sich in der Totenbeschwörung versucht? Undenkbar.\n\nIhr werdet Ihn oben im Turm in der Nähe des Haupttors von Herdweiler finden können. Hoffentlich hat er eine Erklärung für das Ganze. Falls nicht, dann... In jedem Fall solltet Ihr den Magierturm nicht unvorbereitet betreten, {name}.", sourceObjective = "Sprecht mit Magier Bisp im oberen Teil des Magierturms in Herdweiler.", sourceObjectiveStatus = "unverified-source-field" }
quests[27155] = { id = 27155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sich stellen", description = "So... Ihr habt also einen Argentumkreuzfahrer getötet, mitten in Herdweiler. Normalerweise wird so was nicht so einfach abgetan, selbst wenn es sich um Selbstverteidigung handelt.\n\nIch schlage vor, Ihr folgt mir nach Burg Mardenholde und stellt Euch Hochlord Fordring. Wenn Ihr Glück habt, wird er Euch anhören und Verständnis für Eure Situation zeigen. Ich hoffe, ich habe Euch nicht in Schwierigkeiten gebracht.", sourceObjective = "Meldet Euch bei Hochlord Tirion Fordring in Herdweiler in den Westlichen Pestländern.", completion = "Mir sind Eure Taten bekannt, {name}. Ich heiße Euch in meiner Stadt willkommen, gebe Euch meinen Segen und was macht Ihr?\n\nIhr tötet den Verräter, den wir schon seit Wochen jagen. Gut gemacht. Euer Heldenmut erblüht viel früher, als ich erwartet hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[27156] = { id = 27156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es wird langsam Zeit!", description = "Endlich! Ihr seid hier! Fangt mit der Arbeit an!\n\nMeine Männer haben schon zu lange nur mit diesen hölzernen Trainingsattrappen gekämpft. Sicherlich lässt sich das Schwingen eines Schwertes auch mit einer Trainingsattrappe erlernen, doch für den Kampf bedarf es eines echten Kämpfers.\n\nHmmm... Ich hatte ausdrücklich nach jemand mit einer eindrucksvollen Statur gefragt, aber in diesem Fall muss wohl <ein/eine:r> {race} mit dünnen Ärmchen herhalten.\n\nKommt her und zeigt meinen Männern, wie man kämpft!", sourceObjective = "Fordert 7 Lehrlinge von Herdweiler zum Kampf heraus und besiegt sie.", completion = "Ich sehe gerade meine Unterlagen durch, und hier steht, dass ein {race} hier eintreffen soll. Ihr seht nicht gerade aus wie, ähm ...\n\n\n\nEgal. Es scheint, als wärt Ihr nicht die Person, die ich ursprünglich beauftragt hatte, aber Ihr habt gute Arbeit geleistet. Ich werde Euch also bezahlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27157] = { id = 27157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akkordarbeiter... <Seufz>", description = "Oh, mir ist Euer Name entgangen. {name}? Es freut mich, Eure Bekanntschaft zu schließen, {name}.\n\nIch habe noch ein anderes Problem, bei dem ich Hilfe gebrauchen könnte, und Ihr habt etwas an Euch, dass gerade danach schreit, nach Hilfe gefragt zu werden.\n\nAm nördlichen Rand von Herdweiler ist eine kleine Mine, aus der wir den Großteil des für unsere Stadt benötigten Erz beziehen. Die Akkordarbeiter in der Mine verrichten normalerweise gute Arbeit.\n\nAllerdings scheint es leider, als habe eine überdurchschnittlich große Spinne sich in der Höhle häuslich eingerichtet. Meint Ihr, Ihr könnt Euch der Sache annehmen?", sourceObjective = "Tötet Shadril in der Mine in Herdweiler.", completion = "Gute Arbeit! Wenn ich zurückblicke, bin ich fast froh, dass dieser andere {class} nicht aufgetaucht ist ... Ihr habt Euch als Lösung all meiner Probleme herausgestellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27158] = { id = 27158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Andorhal", description = "Beeilt Euch, {name}... es gilt, keine Zeit zu verlieren.\n\nDie Stadt Andorhal befindet sich inmitten eines Krieges zwischen den Verlassenen, der Allianz und der Geißel. König Wrynn hat den Stein ins Rollen gebracht und einen Todesritter geschickt, um den Angriff in die Wege zu leiten. Ich bin aber sicher, dass er alle Hilfe brauchen wird, die er kriegen kann. Mit dem Tod von Arthas ist die Zeit für die Allianz gekommen, Lordaeron zurückzuerobern.\n\nMeldet Euch bei Greifenmeister Bibilfaz Federpfiff, wenn Ihr bereit seid und er wird Euch mit dem nächsten Greifen losschicken.", sourceObjective = "Meldet Euch bei Thassarian in Andorhal in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27159] = { id = 27159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erst die Geißel ... dann die Horde", description = "Dunkelmeister Gandling vom Kult der Verdammten führt die Offensive der Geißel hier in Andorhal an. Mein ehemaliger Mitstreiter Koltira leitet die Streitkräfte der Verlassenen. Um Andorhal einzunehmen, müssen wir beide Streitmächte besiegen. Eine Niederlage ist gewiss, wenn wir versuchen, uns beiden auf einmal zu stellen.\n\nIch kenne Koltira gut genug, um zu wissen, dass er sich zuerst auf die Geißel konzentrieren wird. Wir werden es ihm gleichtun.\n\nSetzt die schwächeren, vertrockneten Geißeldiener außer Gefecht, um ihre Zahlen zu schwächen. Die Verlassenen werden darauf warten müssen, unseren Zorn zu spüren.", sourceObjective = "Tötet 15 ausgedörrte Geißeldiener in Andorhal.", completion = "Ihr reagiert zwar nicht schnell, doch immerhin enttäuscht Ihr mich nicht.\n\nNun gut. Ich werde eine noch wichtigere Aufgabe für Euch haben, {name}, wenn die Zeit reif ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27160] = { id = 27160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsmaschinen", description = "Vertrocknete Geißel... schwach. Monstrositäten... stark.\n\nWir besiegen starke Monstrositäten... wir gewinnen Krieg.", sourceObjective = "Zerstört 6 aufgeschlitzte Ungetüme in Andorhal.", completion = "Monstrositäten ... stark.\n\n{name} ... stärker.", sourceObjectiveStatus = "unverified-source-field" }
quests[27161] = { id = 27161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der unendliche Fluss", description = "Araj der Beschwörer verstärkt die Verteidigung der Geißel mit einfachen Skeletten ... eine Armee von Schwächlingen, die Euch eher überrennen als überwältigen wird. Er hat Animi in den nördlichen Türmen Andorhals versammelt, die diese Skelette in einer erschreckenden Geschwindigkeit hervorrufen können. Ich habe aber eine Lösung!\n\n<Lang reicht Euch ein paar Granaten.>\n\nIhre Funktion ist einfach. Wenn diese Granaten auf einen Knochenanimus - oder in unserem Fall einen Haufen Skelette - geworfen werden, wird nicht mehr als Splitter von ihnen übrig bleiben.", sourceObjective = "Benutzt Langs Handgranaten und tötet 5 Berserker der Klapperknochen und zerstört einen Knochenanimus der Geißel.", completion = "Diese Granaten sind Sprengstoff, mehr nicht. Ich bin zwar kein Gobliningenieur ... aber ich weiß, dass es sehr nützlich sein kann, ab und an mal Sachen in die Luft zu sprengen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27162] = { id = 27162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scholomancer", description = "Scholomance ist eine der letzten verbleibenden Bastionen der Geißel im Westen des Thondroril. Der Direktor von Scholomance, ein Kultist namens Dunkelmeister Gandling, ist auf dem Schlachtfeld erschienen.\n\nDas wird der letzte Fehler sein, der ihm unterläuft.\n\nIhr werdet Gandling auf einem Platz in der Nähe des südlichen Stadtrands finden. Ich möchte, dass Ihr mit Gandling kämpft und ihn schwächt. Ich werde Euch beistehen, damit er sein Ende findet.", sourceObjective = "Tötet Dunkelmeister Gandling in Andorhal.", completion = "Ausgezeichnete Arbeit, {name}. Jetzt, da der Anführer der Streitmächte der Geißel nicht länger in Andorhal sein Unwesen treibt, müssen wir den richtigen Augenblick abwarten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27163] = { id = 27163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rohe Gewalt", description = "Gandling hat seinen Leutnant Blutrippe zur Unterstützung mitgebracht. Dieser rasselnde Schrecken ist viel gefährlicher als jede andere Geißel und Monstrosität, die Euch auf dem Schlachtfeld begegnen wird.\n\nBlutrippe befindet sich im alten Rathaus, in der Nähe der Stadtmitte. Ich empfehle Umsicht, bevor Ihr mit ihm kämpft, {name}. Er ist kein leichter Gegner.", sourceObjective = "Tötet Blutrippe in Andorhal.", completion = "Ausgezeichnete Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27164] = { id = 27164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Araj der Beschwörer", description = "Nun da der Animus besiegt ist, ist der nächste logische Schritt die Auslöschung Arajs und der Erhalt einer Scherbe seines Phylakteriums. Ihr habt ihn wahrscheinlich schon am Brunnen in der Stadtmitte herumlümmeln sehen.\n\nNehmt meine Granaten mit. Sie werden Araj keinen Schaden zufügen, aber Ihr könnt sie benutzen, wenn er auf die Idee kommt, Skelette zu beschwören, und diese damit in die Luft jagen. Ihr wisst ja, wie das geht.", sourceObjective = "Tötet Araj den Beschwörer. Ihr könnt Langs Handgranaten benutzen, um die Berserker der Klapperknochen zu zerstören.", progress = "Araj ist ein ausgezeichneter Gegner. Ihr solltet gut vorbereitet sein.", completion = "Araj ist tot... das ist gut. Dieser Gnom hat bei unserem Sieg eine Rolle gespielt. Und Ihr auch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27165] = { id = 27165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieg, im Moment", description = "Die Allianz hat gesiegt und unsere Streitmächte sind noch immer stark. Im Rahmen unserer Kriegsplanung müssen wir die Verlassenen jetzt angreifen, da sie sich noch vom Kampf erholen und nicht mit einem Angriff rechnen. Ich habe allerdings ein Abkommen geschlossen...\n\nWir werden warten. Wir greifen Koltira und seine Truppen an, wenn der richtige Zeitpunkt gekommen ist. Sprecht in der Zwischenzeit mit Ginny Siegesfroh und begebt Euch zum Zugwindlager südlich von hier. Kommandant Ashlam Ehrenschlag wird Euch über Eure nächste Aufgabe unterrichten.\n\nVon mir werdet Ihr wieder hören, sobald Ihr in Andorhal gebraucht werdet.", sourceObjective = "Meldet Euch bei Kommandant Ashlam Ehrenschlag in Zugwindlager in den Westlichen Pestländern.", completion = "Die Neuigkeiten erreichten uns kurz vor Euch, {name}. Dass die Geißel aus Andorhal vertrieben wurde, bedeutet, dass wir der Rückeroberung von Lordaeron einen Schritt näher gekommen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[27166] = { id = 27166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfeile machen!", description = "Wir müssen immer auf den Kampf vorbereitet sein, {name}. Ob dieser Kampf gegen die Verlassenen in Andorhal, gegen die Geißel im Osten, oder gegen einen noch unbekannten Feind ausgetragen wird, steht noch in der Zukunft geschrieben. Wir wissen nur, dass wir bereit sein müssen.\n\nUns gehen die Pfeile aus. Ich kann Schäfte und Pfeilspitzen besorgen, aber ich benötige Federn. Die Vögel, die nordwestlich von hier kreisen, sind zu dieser Jahreszeit normalerweise in der Mauser. Könntet Ihr Euch dorthin begeben und für unser Lager einige dieser Federn sammeln?", sourceObjective = "Erhaltet 9 Braunfederkiele.", progress = "Es ist gut, Euch wieder zu sehen, {name}.", completion = "Meine Pfeilmacher werden sich gleich an die Arbeit machen.\n\nEs ist gut zu sehen, dass Ihr Euch so nützlich macht, {name}. Vielleicht habe ich später noch aufregendere Aufgaben für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[27167] = { id = 27167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magenknurren", description = "Ich komme aus Westfall, weit im Süden. Auch diese Männer, die mit mir reisen, sind von dort. Wir sind nicht mehr als Bauersleute.\n\nMir wurde gesagt, dass Lordaeron geheilt wurde und der Boden bestellt werden kann. Dieser „Kommandant“ meint jetzt allerdings, dass es zu gefährlich ist, diese Arbeit vorzunehmen. Er meint, es tobe ein Krieg, und dass die Pestländer noch nicht geheilt sind.\n\nWie dem auch sei, was ich wirklich brauche, ist Essen in den Mägen meiner Männer. Es ist egal, was. Es scheint, als seien Bären hier reichlich vorhanden.", sourceObjective = "Beschafft Euch 5 Stücke Bärenfleisch von struppigen Schwarzbären in den Westlichen Pestländern.", progress = "Wir haben eine weite Reise hinter uns. Jeder Bissen, den Ihr übrig habt, ist eine Wohltat für uns.", completion = "Ihr jagt, wie nur ein echter {class} jagen kann. Selbst wenn wir unsere Behausungen noch nicht errichten können, so haben wir wenigstens etwas zu essen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27168] = { id = 27168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer nicht loslassen kann", description = "Trauerhügel nordöstlich von hier war einer der ersten Orte, den die Argentumkreuzfahrer und der Zirkel des Cenarius heilen konnten. Dieses Gebiet ist nun von der Geißel befreit.\n\nAllerdings finden sich dort immer noch Schreckgespenster der Vergangenheit, die aus irgendwelchen Gründen den Weltenübergang nicht vollbracht haben. Vielleicht trauern sie, oder sie haben noch eine Aufgabe zu erledigen... oder sie haben sich einfach nur verirrt.\n\nNehmt mein Weihrauchfass und läutert sie mit dem heiligen Weihrauch. Auf die eine oder andere Weise wird ihnen das beim Weltenübergang helfen.", sourceObjective = "Benutzt das Heilige Weihrauchfass bei 12 zurückgezogenen Geistern in Trauerhügel, und tötet sie, falls ihre Reaktion dies verlangt.", completion = "Ich hoffe, dass den meisten der Übergang in Frieden gelungen ist. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27169] = { id = 27169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uthers Segen", description = "Diese Bauern aus dem Süden wollen sich der Bauernhöfe annehmen, aber ich kann nicht zulassen, dass sie die Pestländer unvorbereitet betreten. Auch jetzt, wo die Geißel nicht mehr hier ist, lauert immer noch Gefahr - durch die Verlassenen. Nein, wir müssen bereit sein, zu kämpfen, und das schließt unsere Besucher ein.\n\nBevor wir irgendetwas anderes tun, würde ich allerdings vorschlagen, dass Ihr nach Osten zu Uthers Grabmal reist und diesen Tribut vor seiner Statue niederlegt, um seinen Segen zu erbitten. Sprecht danach mit dem Priester, der sich um das Grabmal kümmert.", sourceObjective = "Begebt Euch zu Uthers Grabmal und verwendet den Eiswindtribut vor seiner Statue.", progress = "Uther war ein wahrer Held. Es ist mir eine Ehre, ihm zu dienen, nach allem, was er erlitten hat.", completion = "Ihr und die Menschen von Zugwindlager möchtet Andorhal zurückerlangen? Ich wünsche Euch viel Glück.", sourceObjectiveStatus = "unverified-source-field" }
quests[27170] = { id = 27170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlassene Gruft", description = "Wenn Ihr die Schlacht um Andorhal wirklich vorantreiben möchtet, kann ich Euch vielleicht helfen.\n\nÖstlich von hier befindet sich eine große Gruft. Der untere Teil der Gruft wurde einst für die Aufbewahrung von Waffen und Rüstung benutzt - bis die Geißel kam. Jetzt, da die Untoten nicht mehr hier sind, können diese Waffen benutzt werden.\n\nDie meisten Waffen sind wohl rostig und alt, aber trotzdem besser für unsere Zwecke geeignet als Tuniken und Heugabeln.", sourceObjective = "Findet die Waffenkiste unten in der Gruft in den Westlichen Pestländern.", completion = "Auf der untersten Ebene der Gruft findet Ihr zerstörte Kisten am Boden verstreut, in denen sich einst Waffen und Rüstung befanden.\n\nJemand scheint Euch zuvorgekommen zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[27171] = { id = 27171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinterhalt!", description = "Als Ihr Euch umdreht, seht Ihr die Silhoutten der torkelnden Skelette auf den Stufen.\n\nDie Untoten haben die Gruft nicht verlassen. Sie haben hier gewartet! Außerdem scheinen sie die Waffen zu tragen, wegen denen Ihr hier seid.\n\nIhr müsst aus der Gruft fliehen. Versucht, auf dem Weg nach draußen so viel Ausrüstung wie möglich zu ergattern.", sourceObjective = "Erhaltet 4 abgenutzte Brustplatten und 4 verrostete Schwerter.", progress = "Was ist an Uthers Grabmal passiert, {name}?", completion = "Von Geistern angegriffen? Das ist seltsam. Die Gruft wurde wohl doch nicht vollständig geheilt.\n\nIhr habt gerade Thurman Grant verpasst - Ihr wisst schon, der Bauerntrampel, der vorhin schon mal hier war. Er hat seine Männer zusammengerufen und hat sich mit ihnen zum nächsten Bauernhof aufgemacht ... gegen meinen Befehl.", sourceObjectiveStatus = "unverified-source-field" }
quests[27172] = { id = 27172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Trostlose Feld", description = "Die Bauern haben sich aufgemacht zum Trostlosen Feld, einem alten Bauernhof nordöstlich von hier, auf der anderen Seite des Flusses. Jemand muss sie im Auge behalten.\n\nBringt ihnen diese rostigen Waffen und die Rüstungen, die Ihr gefunden habt. Wir können nicht zulassen, dass sie mit Heugabeln kämpfen.", sourceObjective = "Bringt die ramponierten Waffen und Rüstungen zu Thurman Grant zum Trostlosen Feld in den Westlichen Pestländern.", progress = "Hat Ehrenschlag Euch geschickt? Dieser Kommandant weiß nicht, wann es genug ist, oder?", completion = "Nun, da Ihr hier seid, werden wir Euch die Rüstungen dankbar abnehmen.\n\nAber die Waffen könnt Ihr behalten. Diese Männer würden nicht wissen, an welchem Ende sie sie halten müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27173] = { id = 27173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dies ist unsere Armee", description = "Ich habe Kommandant Ehrenschlag darüber unterrichtet, dass wir uns selbst verteidigen können, und das haben wir auch vor. Ich hatte auf meinem Weg hierher ein kurzes Gespräch mit Thassarian, diesem Kriegsherrn der Todesritter. Wir Bauern haben vor, auf unsere eigene Art und Weise zu helfen.\n\nWir werden diesen Bauernhof einnehmen, das Land kultivieren ... und wenn die Schlacht um Andorhal beginnt, werden wir die Verlassenen vom Hinterland aus angreifen. Damit werden sie nicht rechnen.\n\nZuerst müssen wir uns der Vorhut der Verlassenen widmen. Tötet einige von ihnen, und kommt dann wieder zu mir.", sourceObjective = "Tötet 10 Streitkräfte der Vorhut der Verlassenen.", completion = "Ihr seid gut im Kampf, {race}. Meine Männer könnten ein paar Kniffe von einem {class} wie Euch lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27174] = { id = 27174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampftraining", description = "Vielleicht könnt Ihr tatsächlich ein paar meiner Männer ausbilden. Ihr habt wahrscheinlich die Monstrosität da draußen bemerkt. Wir haben zuerst versucht, sie zu bekämpfen, aber sie hat sich nicht gewehrt. Es scheint, als ob sie auf dem Bauernhof helfen möchte.\n\nNehmt vier meiner Männer und fordert die Monstrosität zum Kampf heraus. Sie scheint stark zu sein, aber eine Monstrosität gegen fünf von Euch sollte Euch doch Chancen auf einen Sieg geben.", sourceObjective = "Sprecht mit Gory im Trostlosen Feld und fordert ihn zum Kampf heraus.", completion = "Nun können wir die Sache selbst in die Hand nehmen. Ich danke Euch für Eure Hilfe, {name}.\n\nDas nächste Mal, wenn wir uns sehen, werden wir uns wohl im Kampf befinden. Passt solange auf Euch auf. Wir können alle Hilfe gebrauchen, die wir bekommen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[27175] = { id = 27175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stätte der Heiler", description = "Die Männer und Frauen in Zugwindlager haben ehrenhafte Ziele, doch letztendlich ist der Krieg ihre Absicht. Ich möchte Euch die Möglichkeit geben, friedlichere Ziele zu verfolgen.\n\nNördlich vom kriegsgebeutelten Andorhal befindet sich die Stätte der Heiler. Der Argentumkreuzzug hat sich dort mit dem Zirkel des Cenarius verbündet. Zusammen arbeiten wir daran, das Land von der Seuche zu heilen, die hier so lange herrschte.\n\nSeid Ihr daran interessiert, Euch unserer Sache zu widmen, {class}?", sourceObjective = "Meldet Euch bei Außenagent Kaartish in der Stätte der Heiler in den Westlichen Pestländern.", completion = "Willkommen, {class}. Wie Ihr sehen könnt, besteht unser Lager aus einer Gemeinschaftsexpedition des Argentumkreuzzugs und Druiden des Zirkels des Cenarius. Wir heißen jedoch alle willkommen, die bei der Heilung des Landes helfen wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27176] = { id = 27176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine seltsame Scheibe", description = "Die Gravuren an der Oberfläche dieser Scheibe deuten daraufhin, dass sie uralten Ursprungs ist, und doch zeigt sie keinerlei Anzeichen von Abnutzung.\n\nDas Loch am Rand ist voll mit Holzsplittern, was darauf hindeutet, dass sie dafür vorgesehen war, an einer Art Holzstab angebracht zu werden.\n\nBevor ihr sie Dr. Jones zeigt, solltet Ihr das andere Teil finden.", sourceObjective = "Erhaltet den Stab des Sultans und benutzt die aufwendige Scheibe, um den Schaft der Sterne zu erstellen.", progress = "Ja, {name}?", completion = "<Doktor Jones setzt seine Brille auf.>\n\nLasst uns das genauer betrachten, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[27177] = { id = 27177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergungsaktion", description = "Unsere Flotte wurde durch die Horde und die Naga stark geschwächt. Wir können die Männer, die ihr Leben dem Meer gelassen haben, nicht zurück zum Leben erwecken, aber nur über meine ertrunkene Leiche werde ich zulassen, dass alle unsere Ladungen auf immer verloren gehen.\n\nSchwimmt zum Obsidianbrecher südwestlich von Hochufer und bergt die Ladungen der gesunkenen Schiffe vom Meeresboden.", sourceObjective = "Bergt 8 wiedergefundene Vorräte aus den durchnässten Kisten in Obsidianbrecher.", progress = "Wie viele der Vorräte konntet Ihr bergen?", completion = "Da seht her! Ihr konntet mehr bergen, als ich zu hoffen gewagt hatte. Damit können wir einen ganzen Trupp Marinesoldaten versorgen.\n\nWir haben die Ausrüstung. Wenn wir nun nur irgendwie unseren Kämpfern hier in Hochland Mut machen könnten ...", sourceObjectiveStatus = "unverified-source-field" }
quests[27178] = { id = 27178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung der Naga", description = "Sie kommen aus der Tiefe des Ozeans angeglitscht, {name}. Die Naga. Ich denke, sie haben vor, die Bastion des Zwielichts zu verstärken, und werden wahrscheinlich den Verrall nutzen, um weiter ins Land vorzudringen. Wir dürfen das nicht geschehen lassen!\n\nZeigt ihnen, dass die Ufer nun die unseren sind, und sorgt dafür, dass sie schnell wieder zurück in die dunklen Tiefen huschen.\n\nTötet die Schwarzschuppen-Naga, die sich ihren Weg durch Obsidianbrecher bahnen!", sourceObjective = "Tötet 10 Myrmidone der Schwarzschuppen oder Seerufer der Schwarzschuppen.", completion = "Das wird ihnen eine Lehre gewesen sein, {name}! Cho'gall wird sich in diesem Kampf nicht auf die Naga verlassen können. Von jetzt an sind wir gegen den Schattenhammer auf uns gestellt.\n\n\n\n... Und gegen die Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27179] = { id = 27179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldarbeit", description = "Dieser bedauernswerte Pygmäe war zur falschen Zeit am falschen Ort.\n\nAls Ihr über sein Unglück sinniert, bemerkt Ihr die Symbole auf seinem Schild. Sie sind viel zu aufwendig für Pygmäengekritzel.\n\nIhr seid davon überzeugt, dass Doktor Jones ein Objekt wie dieses hochinteressant finden wird, und macht Euch auf, um weitere Fragmente wie dieses zu finden.", sourceObjective = "Sammelt 10 uralte Tafelfragmente.", progress = "Was haben wir denn hier, mein Freund?", completion = "Diese Tafeln sind übersäht mit titanischen Schriftzeichen. Hier steht noch Unbekanntes geschrieben, {name}!\n\nFehlende Teile eines uralten Rätsels...\n\nGute Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[27180] = { id = 27180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehret die Toten", description = "Ein Konvoi erfahrener Truppen und Katapulte der Verlassenen wurden heute aus dem Hinterhalt angegriffen, als sie Olsens Acker südlich von hier überqueren wollten. Ein Totalschaden: alle Einheiten wurden getötet und alle Katapulte vernichtet.\n\nDas Rudel von Blutfang ist für den Hinterhalt verantwortlich, allerdings sind sie wohl längst wieder in die Hügel geflüchtet, um sich auf ihren nächsten feigen Angriff vorzubereiten. Ihre Zeit wird kommen. Jetzt allerdings möchte ich, dass Ihr zu Olsens Acker geht und die Gefallenen ehrt.\n\nFindet die Insignien der Verlassenen.", sourceObjective = "Findet 6 Insignien der Verlassenen bei den Leichnamen der Veteranengardisten der Verlassenen.", progress = "Konntet Ihr die Insignien finden?", completion = "Ich werde mich darum kümmern, dass die Insignien auf der Stelle zurück nach Unterstadt gelangen. Der Registrator wird ihre Namen in unsere Verzeichnisse aufnehmen, so dass ihr Opfer nie in Vergessenheit gerät.", sourceObjectiveStatus = "unverified-source-field" }
quests[27181] = { id = 27181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schmach ein Ende bereiten", description = "Es scheint, als sei ein Teil der Wegelagerer hier geblieben. Lasst sie für diese Anmaßung teuer bezahlen! Tötet die Blutfangpirscher auf Olsens Acker. Für Sylvanas! Für die Horde!", sourceObjective = "Tötet 10 Blutfangpirscher.", sourceObjectiveStatus = "unverified-source-field" }
quests[27182] = { id = 27182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Einsiedler des Hexenhügels", description = "Die Marschen scheinen seltsame Auswirkungen auf die Menschen zu haben. So mancher wurde schon wahnsinnig, nur weil er dort lebte.\n\nJeder, der sich im Irrlichtanwesen niedergelassen hat, wurde auf ganz besondere Weise verrückt. Bei dem jetzigen Besitzer, man nennt ihn \"Sumpfauge\" Jarl, machen sich bereits einige Anzeichen bemerkbar.\n\nIch weiß zwar nicht genau, was dort vor sich geht, aber ich wäre Euch sehr dankbar, wenn Ihr dort nach dem Rechten sehen würdet.\n\nDas Anwesen liegt am östlichen Ende des Sumpfs. Lauft Richtung Osten durch das Blaumoor und vorbei an der Nordwacht. Die Gegend, in der das Anwesen liegt, ist ein verwunschener Flecken und heißt Hexenhügel.", sourceObjective = "Sprecht mit \"Sumpfauge\" Jarl beim Irrlichtanwesen.", completion = "Seid Ihr hierhergekommen, um mich auszuspionieren? Nein?\n\nDann seid Ihr vielleicht ein Liebhaber der guten Küche? Gut, ich kann Eure Hilfe gebrauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27183] = { id = 27183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marschenfroschschenkel", description = "Ich koche gerne. Gute Sumpfmannskost. Frittierte Grünfroschschenkel und so.\n\nAber ich habe keine Froschschenkel mehr. Im Irrlichtanwesen wimmelt es aber von Fröschen. Riesige Marschenfrösche. Meint Ihr, Ihr könnt ein paar ihrer Schenkel besorgen? Das ist wirklich nicht viel Arbeit. Ihr müsst ihnen nur auf die Köpfe hauen und mir die Schenkel bringen.\n\nDann mach ich Eintopf, und ess den Eintopf, und Ihr könnt auch Eintopf haben.\n\nMögt Ihr Eintopf?", sourceObjective = "Sammelt 10 Marschenfroschschenkel von riesigen Marschenfröschen.", progress = "Gewürze. Gewürze können niemandem schaden. Oder etwa nicht?", completion = "Ah, hier ist das Gewürz! Das nenne ich einen guten Sumpfeintopf.", sourceObjectiveStatus = "unverified-source-field" }
quests[27184] = { id = 27184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jarl braucht Augen", description = "Augensaft ist ein leckeres Getränk. Leider haben die meisten Tierwesen nur zwei Augen.\n\nAber Spinnen haben eine Menge Augen. Jede Menge. Und Graunebelaugensaft ist lecker. Samtig und salzig! Unzerplatzte Spinnenaugen... Ich schmecke sie schon förmlich.\n\nGraunebelspinnen leben westlich von hier in den Graunebelhöhlen. Glaubt Ihr, die Spinnen wurden nach der Höhle benannt... oder ist es umgekehrt?", sourceObjective = "Sammelt 20 unzerplatzte Graunebelaugen von Graunebelspinnen.", progress = "Wo sind diese Augen?", completion = "Ihr habt die Augen! Ihr habt die Augen! Leckere, leckere Spinnenaugen!\n\nManche Augen... wenn man sie anstarrt, starren sie zurück. Die ess ich zuletzt. Sie leisten einem Gesellschaft... draußen im Sumpf.\n\nHallo, kleine Spinnenaugen. Hallo! Ihr seid so lecker wie Hühnchen. Glibberiges, salziges Hühnchen!\n\nMmmh.", sourceObjectiveStatus = "unverified-source-field" }
quests[27185] = { id = 27185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wettstreiter ausmerzen", description = "Ich werd' keine Spielchen mit Euch spielen. Der purpurrote Hammerschmied des scharlachroten Kreuzzugs war bisher nicht wirklich erwähnenswert, aber nun, da er zu einem von Balnazzars Auferstandenen geworden ist, hat der Schreckenslord ihm beigebracht, alle möglichen mächtigen und dämonischen Waffen herzustellen.\n\nDie Aufgabe ist einfach. Findet die Schmiedepläne und tötet den purpurroten Hammerschmied, wenn er kommt, um sie zu holen. So können wir sicherstellen, dass ihre Armee die dämonischen Waffen nicht in die Hände bekommt. Sie sind jetzt schon viel zu stark!", sourceObjective = "Tötet den purpurroten Hammerschmied.", completion = "Gut gemacht, mein Freund! Ohne die neuen Waffen sind sie genau so einfach zu töten wie damals, als sie noch lebendig waren!", sourceObjectiveStatus = "unverified-source-field" }
quests[27186] = { id = 27186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jarl braucht eine Klinge", description = "Ich habe zu schneiden. Ich kann Euch nicht sagen, was ich schneiden werde, aber... Ich brauche eine Klinge. Eine ganz bestimmte Klinge...\n\nManche Leute sprechen von einem Schwert. Ich nenne es eine Schwingklinge.\n\nHelft Ihr mir? Diese Fischmenschen, Murlocs, oder wie auch immer die heißen... Einer von ihnen wird Messerwirbel genannt, hat ständig so ein großes Schwert bei sich, lebt nördlich von hier am Strand. Ich brauche sein Schwert!\n\nAber schlaft nicht noch darüber. Was ich schneide, das hält nicht ewig...", sourceObjective = "Besorgt Messerwirbels Schwert", progress = "Habt Ihr meine Klinge???", completion = "Das ist eine gute Klinge. Sie schwingt gut. Es ist eine gute Schwingklinge. Danke. Danke, danke, danke!!! Jetzt möchte ich sie ausprobieren... \n\nSpäter. Ich probiere sie später aus. Aber wie ich schon sagte... danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[27187] = { id = 27187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gefallen für die Welt", description = "Hyänen sind im besten Fall ein Ärgernis.\n\nDiese finsteren Wesen sind bösartig veranlagt, haben alle möglichen Krankheiten und sind nicht mehr als eine Seuche auf dem Antlitz der Hundewelt.\n\nTut der Welt einen Gefallen und befreit die Wüsten von Uldum von dieser räudigen Bedrohung.", sourceObjective = "Tötet 12 räudige Hyänen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27188] = { id = 27188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was sucht den Hexenhügel heim?", description = "Ich bin hierher gereist, um Jarl in seinem neuen Zuhause zu besuchen, aber seit meiner Ankunft nahm der Schrecken hier kein Ende! Hier stimmt etwas nicht... überhaupt nicht. Ich kann nicht der Einzige sein, der diese Dinge sieht.\n\nHabt Ihr die Geister und Leichname gesehen, die um den Hexenhügel umherstreifen? Wenn einer weiß, was hier vor sich geht, so befürchte ich, dass sie es sind. Haltet nach den auferstandenen Gebeinen und auferstandenen Geistern in der Umgebung Ausschau. Bekämpft sie und gewährt ihnen dadurch ihren verdienten Frieden. Verschafft Euch so viele Informationen wie möglich von ihnen, bevor Jarl dem Bösen vollends verfällt!", sourceObjective = "Sammelt Informationen, indem Ihr 10 auferstandene Gebeine oder auferstandene Geister besiegt.", completion = "<Mordant holt ein kleines Blatt Papier und einen Stift hervor und beginnt, sich Notizen über Eure Berichterstattung zu machen.>\n\nIhr konntet herausfinden, dass sich die Geister an diesem Ort auf die Anzahl aller belaufen, die jemals auf diesem Land gelebt haben, und nicht nur auf die vorherigen Besitzer.\n\nEtwas hat sie zu Grunde gerichtet und getötet. Wer der Sache verfällt, erfährt die Wahrheit nicht, bis es zu spät ist. Wir müssen dem Ganzen ein Ende bereiten, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[27189] = { id = 27189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hexenfluch", description = "In meiner Zeit als Kräuterkundiger habe ich oft feststellen können, dass die Natur stets raffinierte Heilmethoden für die ärgerlichsten Probleme bereithält. Ich habe gelesen, dass die unabhängigen Magier und Hexendoktoren häufig den Rauch einer Pflanze, die als Hexenfluch bekannt ist, verwenden, um das Böse aus seinem Versteck zu locken.\n\nFalls dem wirklich so ist, dann müsste Hexenfluch nahe der seichten Gewässer des Hexenhügels wachsen. Ihr solltet die Pflanze an ihren breiten Blättern und rötlichen Stängeln in der Mitte erkennen. Bringt mir so viele Pflanzen, wie Ihr finden könnt, {name}. Es könnte unsere letzte Hoffnung sein.", sourceObjective = "Sammelt 9 Zweige Hexenfluch am Hexenhügel.", progress = "Konntet Ihr ein paar Pflanzen finden? Wir müssen schnell handeln, bevor das Übel, das hinter dieser Heimsuchung steckt, in dieser Gegend vollends überhand nimmt.", completion = "<Mordant nimmt das Pflanzenbündel von Euch entgegen.>\n\nDiese entsprechen exakt der Beschreibung! Während Eurer Abwesenheit habe ich die Fackel vorbereitet. Jetzt müssen wir die Pflanzen nur noch hier am Ende befestigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27190] = { id = 27190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung des Hexenhügels", description = "Die Fackel ist fertig. Platziert sie am Ende des Anlegestegs und macht Euch darauf gefasst, allem gegenüberzutreten, was erscheinen mag.\n\nIch habe keine Ahnung, was der Rauch der Fackel enthüllen wird... wenn überhaupt etwas passiert. Ich muss zugeben, dass ich dieser Art der Volksmagie nicht viel Vertrauen schenke, aber wir haben keine Zeit für irgendwas anderes. Jarl zuliebe, und auch Euch zuliebe, wünsche ich Euch viel Glück.", sourceObjective = "Platziert die Hexenfluchfackel am Ende des Anlegstegs und besiegt das Böse, das Hexenhügel heimsucht.", progress = "Ist es vorbei?", completion = "Es hat funktioniert?\n\n<Mordant räuspert sich.>\n\nIch meine ... es hat funktioniert! Jarl und ich stehen in Eurer Schuld, {name}. Das nächste Problem ist nun der Möbelgeschmack meines Freundes, und das wird wohl nicht so einfach zu lösen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[27191] = { id = 27191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungrig wie ein Oger!", description = "Hier trifft man schon ab und an jemanden. Nette Leute. Hab mal einen Oger getroffen. Oger werden hungrig, genau wie ich.\n\nIch werde nie vergessen, was er gesagt hat. Er sagte: „Patsch großer Oger. Ich hungrig. Geht Fische hauen. Bringt Patsch Essen. Ihr füttert Patsch oder Patsch frisst Euch.“\n\nIch hab ihm also Fische besorgt, und er hat die Fische gegessen. Und seitdem esse ich auch Fisch. Die Köpfe schmecken am besten, die sind so schön glitschig.\n\nZermalmt die Köpfe nicht. Das macht die Fische unglücklich. Traurige Köpfe schmecken nicht gut. Bringt mir glückliche Fischköpfe, und ich werde die Fischköpfe essen und auch glücklich sein.", sourceObjective = "Sammelt 8 Schlammflossenköpfe von den Murlocs der Schlammflossen.", progress = "Jarl hat Hunger. Genau wie der Oger.", completion = "Ich frag mich, wie es ist, ein Oger zu sein. Große Leute müssen mehr essen.\n\nOger müssen noch hungriger sein als ich. Das klingt wirklich nicht witzig.", sourceObjectiveStatus = "unverified-source-field" }
quests[27192] = { id = 27192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Fras Siabi", description = "Männer von weit entfernten Orten wie Kul Tiras sprechen von Fras Siabis Tollem Tabak. Dieses Genussmittel wurde von jeder wichtigen Person, die Stratholme je besuchte, konsumiert. König Terenas, Uther Lichtbringer, Hochlord Fordring ... ja, alle genossen sie Siabis Spezialität.\n\nLeider verblieb Fras in seinem Laden, als Stratholme überfallen wurde, und er schwörte auf sein Leben, dass die Geißel seinen Tabak nicht anfassen würde. Wagt Euch hinein und seht nach, ob etwas von dem Tabak übrig geblieben ist. Er ist sein Gewicht in Gold wert, das kann ich Euch versichern.", sourceObjective = "Bergt einen Kasten von Fras Siabis Tollem Tabak.", progress = "Habt Ihr welchen gefunden?", completion = "Ihr habt wahrhaftig den Schnupftabak, aus dem die Träume sind, entdeckt. Es ist fast unmöglich, den Preis für diesen historischen Tabak festzulegen.\n\nHier, nehmt diese Münzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27193] = { id = 27193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suchen und Zerstören", description = "<Die Stimme der Bansheekönigin dringt erneut in Eure Gedanken ein.>\n\nSucht in den nahegelegenen Bauernhäusern nach Nachzüglern der Allianz. Haltet Eure Augen offen nach Informationen, die uns zu Crowley und Blutfang führen könnten. Sucht und zerstört alle, die sich Euch in den Weg stellen, {name}!", sourceObjective = "Durchsucht die Bauernhäuser auf Olsens Acker.", sourceObjectiveStatus = "unverified-source-field" }
quests[27194] = { id = 27194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Ecke gedrängt und zermalmt!", description = "<Die Stimme der Bansheekönigin spricht zu Euch.>\n\nWir müssen schnell handeln, {name}. Sie dürfen nicht die Gelegenheit bekommen, zu fliehen. Ich werde ein Geschwader meiner mächtigsten Soldaten zur Tiefenfelsmine schicken. Der Reiter wird sie begleiten, um sicherzustellen, dass alles nach Plan verläuft. Trefft ihn in der Tiefenfelsmine, östlich von Olsens Acker und ZERMALMT diese Ratten.", sourceObjective = "Meldet Euch bei Meister Forteski in der Tiefenfelsmine im Silberwald.", completion = "Ich denke mal, erst in die Enge treiben, dann zermalmen, hm?", sourceObjectiveStatus = "unverified-source-field" }
quests[27195] = { id = 27195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es gibt keinen Ausweg", description = "Die Herrin hat mich beauftragt, die Bande bei dieser Aufgabe zu führen. Unser Hauptziel ist es, in die Mine einzudringen, die Ratten in die Enge zu treiben und sie alle zu töten, auch Blutfang.\n\nIhr habt uns mit der Beschaffung dieser Informationen gute Dienste geleistet, {name}. Habt am Ruhm teil und helft uns dabei, unsere Schwerter durch ihre elenden Schädel zu jagen.\n\nLasst mich wissen, wenn Ihr bereit seid, und ich werde zum Angriff rufen.", sourceObjective = "Begleitet Meister Forteski durch die Tiefenfelsmine.", completion = "WAS!?\n\n<Fürstin Sylvanas kreischt.>\n\nCROWLEY!!!!!\n\nIhr Bastarde. Das waren einige meiner stärksten Soldaten. Ich habe Crowley und Blutfang zum letzten Mal unterschätzt. Ganz eindeutig handelt es sich hier um Feinde, wie wir sie noch nie zuvor gesehen haben - willens, die eigenen Kämpfer in einer Falle wie dieser zu opfern. Das gab es in der Kriegsführung der Allianz noch nie.", sourceObjectiveStatus = "unverified-source-field" }
quests[27196] = { id = 27196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irgendetwas geht vor sich", description = "Ihr habt bemerkenswerte Arbeit geleistet! Vor allem für jemanden, der nie einen meiner Kurse besucht hat.\n\nDiese Tafeln geben uns neue Informationen zu verschiedenen Themen.\n\nSie weisen darauf hin, dass diese Obelisken Teil eines riesigen, uralten Mechanismus sind, der diese Gegend einst vor dem Rest der Welt versteckt hielt.\n\nAußerdem zeigen sie auch auf, wie der Mechanismus wieder in Gang gebracht werden kann. Hier kommt der Schaft der Sterne ins Spiel...\n\nMacht Euch bereit, {name}. Es gilt, Geschichte zu schreiben!", sourceObjective = "Begleitet Harrison Jones zur Kammer der Sterne.", progress = "Also, mal sehen, was dieser Stab uns zeigen kann...", completion = "Das ist aber echt mal ein Ort hier!", sourceObjectiveStatus = "unverified-source-field" }
quests[27197] = { id = 27197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht geht weiter!", description = "Es gibt Nachrichten aus Andorhal, {name}. Die Schlacht hat wieder angefangen.\n\nUnter den Streitkräften der Allianz ist es wohl bekannt geworden, dass Ihr Euch als einer der Helden der ersten Schlacht um Andorhal hervorgetan habt. Thassarian verlangt umgehend nach Eurer Anwesenheit.", sourceObjective = "Meldet Euch bei Thassarian in Andorhal in den Westlichen Pestländern.", completion = "Es heißt, Ihr hättet den Bauern geholfen, sich zu bewaffnen. Und nun haben Sie ohne meinen Befehl angegriffen! Sie zwingen mich zu handeln.\n\nDie Schlacht geht weiter. Dieses Mal kämpfen wir gegen die Verlassenen... und ich kämpfe gegen Koltira, meinen alten Bruder von der Schwarzen Klinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[27198] = { id = 27198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Truppen unterstützen", description = "Ich bin kein Militärexperte, aber diese Schlacht scheint zu unseren Gunsten zu stehen. Unsere Verteidiger sind nicht besser als die Todeswachen unserer Gegner, aber die Bauernmiliz hat sie mit dem Angriff aus dem Hinterland überrascht. Für die Allianz!\n\nWir müssen trotzdem alles tun, was in unserer Macht steht, um einen Sieg zu sichern. Reist nach Andorhal östlich von hier und tötet die Todeswachen der Verlassenen, die mit unseren Männern kämpfen. Je schneller sie sterben, umso eher können wir Andorhal wieder unser Eigen nennen!", sourceObjective = "Tötet 15 Todeswachen von Andorhal.", completion = "Ihr habt gut gekämpft, {name}. Ich wünschte, ich hätte Eure Fähigkeiten ... und Euren Mut.", sourceObjectiveStatus = "unverified-source-field" }
quests[27199] = { id = 27199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asche zu Asche", description = "Östlich von hier, tief im von den Verlassenen gehaltenen Andorhal, werdet Ihr ihre Kommandanten anfinden. Sie kämpfen nicht, sondern befehligen nur von den Rücken ihrer Pferde.\n\nJagt und tötet diese Kommandanten, {name}. Die Verlassenen werden machtlos sein.", sourceObjective = "Tötet 3 Kriegshauptmänner der Todeswache.", completion = "Gut gemacht. Jetzt, da die Kriegshauptmänner ausgeschaltet wurden, habe ich keine Ausreden mehr.\n\nBald muss ich mich Koltira im Kampf stellen, für Ehre und für Andorhal.", sourceObjectiveStatus = "unverified-source-field" }
quests[27200] = { id = 27200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sirenenlied", description = "Sie ist immer noch anzutreffen... Ophelia, die Sirene des Hochlands! Ihr schreckliches Lied wird Euch in die Tiefen locken. Ich habe geschworen, hier zu bleiben und meine gefallenen Besatzungsmitglieder zu rächen, {class}. Wenn Ihr mich unterstützen wollt, müsst Ihr nur den Mund aufmachen.\n\nWir werden uns an den Mast binden, oh ja. Wir werden unsere Augen schließen. Wir werden unsere Ohren mit Wachs ausstopfen. Und wenn ihre schöne Illusion vergeht... werden wir angreifen.\n\nKann ich auf Euch zählen?", sourceObjective = "Tötet Ophelia, die Sirene des Hochlands.", completion = "Sie hatte mich in ihrem Zauber, {name}. Ich wäre nicht mit dem Leben davongekommen, wenn Ihr nicht gewesen wärt. Ich danke Euch!\n\nVielleicht kann die restliche Flotte der Allianz hier nun in Frieden vor Anker gehen ...", sourceObjectiveStatus = "unverified-source-field" }
quests[27201] = { id = 27201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff der Val'kyr", description = "Die Val'kyr waren einst die mächtigste Waffe der Geißel. Sie waren nicht nur fähig im Kampf, sondern konnten auch benutzt werden, um Leichen in Diener der Geißel zu verwandeln. Es fällt mir schwer zu glauben, dass Sylvanas sich um der Verlassenen willen zu solchen Methoden herablässt ... \n\nWir müssen die Val'kyr aufhalten, bevor sie uns ausschalten und unsere Armee gegen uns wenden. Tötet so viele, wie Ihr finden könnt. Nehmt ein paar dieser Freiwilligen mit Euch. Wenn sie bis jetzt überlebt haben, haben sie wohl doch etwas Kampfgeschick.", sourceObjective = "Tötet 9 niedrige Val'kyr in Andorhal.", completion = "Mit jeder Val'kyr, die Ihr tötet, rettet Ihr Dutzende unserer Männer ... und hindert die Streitmächte der Verlassenen daran, weiter zu wachen.\n\nUnd doch machen sie weiter und weiter. Es kann sein, dass wir diese Schlacht doch nicht gewinnen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27202] = { id = 27202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bruder gegen Bruder", description = "Unsere Miliz wurde fast vollständig ausgemerzt. Nur ich und diese paar Bauern sind noch übrig.\n\nDiese beflügelten Kreaturen ... sie haben die Leichen unserer Männer genommen ... und sie in laufende, untote Leichname verwandelt! Mit jedem einzelnen, den sie von uns genommen haben, haben sie ihre eigenen Ränge verstärkt.\n\nEs fällt mir schwer es zuzugeben, aber Ihr werdet auch sie bekämpfen müssen, zusammen mit den Todeswachen und den Val'kyr. Wie sie es auch in ihrem früheren Leben gemacht haben, jagen sie in Gruppen. Nehmt ein paar der Freiwilligen mit Euch.", sourceObjective = "Tötet 20 Reitersoldaten der Verlassenen in Andorhal.", completion = "Ihr habt beherzt gekämpft, aber es bringt uns nichts. Jeder Kämpfer, der fällt, treibt ihre Streitmächte weiter voran.", sourceObjectiveStatus = "unverified-source-field" }
quests[27203] = { id = 27203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Mahlstrom", description = "Dank den Geistern, dass Ihr hier seid, {name}.\n\nWir wissen nicht, wie lange wir den Riss im Mahlstrom noch erhalten können.\n\nUnsere mächtigsten Mitstreiter, die von Thrall angeführt werden, können den Einriss kaum aufhalten.\n\nDer letzte Stand ist, dass unsere einzige Hoffnung darin liegt, durch die Öffnung zu steigen und zu versuchen, sie von der anderen Seite aus zu stabilisieren.\n\nIch werde ein Portal herbeizaubern. Benutzt es und meldet Euch bei Thrall, sobald Ihr könnt.", sourceObjective = "Geht durch das Portal in den Mahlstrom und sprecht mit Thrall.", completion = "<Thralls Muskeln spannen sich an, als urtümliche Energie ihn durchfließt. Sein Blick gleitet zu Euch, er bemerkt Eure Anwesenheit.>\n\nEs freut mich, Euch zu sehen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27204] = { id = 27204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aradne", description = "Unsere letzte Hoffnung auf einen Sieg ist die Bezwingung der Val'kyr. Bisher habt Ihr gute Arbeit geleistet... Ihr seid aber auch nur <ein Mann/eine Frau> gegen wortwörtlich Dutzende, die Zerstörung auf das Schlachtfeld bringen.\n\nEine riesige Val'kyr sitzt auf einem Turm südlich von hier... Ihr könnt sie von hier sehen. Wenn wir sie beseitigen, werden die restlichen Val'kyr sich vielleicht zerstreuen.\n\nEs ist unsere einzige Hoffnung. Nehmt ein paar von Grants Männern mit. Ihr werdet für diesen Kampf Schutz benötigen.", sourceObjective = "Tötet Aradne auf dem Turm im westlichen Teil von Andorhal.", completion = "Ich habe Euren Sieg von hier unten verfolgt. Ihr habt gut gekämpft, doch letztendlich war alles umsonst.\n\nDie Val'kyr und die Verlassenen kämpfen weiter und werden uns bald übermannen. Wir haben Andorhal verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[27205] = { id = 27205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verderbtheit der Verlassenen", description = "Wir haben diese Schlacht fast gewonnen, {name}. Ich kann den Sieg förmlich schmecken. Die Verlassenen hatten nie ein...\n\nWas zum Teufel ist das!?", sourceObjective = "Findet heraus, was Thassarian anschaut.", completion = "Val'kyr? Koltira hat Val'kyr zu diesem Kampf mitgebracht? Ist er verrückt geworden?\n\nNein, das ist nicht Koltiras Werk. Das war Sylvanas.", sourceObjectiveStatus = "unverified-source-field" }
quests[27206] = { id = 27206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weh dir, Andorhal", description = "Begebt Euch nach Süden, nach Zugwindlager. Berichtet Kommandant Ashlam Ehrenschlag von allem, was hier vorgefallen ist.\n\nIch? Ich gehe nach Westen, nach Tirisfal.\n\nMeine Schlacht ist noch nicht abgeschlossen. Ich habe ein Treffen mit einer Harpyie, die sich die Bansheekönigin nennt ... und ich werde herausfinden, was sie Koltira angetan hat.", sourceObjective = "Berichtet Kommandant Ashlam Ehrenschlag von den Ereignissen der Schlacht von Andorhal.", completion = "Verloren? Nein... als nächstes werden sie sich dann wohl Zugwind vornehmen. Das war ein schwerer strategischer Rückschlag für die Pläne der Allianz in Lordaeron.\n\nNun gut. Ich werde das Ergebnis dieser Schlacht König Wrynn melden. Er wird wohl nicht gerade glücklich darüber sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[27208] = { id = 27208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schreckenslord Balnazzar", description = "Mit dem Untergang des Scharlachroten Kreuzzugs entließ der getarnte dämonische Anführer Balnazzar den besessenen Körper des Obersten Kreuzfahrers Dathrohan und begab sich auf einen Amoklauf, bei dem er auch den letzten überlebenden Kreuzfahrer in den Tod riss. Dann nutzte er seine nekromantischen Kräfte, um sie zu widerwärtigen untoten Sklaven zu machen.\n\nBalnazzar nennt diese neue Armee die Auferstandenen. Wir können nicht zulassen, dass diese Armee noch größer wird. Diese Krieger sind äußerst mächtig, und im Gegensatz zu Arthas' Geißel wird Balnazzar seine Streitmächte nicht zurückhalten. Tötet ihn, solange wir noch in der Lage dazu sind, {class}.", sourceObjective = "Tötet Balnazzar.", completion = "Es ist gut, dass wir Balnazzar fürs Erste aufhalten konnten. Es wird nicht mehr lange dauern, bis seine Armee ganz Stratholme eingenommen hat, und ihm so ein mächtiges Herzstück für sein neues, unheiliges Reich bietet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27210] = { id = 27210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verräter unter uns", description = "Schön, Euch zu sehen, {class}. Ich bin nach Theramore gekommen, um bei der Lösung des Problems mit den Deserteuren zu helfen. Einige der Männer haben nicht nur ihren Posten verlassen, nein, sie haben sich zurück in die Stadt geschlichen.\n\nDiese Agenten der Deserteure verbreiten Lügen und Propaganda. Sie erhoffen sich davon, andere von ihrer Sache zu überzeugen, damit sie sich ihnen anschließen.\n\nSie sind nahezu bei jedem Wachposten der Stadt und bei den Docks. Findet sie, entlarvt sie und diskreditiert sie. Im Moment würde alles andere nur dazu führen, dass sie an Sympathie gewinnen.", sourceObjective = "Konfrontiert 5 Aufwiegler der Deserteure in Theramore.", completion = "Gut gemacht, {name}. Ich glaube, wir haben sie überrascht. Ihre Agenten wähnten sich innerhalb der Stadt vermutlich in Sicherheit.\n\nMit der Zeit werden die Aufwiegler zurückkehren und ihre Lügen wieder verbreiten. Wir werden die Zeit, die Ihr uns verschafft habt, nutzen, um die Deserteure weiter auszusperren.", sourceObjectiveStatus = "unverified-source-field" }
quests[27211] = { id = 27211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Propagandakrieg", description = "Die Agenten der Deserteure haben weitaus mehr getan, als nur die Wachen zu beschwatzen. Wir haben eine Reihe von Handzetteln gefunden, die die Deserteure offenbar auf einem Schiff zu den Docks geschmuggelt haben.\n\nDas Schiff, auf dem die Handzettel geladen waren, liegt noch immer in Theramore bei dem am weitesten entfernten Dock vor Anker. Wenn Ihr Euch heimlich an Bord schleichen und das restliche Propagandamaterial in Beschlag nehmen könntet, würden die Agenten ihre wichtigste Waffe verlieren. Seid auf der Hut! Das Schiff ist mit erfahrenen Freibeutern bemannt und die Fracht befindet sich womöglich in der Kajüte des Kapitäns.", sourceObjective = "Erhaltet das Propagandamaterial der Deserteure vom Schiff am Ende der Docks in Theramore.", progress = "Konntet Ihr die restlichen Propagandahandzettel finden und beschlagnahmen?", completion = "<Die SI:7-Agentin nickt zustimmend.>\n\nAusgezeichnet. Jetzt müssen wir die Deserteure nur noch diskreditieren, damit sie in Theramore nie wieder Fuß fassen können. Ich weiß auch schon wie.", sourceObjectiveStatus = "unverified-source-field" }
quests[27212] = { id = 27212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diskreditierung der Deserteure", description = "Ich habe die Handzettel, die Ihr den Söldnerkumpanen der Deserteure beim Dock abgenommen habt, verfälscht. Jeder, der diese Zettel jetzt lesen wird, erhält mit Sicherheit einen ganz anderen Eindruck von den Deserteuren und ihren Absichten.\n\nWenn wir genug davon an die Wachen verteilen, wird es den Deserteuren einfach zu peinlich sein, hier jemals wieder Fuß zu fassen.\n\n<Calia überreicht Euch einen Stapel verfälschte Handzettel.>\n\nFangt doch schon einmal an, während ich den nächsten Schritt plane.", sourceObjective = "Verteilt verfälschte Handzettel an 6 Wachen von Theramore.", progress = "Ich dachte, ich hätte Gelächter bei den Kasernen gehört. Habt Ihr die Handzettel verteilt, die ich Euch gegeben habe?", completion = "<Calia kichert, als Ihr von der Reaktion der Wachen auf das Propagandamaterial berichtet.>\n\nGenau wie ich gehofft hatte! Ich bin mir sicher, dass jeder Agent der Deserteure, der versucht Theramore zu infiltrieren, sofort ausgelacht wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[27213] = { id = 27213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende der Deserteure", description = "Jetzt, da wir die Deserteure aus Theramore vertrieben haben, ist es an der Zeit, unseren Plan zu Ende zu bringen. Meine Kontakte vor Ort haben mir berichtet, dass die Operationsbasis der Deserteure ein Schiff ist, das bei einer kleinen Insel südöstlich der Docks vor Anker liegt.\n\nDie Festnahme ihres Anführers, Gavis Grauschild, wird die anderen entmutigen. Macht ihn innerhalb des Schiffs ausfindig und überzeugt ihn davon, zu kapitulieren. Es würde mich nicht überraschen, wenn er sich mit einem spektakulären Kampf zur Wehr setzt, aber aufgibt, sobald er verstanden hat, dass er nicht gewinnen kann.", sourceObjective = "Besiegt Gavis Grauschild auf dem Schiff südöstlich von Theramore.", completion = "Gavis' Forderung ist nicht so haarsträubend wie sie scheint. Wenn man sie richtig behandelt, gelingt es Lady Jaina vielleicht sogar die Deserteure wieder in unsere Gemeinschaft zu integrieren. Doch diese Entscheidung obliegt alleine ihr.\n\nEs war mir eine große Freude mit Euch zu arbeiten, {name}! Ohne Eure Hilfe wäre die gesamte Operation sicherlich nicht halb so glatt gelaufen. Ich werde Euch in meinem Bericht an Sturmwind lobend erwähnen, so dass alle wissen, dass es Euer Einsatz war, der der Bedrohung durch die Deserteure ein Ende gesetzt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[27214] = { id = 27214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beunruhigende Berichte", description = "Unsere Spähpatrouillen haben in letzter Zeit Beunruhigendes zu Tage gefördert. Sie berichten von Männern mit roten Kopftüchern der Defias, die entlang der Schreckensmoorküste nördlich von Theramore umherwandern.\n\nWrackteile in dieser Gegend lassen darauf schließen, dass es sich um Überlebende eines Schiffbruchs handelt, aber uns mangelt es an Informationen. Hauptmann Wymor bei der Späherwacht, einem Wachturm nördlich der Stadt, sucht nach einem Helfer, der diesen Berichten nachgeht.", sourceObjective = "Erstattet Hauptmann Wymor bei der Späherwacht Bericht.", completion = "<Der Hauptmann versucht ganz offensichtlich Eure Fähigkeiten einzuschätzen.>\n\nIhr habt also von dem Schiffswrack an der Küste gehört? Gut, ich könnte noch etwas Hilfe gebrauchen, um meinen Verdacht gegenüber den Überlebenden zu bestätigen. Willkommen an Bord, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27215] = { id = 27215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Einsiedler beim Irrlichtanwesen", description = "Es gibt da einen Burschen - die Einheimischen nennen ihn \"Sumpfauge\" Jarl - der alleine draußen im Sumpf lebt. Vor nicht allzu langer Zeit hat er sich im Irrlichtanwesen einquartiert, nachdem die vorherigen Bewohner unter geheimnisvollen Umständen verschwunden sind.\n\nVon Zeit zu Zeit schicke ich jemanden aus, um dort nach dem Rechten zu sehen. Wisst Ihr, irgendwie erinnert er mich an meinen Großvater. Manche sagen, dass er nicht alle Tassen im Schrank hat.\n\nFolgt der Straße von Theramore aus in Richtung Nordwesten, und Ihr werdet das Irrlichtanwesen am Hexenhügel finden, bevor die Straße in Richtung Westen abbiegt.", sourceObjective = "Sprecht mit \"Sumpfauge\" Jarl im Irrlichtanwesen.", completion = "Runter von meinem Rasen! Es sei denn, Ihr möchtet dem alten Sumpfauge ein bisschen beim Kochen helfen. Was meint Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[27216] = { id = 27216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der alte Leuchtturm", description = "Der alte Leuchtturm östlich von hier ist schon seit Langem nicht mehr funktionstüchtig. Babs Zischeldrill hat es sich allerdings in den Kopf gesetzt, ihn wieder zum Laufen zu bringen.\n\nIch weiß zwar nicht, wie sie das alleine bewerkstelligen will, aber sie behauptet, dass die Schiffe und ihre Fracht dann reibungsloser zu den Docks gelangen werden. Was kann ich dagegen schon einwenden? Man sollte sich nicht über die Arbeit auf den Docks beschweren, wenn man bedenkt, dass man genauso gut an vorderster Front stehen könnte, oder?", sourceObjective = "Sprecht mit Babs Zischeldrill am Leuchtturm auf der Insel östlich von Theramore.", completion = "Gut. Ich kann jegliche Hilfe gebrauchen. Das Wichtigste ist, die Lampe wieder zu entzünden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27217] = { id = 27217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drescheröl", description = "Im alten Logbuch des Leuchtturms steht, dass die Lampe mit dem Öl von Dreschern, die entlang der Küste hier leben, betrieben wurde.\n\n<Babs rümpft bei der Erwähnung dieser veralteten Technologie ihre Nase.>\n\nIch vermute, dass es sich hierbei um eine praktische, wenn auch weniger elegante Lösung handelt. Im Logbuch wurde vermerkt, dass das Öl von jungen Düsterdreschern am besten funktioniert. Sie sind unterhalb der Docks von Theramore zu finden.\n\nWürdet Ihr mir helfen, den Leuchtturm wieder mit Öl zu versorgen?", sourceObjective = "Sammelt 4 Behälter mit Drescheröl von den Düsterdreschern unter den Docks von Theramore.", progress = "Konntet Ihr das Drescheröl bekommen?", completion = "Ich habe immer noch meine Zweifel, aber momentan ist das die einzige Lösung. Sobald wir sie zum Laufen gebracht haben, werden wir sicherlich die Zeit finden, um die Lampe auch anderweitig mit Energie zu versorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27218] = { id = 27218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimtückische Bewohner der Tiefe", description = "Wisst Ihr was? Es ist erstaunlich, was man alles in diesem alten Leuchtturm finden kann. Nachdem ich die Lampe angezündet hatte, bemerkte ich dieses Buch in einem dieser alten Koffer da oben.\n\n<Babs hält das Buch in die Höhe und liest den Titel mit lauter und dramatischer Stimme vor.>\n\n\"Heimtückische Bewohner der Tiefe!\"\n\nBeim Anblick einer dieser Bestien wäre ich bestimmt in Ohnmacht gefallen! Sicherlich ist es den einen oder anderen Lacher wert, aber mir fehlt momentan einfach die Zeit zum Lesen.\n\nIch kenne da aber jemanden, dem diese Lektüre gefallen könnte... der alte Fischhändler bei den Docks, Michael \"Schmutz\" Fink. Er sammelt alte Bücher.", sourceObjective = "Bringt das Buch \"Heimtückische Bewohner der Tiefe\" zu Michael \"Schmutz\" Fink bei den Docks von Theramore.", progress = "Was darf es heute sein? Der Barsch ist ausgezeichnet.", completion = "Nun ja, mir dieses Buch zukommen zu lassen, war ganz schön aufmerksam von der alten Babs. Ich weiß nicht, ob Ihr ein wenig darin geblättert habt, aber in den Geschichten steckt schon die ein oder andere Wahrheit. Seefahrer erfinden so was nicht einfach, versteht Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[27219] = { id = 27219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ist das wahr?", description = "Oh, ich bin mir sicher, dass Ihr und Babs bei einigen der haarsträubenden Beschreibungen und Zeichnungen im Buch laut lachen musstet. Aber habt Ihr Euch auch mal überlegt, dass an diesen Legenden etwas Wahres dran sein könnte?\n\nWenn Ihr gut genug aufpasst, dann könnt Ihr die Seefahrer mit Sicherheit noch über Tethyr reden hören, die Meereskreatur, die laut dem Buch genau hier lebt! Wenn Ihr sicher gehen wollt, dann könnt Ihr natürlich den alten Nat Pagle fragen.\n\nIhr findet ihn bei seinem Angelplatz auf einer kleinen Insel in Tidenbucht, südwestlich jenseits der Bucht der Düstermarschen.", sourceObjective = "Sprecht mit Nat Pagle bei Nats Angelplatz in Düstermarschen.", completion = "Ihr wollt also mehr über Meeresungeheuer erfahren? Hmm ... also, ich mache Euch einen Vorschlag. Es wird aber viel Alkohol im Spiel sein und für Euch könnte es ein bisschen peinlich werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27220] = { id = 27220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nats Abmachung", description = "Ihr habt also eine Kopie von \"Heimtückische Bewohner der Tiefe\", ist das so? Nun, aus meiner Erfahrung heraus kann ich Euch sagen, dass alles wahr ist. Ich habe sogar ein paar dieser Biester mit meinen eigenen Augen gesehen.\n\nIhr wollt aber etwas über Tethyr erfahren. Ich sagte ja bereits, dass ich Euch ein Angebot machen würde, also hört gut zu. Ich arbeite an einer neuen Art von Köder, habe diesen hier aber noch nicht getestet.\n\nNehmt diese Paste - ja, sie stinkt etwas faulig - beschmiert Euch damit selbst und schwimmt rüber zu dem Schiffswrack im Südwesten. Solltet Ihr überleben, dann lasst mich wissen, wie es war!", sourceObjective = "Schmiert Euch mit Pagles Fischpaste, extra stark ein und schwimmt dann hinaus in die Tidenbucht.", progress = "Nicht vergessen, kommt erst zurück, wenn Euch etwas gebissen hat!", completion = "Nicht schlecht. An Eurer Stelle würde ich allerdings so schnell wie möglich ein Bad nehmen.\n\nJetzt zu Eurem Meeresungeheuer...\n\nNehmt Euch ruhig ein Bier oder zwei, während ich Euch die Geschichte erzähle.", sourceObjectiveStatus = "unverified-source-field" }
quests[27221] = { id = 27221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, es ist wahr!", description = "Ja, Tethyr gibt es wirklich. Das Monster lebt in den Gewässern rund um Theramore.\n\nEs mag sehr gerne helle Lichter, deshalb hat man den Leuchtturm überhaupt erst geschlossen, versteht Ihr...\n\nWenn Ihr den Turm wieder in Betrieb nehmt, wird das Biest sofort wieder auftauchen. Natürlich würde niemand mit gesundem Menschenverstand dergleichen tun.\n\nIhr solltet Euch also darum kümmern. Es war schön, bei einem Bierchen mit Euch plaudern zu können, aber gebt dem alten Nat bloß nicht die Schuld, wenn Tethyr Euch WIRKLICH in einen Fischköder verwandelt. Bevor Ihr Euren Plan in die Tat umsetzt, sprecht auf jeden Fall mit Major Mühlens bei den Docks von Theramore.", sourceObjective = "Sprecht mit Major Mühlens bei den Docks von Theramore.", completion = "<Ihr berichtet von Eurem Erlebnis mit Nat Pagle, seid jedoch bemüht, den Teil der Geschichte mit dem 'Ködertest' auszulassen.>\n\nNun, es scheint, als haben wir etwas zu tun. Ich mache mich an die Vorbereitungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27222] = { id = 27222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bezwingt Tethyr!", description = "Meeresungeheuer hin oder her, wir werden auf keinen Fall die Sicherheit unserer Schiffe aufs Spiel setzen. Ich habe unsere besten Schützen angewiesen, sich auf eine Begegnung mit Tethyr vorzubereiten. Die Artilleristen haben die Verteidigung der Docks mit drei Mörsern verstärkt.\n\nIch werde den Befehl zum Entzünden der Leuchtturmlampe erteilen. Falls Tethyr angreift, müsst Ihr die Mörser bedienen und das Biest bezwingen, bevor es alle Schützen tötet. Ich würde allerdings nicht zu lange an einer Stelle bleiben. Die Verwendung der Mörser wird mit Sicherheit die Aufmerksamkeit des Ungeheuers erregen.", sourceObjective = "Benutzt die Mörser, um Tethyr zu besiegen.", completion = "Gute Arbeit, {name}! Ich gebe zu, dass ich beim ersten Anblick des Biests meine Zweifel hatte, dass wir die Docks verteidigen können, aber Ihr habt die Verteidiger bestens zusammengehalten!", sourceObjectiveStatus = "unverified-source-field" }
quests[27223] = { id = 27223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergeltung", description = "Dort, wo die Marktgasse auf die Feststraße trifft, werdet Ihr auf den Unverziehenen treffen. Wenn Ihr alle auf dem Kreuzzüglerplatz tötet, werdet Ihr auch Timmy den Grausamen erwischen. Diese beiden ehemaligen Champions haben den Unschuldigen hier gegenüber schreckliche Taten vollbracht, um unheilige Macht zu erlangen.\n\nIhr müsst sie beide besiegen, um Stratholme von ihrer finsteren Anwesenheit zu befreien. Seid wachsam, denn sie waren zu Lebzeiten mächtige Kämpfer, und durch den Erhalt ihrer neuen dunklen Kräfte wurden sie nur noch stärker.", sourceObjective = "Tötet den Unverziehenen und Timmy den Grausamen.", completion = "Erhaltet dies als Belohnung. Ich hab es in der Rüstung einer Geißel gefunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27225] = { id = 27225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufforderung von Ander Germaine", description = "Ander Germaine hat verlauten lassen, dass er Euch für Euren meisterhaften Umgang mit den Waffen und Eurer Zuschreibung zur Allianz ehren möchte. Macht Euch auf nach Sturmwind und verlasst das Altstadtviertel durch den südlichen Ausgang. Ihr werdet ihn in seiner Kommandozentrale finden. Ich weiß nicht, was er vorhat, aber ich glaube, er ist von Eurem raschen Fortschritt beeindruckt.", sourceObjective = "Sprecht mit Ander Germaine in der Kommandozentrale von Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[27226] = { id = 27226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Um ein Seebärenhaar", description = "Dem Kriegshäuptling sei Dank, dass Ihr hier seid, {name}. Mir ist ein schwerwiegender Fehler mit den Seebären unterlaufen und ich brauche Eure Hilfe, um die Sache wieder gerade zu biegen.\n\nIch habe sie stocknüchtern losgeschickt, um gegen die Worgen zu kämpfen, die von der Insel Fenris kamen. Sie haben die Bestien angegriffen und haben ordentlich was einstecken müssen. Viele sind gefallen, aber ein paar leben noch und kämpfen nun um ihr Leben.\n\nBringt dieses Bierfass zu den Verfallenen Feldern östlich von hier und seht zu, dass kein Schluck übrig bleibt.", sourceObjective = "Weckt 8 orcische Seebären auf.", completion = "AHA! Ich wusste es! Da haben wir wohl wieder etwas gelernt. Wir werden nicht wieder so versagen. Ich werde sicherstellen, dass immer Bier an vorderster Front bereitsteht.", sourceObjectiveStatus = "unverified-source-field" }
quests[27227] = { id = 27227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron Aurius Totenschwur", description = "Diese Kapelle ist das letzte Licht in der wachsenden Dunkelheit. Ras Frostraunen nahm sich auf dem Schlachthof sein Leben und schlitzte vor dem Lichkönig sein Gesicht in ein makabres Lächeln. Der Lichkönig nahm sich seiner an und machte ihn zu dem Lich, der jetzt Scholomance heimsucht.\n\nDer Ort, an dem diese Gräueltat geschah, ist nun heiliger Boden der Geißel, und wurde vom Lichkönig mit der dunkelsten aller Magie gesegnet. Baron Aurius Totenschwur, der neue Herrscher von Stratholme, bewacht diesen Ort und führt die grausame Arbeit seines Meisters fort. Tötet ihn, ohne zu zögern.", sourceObjective = "Tötet Baron Aurius Totenschwur.", completion = "Stratholme wird zum Symbol für alles Gute in dieser Welt werden. Ihr habt meinen Dank für Eure Arbeit in dieser Mission.", sourceObjectiveStatus = "unverified-source-field" }
quests[27228] = { id = 27228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mann gegen Monstrosität", description = "Tief im Inneren werdet Ihr Ramstein den Verschlinger finden. Ich wage es kaum, Euch von den Gräueltaten zu erzählen, die dieses Monster vollbracht hat. Ihr müsst nur wissen, dass er den gesammelten Zorn zahlloser verirrter Seelen zu Gesicht bekommen soll; Zorn, den Ihr über ihn bringen werdet.\n\nHabt keine Gnade. Seid standhaft in Eurer Wut.", sourceObjective = "Tötet Ramstein den Verschlinger.", completion = "Die Macht, mit der Ihr Ramstein getötet habt, verdient meinen Respekt. Wenn echte Wut in den Taten zu sehen ist, kann wohl selbst die Geißel Angst empfinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27229] = { id = 27229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ZERMATSCHT DIE BRUTKÖNIGIN", description = "<Der folgende Text ist in sehr großer Schrift geschrieben.>\n\nSPINNEN IN NORDHÖHLE BÖSE. VERGIFTEN OGER. OGER WERDEN KRANK. SCHLECHT!\n\nGROSSE RIESENSPINNE IN HÖHLE MACHT MEHR SPINNEN. MEHR SPINNEN SCHLECHT!\n\nTÖTET GROSSE SPINNE, AUFHALTEN NEUE SPINNEN. TÖTET GROSSE SPINNE, GROSSE BELOHNUNG! GUT!\n\n<Eine primitive Skizze wurde unter der Nachricht geschmiert.>", sourceObjective = "Beschafft den Pedipalpus der Brutkönigin.", progress = "Seid Ihr wegen des Schilds hier?\n\nIch möchte nicht darüber sprechen, es sei denn, Ihr habt einen Beweis für die Tötung.", completion = "Bei Grom - bin ich froh, dass es vorbei ist. Wenn Ihr das Schild gelesen habt, ist Euch vielleicht klar, wie verzweifelt ich war, nachdem ich versucht hatte, mit diesen schwerfälligen Trotteln zu kommunizieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[27230] = { id = 27230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen für den Krieg", description = "Die Geißel sind Meister im Schmieden mächtiger Waffen für ihre Krieger, und das macht es für unsere Männer schwieriger, sie zu töten! In der Nähe der Ziggurat von Baroness Anastari sind Schmiedekunstpläne, die der Oberste Schwertschmied nutzen wird, um eine äußerst mächtige Waffe für Lord Aurius zu schmieden.\n\nWir werden verhindern, dass diese Waffe geschmiedet wird, und gleichzeitig dafür sorgen, dass sie auch keine normalen Waffen mehr herstellen werden! Nehmt die Schmiedekunstpläne an Euch, und tötet den Schwertschmied der schwarzen Wache, wenn er kommt, um die Pläne zu verteidigen. Das wird unsere Aufgabe erleichtern.", sourceObjective = "Tötet den Schwertschmied der schwarzen Wache.", progress = "Ihr müsst den Schwertschmied töten! Los!", completion = "Großartig! Wir werden durch ihren Verlust einer verlässlichen Bezugsquelle für Waffen siegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27231] = { id = 27231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung aus Fenris", description = "Diejenigen, die Euren Angriff auf die Insel Fenris überlebten, konnten das Blut des Wolfes trinken. Sie wurden zu wilden Worgen, die nichts anderes als Rache im Sinn haben. Nun schwimmen sie über den Lordameresee und greifen meine Seebären an. Viele wurden bereits getötet. Die Worgenmonster müssen aufgehalten werden!\n\nMacht Euch auf den Weg zur verfallenen Fähre östlich von hier und tötet die Worgen des Hügellands, die diese Gegend heimsuchen. Sobald Ihr sie getötet habt, macht Euch auf den Weg zur Kommunikationskonsole der Horde bei den Docks. Ich werde mich mit Euch in Verbindung setzen.", sourceObjective = "Tötet 10 Worgen des Hügellands.", completion = "<Hatchets Kommunikationsgerät rauscht.>\n\nHatchet hier, sind alle tot?", sourceObjectiveStatus = "unverified-source-field" }
quests[27232] = { id = 27232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rot gefärbte Gewässer ...", description = "<Das Kommunikationsgerät brummt.>\n\nDie Worgen, die Ihr getötet habt, waren der Spähtrupp. Hunderte von ihnen sind auf dem Weg! Es scheint, als haben Crowley und Blutfang allen Menschen in Lordaeron das Blutopfer angeboten.\n\nNehmt eine von diesen Kanonen der Horde und schickt sie dorthin zurück, wo sie herkommen. Färbt die Wasser des Lordameresees rot mit ihrem Blut!", sourceObjective = "Tötet 50 Worgen des Hügellands mit der Kanone der Horde.", completion = "Auch wenn Ihr viele der neuen Worgen getötet habt, können wir sicher sein, dass noch viel mehr von ihnen erscheinen werden. Ihr Angriff wurde jedoch geschwächt. Gute Arbeit, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[27233] = { id = 27233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stätte der Heiler", description = "Nun kann ich die Ausbildung selbst in die Hand nehmen. Falls Ihr nach Arbeit sucht, kann ich Euch empfehlen, der Straße nach Nordwesten zu folgen. Die Cenarischen Druiden und der Argentumkreuzzug haben dort auf Dalsons altem Hof ihr Lager aufgeschlagen. Vielleicht können sie Euch beschäftigen, bis wir hier wieder Hilfe benötigen.", sourceObjective = "Meldet Euch bei Außenagent Kaartish in der Stätte der Heiler in den Westlichen Pestländern.", completion = "Willkommen, {class}. Wie Ihr sehen könnt, besteht unser Lager aus einer Gemeinschaftsexpedition des Argentumkreuzzugs und Druiden des Zirkels des Cenarius. Wir heißen jedoch alle willkommen, die bei der Heilung des Landes helfen wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27234] = { id = 27234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defias in Düstermarschen?", description = "Meine Späher haben von einem Schiffswrack nahe des Strands im Nordosten berichtet. Schiffswracks sind hier draußen zwar nichts Ungewöhnliches, aber den Berichten zufolge tragen die Überlebenden alle rote Kopftücher. Das ist das Symbol der Defias!\n\nAnscheinend hält sich ihr Anführer auf einer großen Insel in der Nähe der Küste nordöstlich des Turms auf. Tötet ihn, und nehmt alle Unterlagen an Euch, die Ihr bei ihm findet.", sourceObjective = "Erhaltet die Befehle der Defias von Garn Mathers.", progress = "Konntet Ihr ihren Anführer finden?", completion = "<Hauptmann Wymor nimmt die Befehlspapiere entgegen und liest sie durch.>\n\nWas könnte wohl mit 'wertvoller Fracht' gemeint sein? Die Defias haben öfter kleine Schmuggelaktionen in Sturmwind durchgeführt, aber das hier scheint in einer ganz anderen Größenordnung zu sein. Die Sprache, in der diese Befehle verfasst wurden, ist die eines Reichens oder Adligen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27235] = { id = 27235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renn McGill", description = "Die von Euch erlangten Befehle weisen darauf hin, dass die Defias besonders erpicht darauf sind, ihre Fracht auszumachen und zu bergen.\n\nDer SI:7 arbeitete rund um Theramore eine Zeit lang mit dem Bergungstaucher Renn McGill zusammen. Als er von dem Schiffswrack erfuhr, machte sich Renn sofort auf den Weg nach Norden, um in der Nähe der Inseln, die von den Defias besetzt werden, zu tauchen.\n\nWenn wir vor den Defias an die Fracht gelangen wollen, werden wir seine Hilfe benötigen. Haltet in den Gewässern nordöstlich einer kleinen Insel nach ihm Ausschau. Sie liegt im Norden der Insel, die Ihr zuvor schon einmal besucht habt.", sourceObjective = "Bringt die Befehle der Defias zu Renn McGill in den Gewässern nahe Schreckensmoorküste.", progress = "Seid gegrüßt, {class}. Was führt Euch hierher?", completion = "<Renn liest die Befehle durch.>\n\nEs war also wirklich wertvolle Fracht auf dem Schiff! Wir müssen sie finden, bevor die Defias uns zuvorkommen. Diese Jungs sind keine Taucher, aber wir brauchen einen Teil ihrer Ausrüstung, damit Ihr mir helfen könnt, die Fracht zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27236] = { id = 27236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tauchausrüstung aus zweiter Hand", description = "Zwischen hier und der Insel Alcaz liegen zahlreiche Wrackteile auf dem Meeresgrund. Die Defias haben bereits Taucher entsandt, die die Gewässer absuchen. Mithilfe einiger ihrer Ausrüstungsteile könnten wir Euch so ausstatten, dass Ihr Euch der Jagd anschließen könnt. Ihr müsstet allerdings erst einen Weg finden, wie Ihr an diese \"Leihgabe\" kommt.\n\nSucht diese Insel nach einer Kiste mit Tauchausrüstung und etwas zum Reparieren ab. Wenn Ihr das Material gefunden habt, bringt es zu mir und ich werde es in null Komma nichts einsatzbereit machen!", sourceObjective = "Bringt den Werkzeugsatz und die beschädigte Tauchausrüstung zu Renn McGill in Düstermarschen.", progress = "Mal sehen, was Ihr so von den Defias \"leihen\" konntet.", completion = "Oha, die Ausrüstung ist in schlechterer Verfassung, als ich gedacht hatte, und das Werkzeug...\n\nNaja, ich habe gesagt, dass ich es für Euch einsatzbereit machen kann, also mache ich mich besser mal an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[27237] = { id = 27237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergt die Fracht!", description = "Nun, ich konnte die Ausrüstung so reparieren, dass Ihr damit zumindest eine Weile lang tauchen könnt. Allerdings würde ich das Ganze nicht allzu lange auf die Probe stellen.\n\nDie Wrackteile des Schiffs sind auf dem Meeresgrund zwischen der Ostküste dieser Insel und der Insel Alcaz verstreut. Solange dieser Tauchhelm funktioniert, solltet Ihr versuchen, Teile des Wracks zwischen hier und Alcaz auszumachen. Verwendet diese Bergungsausrüstung, um die Wrackteile nach Spuren der Fracht zu durchsuchen. Gebt Acht, dass Ihr der Insel Alcaz nicht allzu nahe kommt. Die Hydras dort sind gefährlich.", sourceObjective = "Sammelt 1 geborgene Geldkassetten.", progress = "Habt Ihr bei der Durchsuchung der Wrackteile etwas über die Fracht der Defias in Erfahrung bringen können?", completion = "<Renn durchwühlt die Inhalte der Geldkassetten, die Ihr geborgen habt.>\n\nGute Arbeit. Sehen wir nach, ob die 'wertvolle Fracht' auch hier drin ist ...", sourceObjectiveStatus = "unverified-source-field" }
quests[27238] = { id = 27238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jaina muss davon erfahren", description = "Ihr müsst Lady Jaina sofort von unserem Fund berichten! Wenn die Defias einen Gefangenen an Bord hatten, dann ist es schwierig, herauszufinden, wer es ist und ob diese Person noch am Leben ist!\n\nEines ist jedoch sicher, {name}. Die Defias würden all diese Schwierigkeiten nicht aus bloßer Gehässigkeit auf sich nehmen. Ihr Gefangener muss jemand von Wichtigkeit sein. Lady Jaina kann mit Sicherheit mehr als jeder andere mit diesen Fundstücken anfangen. Ihr findet sie hoch oben im Magierturm im Zentrum von Theramore.", sourceObjective = "Sprecht mit Lady Jaina Prachtmeer in Theramore.", completion = "Ihr und Renn habt ausgezeichnete Arbeit geleistet, diese Informationen zu Tage zu bringen und sofort Bericht zu erstatten. Jetzt müssen wir den Fund bestätigen. Es würde schwerwiegende Ausmaße annehmen, wenn wir falsch liegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27239] = { id = 27239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beobachtet die Insel Alcaz", description = "Offenbar hatte Renn mit seinen Vermutungen über die Insel Alcaz Recht. Wir müssen diese Insel beobachten. Dazu bräuchten wir allerdings eine ganze Brigade von Soldaten.\n\nTheramores Verteidigung könnte einen derartigen Schlag nicht überstehen, also habe ich mich mit Cassa Purpurschwinge, dem Greifenmeisterlehrling von Theramore, abgesprochen. Sie wird uns eines ihrer Tiere für die Beobachtung der Insel Alcaz aus der Luft überlassen.\n\nDie Insel birgt den Schlüssel zum Geheimnis darüber, inwiefern die Defias in diese Entführung verwickelt sind.", sourceObjective = "Sprecht mit Cassa Purpurschwinge und nutzt einen ihrer Greifen, um die Insel Alcaz zu beobachten.", completion = "<Lady Jaina hört aufmerksam zu, als Ihr von Euren Funden der Luftbeobachtung berichtet.>\n\nEin Runenzirkel, Drachkin? Die Defias haben sich mit IHR verbündet? Der Verräterin?\n\n<Lady Jaina beruhigt sich und bereitet sich vor, die Situation zu erklären.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27240] = { id = 27240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweis des Verrats", description = "Onyxia wurde zwar entlarvt und vom Hofe entfernt, doch noch müssen die Defias, die ihren Plan ausgeführt haben, bestraft werden. Bringt König Varian Wrynn in Burg Sturmwind die Nachricht, dass die Defias für seine Entführung verantwortlich sind. Ich hege kaum Zweifel daran, dass der König die darin Verwickelten schnell und grausam bestrafen lassen wird.\n\nIch kann Euch mithilfe meiner Magie schneller nach Sturmwind bringen. Sagt einfach Bescheid, sobald Ihr bereit seid, {name}.", sourceObjective = "Sprecht mit Jaina, sobald Ihr bereit seid, nach Sturmwind zu reisen und König Varian Wrynn zu treffen.", completion = "Es waren die Defias, die Onyxia bei diesem Plot unterstützt haben?\n\n<Das Gesicht des Königs wird rot vor Wut, und er ballt seine Hände zu Fäusten.>\n\nIhr und Lady Jaina habt Sturmwind an diesem Tag einen großen Dienst erwiesen. Die Verräter werden nicht lange genug leben, um ihre Verbrechen zu bereuen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27241] = { id = 27241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Jaina", description = "Ich muss mich darum kümmern, die Reste der Defias zu beseitigen. Bitte überbringt Lady Jaina in Theramore meinen Dank. Sie ist schon immer ein treuer Freund und loyaler Verbündeter gewesen.\n\nGeht zum Magierviertel im Westen der Stadt und sprecht dort am Fuße des Turms mit Erzmagier Malin. Er wird Euch rasch wieder nach Theramore bringen.", sourceObjective = "Kehrt zu Lady Jaina Prachtmeer in Theramore zurück.", completion = "Ich habe keine Zweifel daran, dass der König jedes einzelne Wort ernst gemeint hat, als er Euch von seinen Plänen unterrichtete, die Defias ein für alle Mal zu vernichten. Er ist kein Mann leerer Versprechen, und die Feinde Sturmwinds sollten das wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27242] = { id = 27242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptorenfänger", description = "Im nordöstlichen Sumpfgebiet lebt eine ganz besonders gefährliche Raptorenart. Wir haben schon mehr als einen unachtsamen Soldaten an sie verloren. Ich denke jedoch, dass wir sie gegen unsere unliebsamen Nachbarn, die Grimmtotem, einsetzen könnten.\n\nNehmt dieses Seil und fangt damit Blutsumpfraptoren oder Blutsumpfkreischer ein, die Ihr zuvor überwältigt habt. An Eurer Stelle würde ich sie zunächst im Kampf schwächen, bevor ich versuchen würde, sie einzufangen. Das wird ein ganz schön harter Kampf werden.", sourceObjective = "Benutzt den strapazierfähigen Strick, um 6 Blutsumpfraptoren oder Blutsumpfkreischer zu fangen.", progress = "Konntet Ihr diese Raptoren einfangen?", completion = "Ihr seht ein wenig zerkratzt aus, aber das sollten keine schlimmen Wunden sein. Ihr seid sicherlich in einem besseren Zustand als die Grimmtotem in Kürze sein werden, wenn wir unsere neuen Raptorenfreunde auf sie loslassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27243] = { id = 27243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst die Raptoren los", description = "Jetzt, da wir unsere Raptoren haben, ist der nächste Schritt, sie zu einem Angriff auf die Grimmtotem im Dorf der Schwarzhufe im Nordwesten zu \"animieren\".\n\nIch habe hier noch eine übriggebliebene Lende von einem ... nun, eigentlich ist es völlig egal, was es ist. Ihr werdet dieses Fleisch als Köder verwenden. Platziert es in der Nähe der Windmühle im Zentrum des Dorfes der Schwarzhufe. Die Raptoren sollten sich um den Rest kümmern, falls das Training funktioniert hat.", sourceObjective = "Platziert den Raptorköder in der Nähe der Windmühle im Dorf der Schwarzhufe.", completion = "<Der Unteroffizier versucht gar nicht erst, sein Grinsen zu unterdrücken.>\n\nGut. Das sollte den einen oder anderen Angriff verhindern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27244] = { id = 27244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verlorene Bericht", description = "Beim Durchsuchen der lockeren Erde wird die abgetrennte Hand eines Orcs gefunden. Die Hand hält eine aus Knochen geschnitzte Röhre umklammert. Und in der Röhre befindet sich ein fleckiges Pergament.\n\nDas Pergament ist ein Bericht von einem Orc, der die Stadt Theramore über Wochen ausspionierte.\n\nAls Ihr das Pergament überflogen habt, ist klar, dass es zum orcischen Spionagemeister in Brackenwall gebracht werden muss.", sourceObjective = "Bringt den Bericht des Spions zu Nazeer Blutlanze in Brackenwall.", progress = "Habt Ihr etwas für mich?", completion = "Gute Arbeit, {name}. Unser Agent Marg Nachtauge war außerhalb von Theramore stationiert. Seine Aufgabe war es, die Stadt auszuspionieren. \n\nDas ist sein jüngster Bericht und könnte sein letzter sein; nach Eurer Aussage fürchte ich, dass Marg im Sumpf sein Ende fand...", sourceObjectiveStatus = "unverified-source-field" }
quests[27245] = { id = 27245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangene der Grimmtotem", description = "Wir tun, was wir können, um die Räuber der Grimmtotem in Schach zu halten, aber sie greifen den Turm immer wieder an. Was noch viel schlimmer ist, die Späher unserer Patrouillen, die vom Hauptmann entsandt werden, um Informationen zu sammeln und die Straße zu sichern, wurden von ihnen entdeckt und entführt.\n\nIch vermute, dass die Gefangenen zum Dorf der Schwarzhufe im Nordwesten gebracht wurden. Wie ich die Grimmtotem kenne, tragen die Verteidiger des Dorfes die Schlüssel zu den Käfigen der Gefangenen bei sich. Mir ist egal wie, {class}, aber bringt mir meine Männer lebend zurück.", sourceObjective = "Erlangt die Schlüssel der Grimmtotem von den Taurendruiden der Grimmtotem im Dorf der Schwarzhufe und benutzt sie, um 5 Gefangene von Theramore zu befreien.", completion = "Die befreiten Gefangenen sind bereits auf dem Heimweg vom Dorf der Schwarzhufe. Die Informationen, die der Hauptmann von den Gefangenen erhalten wird, werden uns in unserem nächsten Kampf gegen die Grimmtotem einen Vorteil verschaffen.\n\nIhr habt den Dank meiner Männer und mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[27246] = { id = 27246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Orcbericht", description = "Beim Durchsuchen der lockeren Erde wird die abgetrennte Hand eines Orcs gefunden. Die Hand hält eine aus Knochen geschnitzte Röhre umklammert. Und in der Röhre befindet sich ein fleckiges Pergament.\n\nDas Pergament ist in der Sprache der Orcs verfasst ... und sieht wichtig aus.", sourceObjective = "Bringt den Spionbericht zu Leutnant Aden in Theramore.", progress = "Habt Ihr etwas zu berichten?", completion = "Hm ... Mein Orcisch ist nicht sehr gut, aber dieses Schriftstück sieht aus wie ein Report, der von einem orcischen Spion geschrieben wurde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27247] = { id = 27247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hauptmann Mumm", description = "Hauptmann Mumm sollte den Orcbericht sehen, den Ihr gefunden habt, {name}. Er kennt die Sprache der Orcs besser als die meisten. Und er sollte wissen, dass sich Spione der Horde bei Theramore aufhalten!\n\nDer Hauptmann befindet sich in der Kaserne auf der nordöstlichen Seite der Insel Theramore.", sourceObjective = "Bringt den Spionbericht zu Hauptmann Garran Mumm.", progress = "Ihr habt etwas für mich?", completion = "Der Report von einem Orcspion! Wie habt Ihr das gefunden? Egal - erst sollten wir sehen, was hier steht ...", sourceObjectiveStatus = "unverified-source-field" }
quests[27248] = { id = 27248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission nach Morastwinkel", description = "Das Dampfdruckkartell hat vor Kurzem im südlichen Teil von Düstermarschen einen neuen Außenposten errichtet. Man taufte ihn Morastwinkel und er befindet sich entlang der Hauptstraße, südlich von Tabethas Hof und den Ruinen der Steinbrecher.\n\nDas ist eine hervorragende Gelegenheit für uns, neue Handelskontakte zu knüpfen, und Lady Jaina möchte, dass ich einen Abgesandten dorthin schicke, um Kontakt aufzunehmen. Wärt Ihr bereit, die Reise für uns aufzunehmen?", sourceObjective = "Sprecht mit Drazzit Tropfhahn in Morastwinkel.", completion = "Theramore ist also am Handel interessiert? Das ist kein Angebot, dass ich abschlagen möchte. Uns gehen die Vorräte hier auch langsam aus, und wir können alle Geschäftskontakte brauchen, die wir finden können!", sourceObjectiveStatus = "unverified-source-field" }
quests[27249] = { id = 27249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung der Ruinen", description = "Der arme James, er ist nie wirklich über die Zerstörung des Gasthauses \"Zur Süßen Ruh\" und den Tod seiner Familie hinweggekommen. Die Jungs und ich versuchen unser Bestmögliches, um die Monster, die dafür verantwortlich sind, zu finden.\n\nIch habe unseren besten Ermittlungsbeamten, Inspektor Tarem, zu den Ruinen geschickt. Einer allein wird mit dieser Aufgabe aber wohl kaum fertig werden. Wir würden es wirklich zu schätzen wissen, wenn Ihr Tarem helfen würdet. Beim Licht, wir würden alle gern da draußen sein und mithelfen.\n\nDie Hauptstraße führt Euch direkt zum Gasthaus, aber seid vorsichtig. Auf dieser Reise seid Ihr auf Euch selbst gestellt. Meine Soldaten können Euch keinen Schutz bieten.", sourceObjective = "Sprecht mit Inspektor Tarem beim Gasthaus \"Zur Süßen Ruh\".", completion = "Gut, dass Hauptmann Mumm endlich auch andere Leute in die Untersuchung einbindet.\n\nIch habe hier im Umkreis reflektierenden Staub verwendet.\n\nEr wird ungewöhnliche Gegenstände und Markierungen ans Licht bringen. So könnt Ihr Euch besser auf Eure Anstrengungen konzentrieren. Betrachtet alles genau, was vom Staub erleuchtet wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[27250] = { id = 27250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WIEDERVERARBEITUNG - SCHLECHTE KOPIE", description = "Bevor ich im Blauen Eremiten angefangen habe, wurde ich von einem der besten Köche und Gastwirte ausgebildet, die ich je getroffen habe. James Hyal hieß er. Meinen gesamten Besitz und Alles, was ich in meinem Leben je erreicht habe, verdanke ich ihm.\n\nIch frage mich, wie es ihm geht. Sein Bruder Vincent und er arbeiten in einer Taverne im Hafen von Menethil, aber ich habe schon länger nichts mehr von ihm gehört.\n\nFalls Ihr Euch jemals auf dem Weg nach Menethil wiederfindet, könntet Ihr im vielleicht meine Grüße ausrichten.", sourceObjective = "Sprecht mit Vincent Hyal im Hafen von Menethil.", sourceObjectiveStatus = "unverified-source-field" }
quests[27251] = { id = 27251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie nennen ihn den lächelnden Jim", description = "Der alte Jim da tut mir leid, ich kann mir nicht helfen. Er war nicht immer so. Hatte eine Zeitlang ein Gasthaus im Sumpf, ein wunderbares Lokal.\n\nAber eigentlich möchte ich nicht darüber sprechen. Besprecht es mit Hauptmann Mumm, wenn es sein muss. Ihr findet ihn auf der obersten Etage der Wehrzitadelle, der großen Kaserne östlich von Lady Jainas Turm.", sourceObjective = "Sprecht mit Hauptmann Garran Mumm auf der obersten Etage der Wehrzitadelle.", completion = "James Hyal ist sein richtiger Name. Er hat ein Gasthaus am Randes des Brachlands eröffnet. Er wollte Reisenden einen netten Ort für Übernachtungen anbieten...\n\nKönnte schon sein, dass er zu hochfliegende Pläne hatte, aber das Gasthaus lief eine Weile ganz gut. Dann haben wir die Kontrolle über die Straßen in den Marschen verloren und die Ogers haben alles übernommen.\n\nJames war zu stur, um seinen Traum gegen die Sicherheit innerhalb unserer Mauern einzutauschen und das Gasthaus \"Zur Süßen Ruh\" wurde niedergebrannt. Wir untersuchen den Vorfall noch, hatten bisher aber nicht viel Glück. Wenn Ihr helfen wollt, seht, was Ihr in den Trümmern finden könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27252] = { id = 27252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarze Schild", description = "Ein Eisenschild, von dem Feuer geschwärzt, das in dem Gasthaus wütete, ist an dem verfallenen Kamin befestigt, einer der wenigen erhaltenen Teile des Gebäudes, das einmal das Gasthaus \"Zur Süßen Ruh\" war.\n\nDer Schild lässt sich von den Mauersteinen des Kamins ablösen.", sourceObjective = "Bringt den geschwärzten Eisenschild zu Hauptmann Garran Mumm in Theramore.", completion = "Hm, ich bin kein Experte, was die Herstellung von Waffen und Rüstung angeht. Wie man sie handhabt, ja, aber nicht, wie man sie herstellt.\n\nDieser Schild scheint mir sehr gewöhnlich zu sein, bis auf den Schaden durch das Feuer, das im Gasthaus wütete.", sourceObjectiveStatus = "unverified-source-field" }
quests[27253] = { id = 27253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung der Ruinen", description = "Wenn Ihr der Straße vom Dorf aus nach Süden und dann westlich in Richtung Brachland folgt, werdet Ihr auf die Ruinen des Gasthauses \"Zur Süßen Ruh\" stoßen.\n\nTheramore hat einen Ermittlungsbeamten entsandt, um herauszufinden, von welchem Schicksal das Gasthaus heimgesucht wurde. Ich habe in dem Gasthaus einen Spion untergebracht und ich vertraue nicht darauf, dass diese Menschen kompetent genug sind, um in Erfahrung zu bringen, was damals passiert ist.\n\nEgal was Ihr findet, seht zu, dass der Ermittlungsbeamte es nicht in die Hände bekommt. Wir werden uns der Sache selbst annehmen.", sourceObjective = "Erforscht das Gasthaus \"Zur Süßen Ruh\" an der Grenze Brachlands in Düstermarschen.", completion = "<Der Inspektor mustert Euch voller Geringschätzung und Argwohn.>\n\nVerlasst diesen Ort, Bote, oder ich werde dafür sorgen, dass ich das nächste Mal mit einer Gefolgschaft Wachen herkomme, um Euch zu verdeutlichen, was ich meine.", sourceObjectiveStatus = "unverified-source-field" }
quests[27254] = { id = 27254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarze Schild", description = "Ein Eisenschild, von dem Feuer geschwärzt, das in dem Gasthaus wütete, ist an dem verfallenen Kamin befestigt, einer der wenigen erhaltenen Teile des Gebäudes, das einmal das Gasthaus \"Zur Süßen Ruh\" war.\n\nDer Schild lässt sich von den Mauersteinen des Kamins ablösen.", sourceObjective = "Bringt den geschwärzten Eisenschild zu Krog in Brackenwall.", progress = "Was habt Ihr da, {name}? Beweise aus den Ruinen vom Gasthaus \"Zur Süßen Ruh\"?", completion = "Ich gebe zu, dass Menschen nicht die besten Inneneinrichter sind, aber würden sie wirklich einen einfachen Eisenschild wählen, um ihren Kamin zu schmücken? Vielleicht wurde der Schild von denjenigen hinterlassen, die das Gasthaus in Flammen setzten.\n\nEine Warnung? Eine Drohung?", sourceObjectiveStatus = "unverified-source-field" }
quests[27255] = { id = 27255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarze Schild", description = "Hmm ... Ich sehe nichts Außergewöhnliches an diesem Schild. Wir sollten ihn Do'gol dem Schmied zeigen. Vielleicht kann er uns mehr verraten, aber ich würde keine Hoffnung hegen ...", sourceObjective = "Zeigt den geschwärzten Eisenschild Do'gol in Brackenwall.", progress = "Ihr habt etwas für mich, {class}?", completion = "Das ist ein guter Schild. Sehr stark, schwer, wirklich gut. Aber Do'gol kann damit nichts anfangen. Ich mache Schilde, und kaufe sie nicht, {name}.\n\nIhr solltet das wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27256] = { id = 27256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarze Schild", description = "Hmmm, hier am Rand des Schildes steht etwas geschrieben, aber durch die Brandspuren kann man es kaum lesen.\n\nIch brauche Säure, um ihn zu reinigen. Das Gift der Graunebelspinnen sollte dafür ausreichen. Die Spinnen haben sich in einer alten Mine in den Graunebelhöhlen nordwestlich der Siedlung eingenistet. Bringt mir ihre Giftsäcke und ich kann den Schild reinigen.", sourceObjective = "Sammelt 5 Säuregiftbeutel von Graunebelspinnen.", progress = "Habt Ihr die Beutel von den Spinnen?", completion = "Ich mag Spinnen nicht, die so groß sind, dass ich sie nicht einfach zerquetschen kann.\n\nDanke, dass Ihr das erledigt habt, {name}. Jetzt muss ich die Giftbeutel nur aufreißen und das Gift auf den Schild schütten ...", sourceObjectiveStatus = "unverified-source-field" }
quests[27257] = { id = 27257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarze Schild", description = "Oh, ich glaube, ich habe zu viel Säure auf den Schild geschüttet. Lasst mich ein wenig rubbeln ...\n\nHm, schwer zu lesen, sieht aber aus wie der Name Mosarn. Nie von ihm gehört. Vielleicht kennt Krog ihn. Krog kennt viele Leute.", sourceObjective = "Sprecht mit Krog in Brackenwall.", completion = "Mosarn? Kommt mir bekannt vor... Ich komm' nicht drauf. Vielleicht fällt es mir später wieder ein.\n\nIst wahrscheinlich nicht so wichtig. Ein Schild kann von überall herkommen und nichts bedeuten...", sourceObjectiveStatus = "unverified-source-field" }
quests[27258] = { id = 27258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarze Schild", description = "Ah, jetzt erinnere ich mich! Mosarn ist ein angesehener Schmied in Donnerfels. Ich wusste, dass ich den Namen irgendwo schon einmal gehört habe.\n\nAus Dankbarkeit hat mir der Irdene Ring eine Rüstung verliehen, die von Mosarn angefertigt wurde. Sehr gute Arbeit.\n\nVielleicht kann er Euch mehr über den Schild erzählen, den er hergestellt hat.\n\nEs ist nicht viel, aber da wir von Reethe nichts Nützliches in Erfahrung bringen konnten, ist es alles, was wir vorweisen können.", sourceObjective = "Zeigt den geschwärzten Eisenschild Mosarn in Donnerfels.", progress = "Hallo, {class}. Wie kann ich Euch helfen?", completion = "Ja, Ihr liegt richtig. Das ist ein Schild, den ich angefertigt habe.\n\nAllerdings kann ich Euch leider nicht sehr viel mehr darüber erzählen, {name}. Ich stelle so viele Schilder und Rüstungen her, dass ich nicht über alle Bescheid wissen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[27259] = { id = 27259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdächtige Hufabdrücke", description = "Hufspuren führen von den noch rauchenden Überresten des Gasthauses \"Zur Süßen Ruh\" weg. Wenigstens einige Abdrücke sind deutlich erkennbar, und weitere Abdrücke sind im weichen Schlamm des Sumpfs zu sehen, wenn man ganz genau hinsieht.", sourceObjective = "Berichtet Krog in Brackenwall von den verdächtigen Abdrücken beim Gasthaus \"Zur Süßen Ruh\".", completion = "Hufabdrücke... Ich denke, das waren möglicherweise die Stacheleber. Oder vielleicht ein Zentaur. Im Brachland gibt es recht viele von ihnen und es dürfte ihnen nicht schwerfallen, so eine Tat zu verüben\n\nHabe ich übrigens erwähnt... Nicht nur das Gasthaus wurde niedergebrannt. Die Frau und das Kind des Besitzers wurden getötet. Ganz üble Sache, das.\n\nNichtsdestotrotz, ich werden Kagoro schicken, um nachzusehen, wo die Spuren hinführen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27260] = { id = 27260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leutnant Paval Reethe", description = "Unter dem Geröll erregt ein Funkeln Eure Aufmerksamkeit. Nachdem Schmutz und Asche von dem Objekt gewischt wurden, kommt das Emblem eines goldenen Ankers auf einer weißen Emailleoberfläche zum Vorschein: das Zeichen von Theramore.\n\nUnter dem Anker ist der Name \"Leutnant Paval Reethe\" eingeprägt.", sourceObjective = "Bringt Reethes Abzeichen zu Krog in Brackenwall.", progress = "Habt Ihr weitere Hinweise auf die Geschehnisse im Gasthaus \"Zur Süßen Ruh\" gefunden?", completion = "Hmm ... also das ist interessant.", sourceObjectiveStatus = "unverified-source-field" }
quests[27261] = { id = 27261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befragt Reethe", description = "Es hat lange gedauert, aber ich habe Reethe gefunden. Für einen Menschen hatte er sich gut versteckt.\n\nOgron hatte Angst, nach dem langen Aufenthalt im Sumpf könnte er verrückt geworden sein. Ihr kommt mit mir, denn wir brauchen Antworten von ihm.", sourceObjective = "Folgt Ogron und sprecht mit Reethe.", completion = "Hmpf. Es ist gut, dass Reethe nicht mehr im Sumpf herumlungert. Ein Jammer, dass Menschen so empfindlich sind, dass er sich nicht von einer kleinen Pfeilwunde erholen konnte.\n\nOffenbar hat dieser Teil des Rätsels nirgendwohin geführt und wir müssen es anderswo versuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27262] = { id = 27262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdächtige Hufabdrücke", description = "Hufspuren führen von den noch rauchenden Überresten des Gasthauses \"Zur Süßen Ruh\" weg. Wenigstens einige Abdrücke sind deutlich erkennbar, und weitere Abdrücke sind im weichen Schlamm des Sumpfs zu sehen, wenn man ganz genau hinsieht.", sourceObjective = "Berichtet Hauptmann Garran Mumm in Theramore von den verdächtigen Abdrücken beim Gasthaus \"Zur Süßen Ruh\".", completion = "Hufabdrücke also? Es stimmt, in den Ländern nahe der Düstermarschen gibt es außergewöhnlich viele Zentauren. Bei unseren kurzen Ausflügen ins Brachland haben wir ihre Lager und Besitztümer im ganzen Gebiet verstreut gefunden.\n\nIch werde Falgran Hastil, einen unserer Spurenleser, ausschicken, um nachzusehen, wohin die Spuren führen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27263] = { id = 27263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leutnant Paval Reethe", description = "Unter dem Geröll erregt ein Funkeln Eure Aufmerksamkeit. Nachdem Schmutz und Asche von dem Objekt gewischt wurden, kommt das Emblem eines goldenen Ankers auf einer weißen Emailleoberfläche zum Vorschein: das Zeichen von Theramore.\n\nUnter dem Anker ist der Name \"Leutnant Paval Reethe\" eingeprägt.", sourceObjective = "Bringt Reethes Abzeichen zu Hauptmann Garran Mumm in Theramore.", completion = "Das Abzeichen einer Wache bringt nie gute Neuigkeiten mit sich.\n\nManchmal handelt es sich um jemanden, der im Kampf gefallen ist, und dann liegt es an mir, die Nachrichten der trauernden Familie zukommen zu lassen. Manchmal finden wir nicht einmal heraus, was passiert ist. Und dann gibt es noch Situationen, die sogar schlimmer sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[27264] = { id = 27264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leutnant Paval Reethe", description = "Ich kenne den Namen Leutnant Paval Reethe nicht. Am besten erkundigt Ihr Euch bei Adjutant Tesoran. Er hat alle Aufzeichnungen über die Wachen von Theramore, vom Personal bis hin zur Ausrüstung.\n\nEr sollte Euch nach einem Blick in seine Bücher sagen können, wer dieser Reethe ist.", sourceObjective = "Findet bei Adjutant Tesoran in Theramore mehr über Reethe heraus.", completion = "Hallo, {name}. Möchtet Ihr Informationen über ein bestimmtes Mitglied der Wache von Theramore? Reethe, sagt Ihr?\n\nGebt mir einen Moment, damit ich das richtige Buch suchen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[27265] = { id = 27265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Grayson Schattenbruch", description = "Lord Grayson Schattenbruch, einer der führenden Paladine im Realm, hat Euch zu einem persönlichen Gespräch aufgefordert. Ich weiß nicht, was er vorhat, aber ich glaube, er ist von Eurem raschen Fortschritt beeindruckt.\n\nIhr solltet Euch umgehend nach Sturmwind aufmachen und ihn in der Kathedrale des Lichts aufsuchen.", sourceObjective = "Sprecht mit Lord Grayson Schattenbruch in der Kathedrale des Lichts in Sturmwind.", completion = "Es erfreut mich, dass meine Nachricht Euch erreicht hat, {name}. Wir haben viel zu besprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27266] = { id = 27266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wulf ruft", description = "Wulf Hansreim beaufsichtigt die Ausbildung und Koordination der Jäger im Dienst von Sturmwind. Er hat Euch zu einem persönlichen Gespräch gebeten. Reist nach Sturmwind, sobald es Euch möglich ist, und verlasst das Altstadtviertel durch das südliche Tor, um zu seinem Quartier zu gelangen.\n\nIch weiß nicht, was er vorhat, aber ich glaube, er ist von Eurem raschen Fortschritt beeindruckt.", sourceObjective = "Sprecht mit Wulf Hansreim in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[27267] = { id = 27267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nehmt zum SI:7 Kontakt auf", description = "Es scheint, als zeigten die Anführer von SI:7 Interesse an Eurem Fortschritt und Euren Diensten für die Allianz. Osborne der Nachtmensch, ein hochrangiges Mitglied von SI:7, wünscht ein Gespräch mit Euch. Ihr findet ihn im südlichen Teil von Sturmwinds Altstadt.\n\nIch weiß nicht, was Osborne von Euch will, aber es schien wichtig.", sourceObjective = "Sprecht mit Osborne dem Nachtmensch in Sturmwinds Altstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27268] = { id = 27268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eilt zur Kathedrale", description = "Ich habe eine dringende Nachricht aus Sturmwind für Euch, {name}. Es scheint, als wünsche Hohepriesterin Laurena Euch in der Kathedrale des Lichts am Kathedralenplatz in Sturmwind zu sprechen. Der Botschafter lies nicht verlauten, um welches Anliegen es gehe, doch er gab den Rat, die Reise nach Sturmwind nicht aufzuschieben.", sourceObjective = "Sprecht mit Hohepriesterin Laurena in der Kathedrale des Lichts in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[27269] = { id = 27269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tempel des Mondes", description = "Ich habe eine dringende Nachricht aus Darnassus für Euch. Die Nachricht ist von der Hohepriesterin Elunes, Tyrande Wisperwind, persönlich! Der Botschafter lies nicht verlauten, um welches Anliegen es gehe, doch er gab den Rat, die Reise zum Tempel des Mondes in Darnassus nicht aufzuschieben und die Hohepriesterin so schnell wie möglich zu treffen.", sourceObjective = "Sprecht mit Tyrande Wisperwind im Tempel des Mondes in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[27270] = { id = 27270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Audienz bei der Scharfseherin", description = "Ich habe eine dringende Nachricht aus Sturmwind für Euch, {name}. Es sieht aus, als würde Scharfseherin Umbrua darum bitten, mit Euch zu sprechen, wenn Ihr das nächste Mal in der Stadt seid.\n\nDer Bote hat mir keine Erklärung für die Einladung der Scharfseherin gegeben, aber Ihr solltet nach Sturmwind reisen und Scharfseherin Umbrua im Goldenen Fass im Zwergenviertel treffen, sobald Ihr könnt.", sourceObjective = "Sprecht mit Scharfseherin Umbrua im Gasthaus Zum Goldenen Fass im Zwergendistrikt in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[27271] = { id = 27271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise zum Sanktum des Magiers", description = "Soeben kam eine Nachricht aus Sturmwind an, {name}. Einer der angesehensten Magier Sturmwinds, Maginor Dumas, hat Euch zu einem Besuch im Magierviertel in Sturmwind eingeladen. Ihr werdet ihn im Sanktum des Magiers oben auf dem großen Turm im Herzen des Magierviertels finden.\n\nIch weiß nicht, was er vorhat, aber ich glaube, er ist von Eurem raschen Fortschritt beeindruckt.", sourceObjective = "Sprecht mit Maginor Dumas im Sanktum des Magiers in Sturmwinds Magierviertel.", sourceObjectiveStatus = "unverified-source-field" }
quests[27272] = { id = 27272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demisette schickt Kunde", description = "Es scheint, als haben die Ältesten in unseren Rängen von Euren Fortschritten und Eurer Hingabe erfahren, {name}. Demisette Cloyce, eine der ältesten und geachtetsten Mitglieder unseres Kreises, hat Kunde geschickt, dass Sie Euch sprechen möchte. Ihr solltet eine Einladung wie diese sehr ernst nehmen. Die Meisten sprechen nur während ihrer Kurse mit ihr, aber wenn Sie Euch zu einem persönlichen Gespräch lädt, muss es sich um etwas Wichtiges handeln.\n\nEilt zurück nach Sturmwind und sucht sie im Gasthaus \"Zum Geschlachteten Lamm\" im Magierviertel auf.", sourceObjective = "Sprecht mit Demisette Cloyce im Gasthaus \"Zum Geschlachteten Lamm\" in Sturmwinds Magierviertel.", sourceObjectiveStatus = "unverified-source-field" }
quests[27273] = { id = 27273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Einladung aus Mondlichtung", description = "Ihr habt den Botschafter aus Mondlichtung gerade verpasst, {name}. Er hat wenig Preis gegeben, meinte aber, er habe eine dringende Nachricht von Loganaar, einem der ehrwürdigen Ausbilder des Zirkel des Cenarius. Brecht umgehend nach Mondlichtung auf, {name}. Es scheint sich um eine wichtige Angelegenheit zu handeln.\n\nIhr werdet Loganaar in dem Dorf Nachthafen auffinden.", sourceObjective = "Sprecht mit Loganaar in Nachthafen in Mondlichtung.", completion = "Gut, dass Ihr sicher in Nachthafen angekommen seid, {name}. Ich heiße Euch mit der Gastfreundschaft des Zirkel des Cenarius willkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27274] = { id = 27274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Chefchirurgin", description = "Ich habe eine dringende Nachricht aus Sturmwind für Euch, {name}. Chefchirurgin Schnittschweißer hat Euch gebeten, sie in Sturmwind aufzusuchen. Die Nachricht gibt keinerlei Informationen über das Anliegen der Chefchirurgin, Ihr solltet die Reise nach Sturmwind jedoch nicht aufschieben. Sucht Chefchirurgin Schnittschweißer im Zwergendistrikt der Stadt auf.", sourceObjective = "Sprecht mit Chefchirurgin Schnittschweißer im Zwergendistrikt in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[27275] = { id = 27275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiedervereint", description = "Wir haben uns darum gekümmert, die Schildwache zu heilen und neu auszustatten. Ich habe sie bereits wieder zum Einsatz geschickt.\n\nGeht zurück nach Düsterwolkengipfel. Sie wird Euch dort treffen.", sourceObjective = "Sprecht mit der Schildwache von Feralas in Düsterwolkengipfel in Tausend Nadeln.", completion = "Schön Euch wiederzusehen, {name}. Lasst uns den Grimmtotem Angst vor der Göttin einjagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27276] = { id = 27276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiedervereint", description = "Wir haben uns darum gekümmert, den Kriegerhelden zu heilen und neu auszustatten. Ich habe ihn bereits wieder zum Einsatz geschickt.\n\nGeht zurück nach Düsterwolkengipfel. Er wird Euch dort treffen.", sourceObjective = "Sprecht mit dem Kriegerheld des Freiwindpostens in Düsterwolkengipfel in Tausend Nadeln.", completion = "Ich fühle mich durch Eure Gegenwart geehrt, {name}. Lasst uns den Grimmtotem Angst vor der Erdenmutter einjagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27277] = { id = 27277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Audienz bei Ureda", description = "Ich habe eine dringende Nachricht aus Orgrimmar für Euch, {name}. Die berühmte Magierin Ureda wünscht, Euch in Orgrimmar zu empfangen. Ich bin mir nicht sicher, worum es hier geht, aber wenn ich Ihr wäre, würde ich so schnell wie möglich in die Hauptstadt reisen und Ureda in der Kluft der Schatten aufsuchen.", sourceObjective = "Sprecht mit Ureda in der Kluft der Schatten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27278] = { id = 27278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Grimmschlag", description = "Ein Bote aus Orgrimmar hat gerade eine Nachricht für Euch gebracht. Ich soll Euch ausrichten, dass Ormak Grimmschlag, der Jägerlehrer aus Orgrimmar, Euch treffen möchte.\n\nReist schnell nach Orgrimmar und sucht Ormak im Tal der Ehre auf.", sourceObjective = "Sprecht mit Ormak Grimmschlag im Tal der Ehre.", sourceObjectiveStatus = "unverified-source-field" }
quests[27279] = { id = 27279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zerschmetterte Hand", description = "Ein Bote aus Orgrimmar kam gerade mit einer Mitteilung für Euch an. Gordul, der leitende Schurkenlehrer aus Orgrimmar, schickt nach Euch. Ihr müsst Euch sofort nach Orgrimmar begeben und ihn in der Kluft der Schatten aufsuchen.\n\nWenn Gordul ein Treffen einberuft, ist es weise, der Aufforderung zu folgen. Lasst ihn nicht warten, {name}.", sourceObjective = "Sprecht mit Gordul in der Kluft der Schatten in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[27280] = { id = 27280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Traumsucher ruft", description = "Kardris Traumsucher, eine Schamanin, deren Weisheit bei der Horde legendär ist, hat Kunde geschickt, dass sie Euch sprechen möchte. Der Botschafter ließ nicht verlauten, was so dringlich sei. Er meinte nur, Ihr solltet schnellstmöglich nach Orgrimmar aufbrechen und Kardris im Tal der Weisheit aufsuchen. Sie wird dort mit anderen Ausbildern zusammentreffen, um junge Schamanen zu unterrichten.", sourceObjective = "Sprecht mit Kardris Traumsucher im Tal der Weisheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[27281] = { id = 27281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grezz Zornfaust", description = "Soeben kam die Nachricht, dass Ihr in Orgrimmar gebraucht werdet, {name}. Grezz Zornfaust, der ehrenhafte Kriegerlehrer der Stadt, hat nach Euch verlangt. Diese Aufforderung zu ignorieren wäre unklug.\n\nReist schnell nach Orgrimmar zum Tal der Ehre, wo Grezz auf Eure Ankunft wartet.", sourceObjective = "Sprecht mit Grezz Zornfaust im Tal der Ehre.", sourceObjectiveStatus = "unverified-source-field" }
quests[27282] = { id = 27282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zevrosts Befehl", description = "{name}, soeben kam die Nachricht, dass Ihr wieder in Orgrimmar gebraucht werdet. Zevrost, einer der erfahrensten Hexenmeisterlehrer in der Kluft der Schatten, hat etwas Wichtiges mit Euch zu besprechen. Es scheint sich um etwas zu handeln, dass nicht aufgeschoben werden kann.\n\nMacht Euch auf den Weg und geht zurück nach Orgrimmar. Sprecht so bald wie möglich mit ihm.", sourceObjective = "Sprecht mit Zevrost in der Kluft der Schatten in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[27283] = { id = 27283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Reise nach Mondlichtung", description = "Wie Ihr sicher wisst, ist Mondlichtung die Heimat des Zirkel des Cenarius, der Bruderschaft der Druiden. Alle Bewohner leben dort unter dem Frieden des Cenarius. Ausbilder Loganaar hat die Einladung nach Mondlichtung unter Anbetracht dieser Tatsache ausgesprochen.\n\nIhr werdet ihn in dem Dorf Nachthafen auffinden.", sourceObjective = "Sprecht mit Loganaar in Nachthafen.", completion = "Willkommen in Mondlichtung, {name}. Ich habe mich auf unser Treffen gefreut.", sourceObjectiveStatus = "unverified-source-field" }
quests[27284] = { id = 27284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarze Schild", description = "Ich kann Euch leider nicht weiterhelfen, {name}, aber ich kann Euch verraten, wer Euch helfen könnte. Caz Doppelspross, einer unserer besten Schmiede, arbeitet in der Schmiede.\n\nBringt ihm den Schild und hört Euch an, was er zu sagen hat.", sourceObjective = "Zeigt den geschwärzten Eisenschild Caz Doppelspross in Theramore.", progress = "Etwas, dass ich mir anschauen soll?", completion = "Hm ... das ist ein interessantes Stück Eisen! Ganz sicher wurde der Schild von keinem der Schmiede hergestellt, die ich auf dieser Seite des Meeres kenne. Und ich kann auch mit Sicherheit sagen, dass die Arbeit nicht von mir stammt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27285] = { id = 27285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarze Schild", description = "Ah, das hier hätte ich fast übersehen ... Der Lederriemen auf der Rückseite hat das Feuer wohl nicht überstanden, aber ich glaube, er wurde für eine große Person angefertigt. Ich würde auf einen Tauren tippen.\n\nAber mehr kann ich leider auch nicht ausmachen. Sagt Hauptmann Mumm, es tut mir leid, dass ich nicht mehr helfen konnte.", sourceObjective = "Sprecht mit Hauptmann Garran Mumm in Theramore.", completion = "Das ist nicht viel, mit dem wir etwas anfangen können, aber wir werden es im Kopf behalten. Hoffentlich werden uns noch andere Informationen etwas mehr Klarheit verschaffen und uns einen Überblick über das, was geschehen ist, verschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27286] = { id = 27286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daelins Männer", description = "Reddon ... Oh, da haben wir ihn! Leutnant Paval Reethe.\n\nTrat den Wachen von Theramore zusammen mit den meisten Rekruten bei, die mit Lady Prachtmeer über das Meer kamen. Trat mit sechzehn Jahren den Marinesoldaten von Kul Tiras bei. Herausragende Dienste, Beförderungen ...\n\nIst als vermisst eingetragen.", sourceObjective = "Kehrt mit den Informationen über Reethe zu Hauptmann Garran Mumm in Theramore zurück.", completion = "Vermisst? Das ist Tesorans Art, \"Verräter\" zu sagen.\n\nZweifellos ist er einer dieser Narren, die Admiral Daelin so blindlings treu ergeben sind, dass sie zu Verrätern wurden. Ist das nicht eine delikate Ironie? Die Deserteure beschuldigen uns, die Allianz zu verraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27287] = { id = 27287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Deserteure", description = "Es war ein ständiger Kampf, in den Marschen präsent zu bleiben, aber durch die Kraft unserer Entschlossenheit konnten wir mehrere Wachtürme in diesem Gebiet zur Verteidigung halten.\n\nDie aktuellsten Informationen und Späherberichte, die ich bekam, deuten darauf hin, dass eine Gruppe Deserteure sich in unserem alten Turm bei der Verlassenen Wacht, südöstlich des Gasthauses, eingenistet hat.\n\nDer örtliche Anführer der Deserteure ist ein Mann namens Balos Jacken. Seht zu, ob Ihr Informationen von ihm bekommen könnt.\n\nSeid gewarnt, {name}. Er könnte sich als harte Nuss herausstellen.", sourceObjective = "Sammelt Informationen über Reethe von Balos Jacken und den Deserteuren in Düstermarschen.", completion = "Hat Mumm Euch geschickt? Konnte seine schmutzige Arbeit nicht selber machen, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[27288] = { id = 27288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Deserteure", description = "Reethe? Der Feigling?\n\nWir warfen ihn aus dem Lager hinaus, weil er dauernd die Vorräte der Oger in Brackenwall plündern wollte. So viele sind wir nicht, als dass wir es mit diesen hirnlosen Schlägern aufnehmen könnten.\n\nEr hat das Fass zum Überlaufen gebracht, daher haben wir ihn sich selbst überlassen.\n\nNun, ich habe Euch also geholfen ... Nun könnt Ihr uns helfen und vergessen, dass Ihr uns gefunden habt.", sourceObjective = "Sprecht mit Hauptmann Garran Mumm in Theramore über Reethe.", completion = "Ich werde Leutnant Kaldenbrunn schicken, damit er sich um die Deserteure an der Verlassenen Wacht kümmert. Zusätzlich werde ich ihn instruieren, Reethe zu suchen. Die Marschen sind nicht so groß und auch dort gibt es Spuren. Es sollte ihm nicht allzu schwerfallen, ihn zu finden.", sourceObjectiveStatus = "unverified-source-field" }
